    [ "$r0" = RAN-ONCE ] && [ "$r1" = "$r0" ] || gwd="$gwd replay-did-not-return-the-first-reply($r0|$r1)"
    [ "$(ls "$W/state/gateway/ledger" | wc -l | tr -d ' ')" = 1 ] || gwd="$gwd ledger-has-$(ls "$W/state/gateway/ledger" | wc -l | tr -d ' ')-entries"
