    _gw_caught _gw_c_real_load plugin fourth-verb-in-real-hermes __init__.py '"park": "gate-park.sh",' '"park": "gate-park.sh", "complete": "gate-accept.sh",' || mnot="$mnot fourth-verb-in-real-hermes"
