    gate="$(HERMES_HOME="$H" hermes kanban --board ck create "GATE-M1: held" --initial-status blocked --json 2>/dev/null | jq -r '.id // empty')"
    [ -n "$gate" ] || { gwd="$gwd gate-create-failed"; return; }
