  {tool:"execute_code", args:{code: ("import subprocess\nsubprocess.run(['" + $s + "','kanban','--board','ck','complete','" + $g + "'])")}},
  {tool:"kanban_complete", args:{task_id:$g, summary:"x", result:"x"}},
