    gwd=""; _gw_c_busy
    mnot=""
    _gw_caught _gw_c_busy plugin guard-cut __init__.py '        return _decide(tool_name, args, task_id)' '        return None' 'the-board-changed' || mnot="$mnot guard-cut"
    _gw_caught _gw_c_busy plugin relative-uses-the-process-cwd __init__.py '        return str(_resolve_path_for_task(path, task_id or "default"))' '        return os.path.abspath(path)' 'relative-protected-was-not-refused' || mnot="$mnot relative-uses-the-process-cwd"
    _gw_caught _gw_c_busy plugin v4a-move-destination-unread __init__.py '        if getattr(op, "new_path", None):' '        if False:' 'v4a-protected-patch-was-not-refused' || mnot="$mnot v4a-move-destination-unread"
    _gw_caught _gw_c_busy plugin the-gate-profile-is-ordinary __init__.py '        if _is_gate_session():' '        if False:' 'forge-gate-turn-was-not-refused-whole' || mnot="$mnot the-gate-profile-is-ordinary"
    _gw_caught _gw_c_busy plugin guard-is-off-for-telegram __init__.py '        return platform not in _NON_MESSAGING' '        return False' 'the-board-changed' || mnot="$mnot guard-is-off-for-telegram"
    if [ -z "$gwd" ] && [ -z "$mnot" ]; then ok "busy-text-never-writes-a-gate (in an isolated HERMES_HOME with the plugin enabled and the session bound as a ContextVar, ten calls a model could make with a verb's text in hand — terminal and execute_code naming the hermes CLI and the board file, and five kanban_* tools — each come back as the guard's own refusal, the stub is never called and a real board is byte-identical; echo, a read and kanban_show still work; two mutants caught: with the guard cut the same calls reach the stub and complete the gate)"
    else bad "busy-text-never-writes-a-gate" "a verb that reaches the agent as text must not become a board write on a gate card:${gwd}; mutants not caught:${mnot:- none}"; fi
  else
    skip "busy-text-never-writes-a-gate" "needs the Hermes venv at ~/.hermes/hermes-agent and hermes on PATH"
  fi

  # ======================================================================
  # forge-gate-profile-has-no-tools  (the real bootstrap into a scratch root, then Hermes' own resolver)
  # ======================================================================
  _gw_probe() { # home -> JSON on stdout
    HERMES_HOME="$1" "$hpy" -I "${GW_PROBE:-$REPO_ROOT/scripts/gateway-toolset-probe.py}" --platform telegram 2>/dev/null
  }
  # The bootstrap, for forge-gate alone, into a scratch Hermes root AND a scratch HOME (so `hermes profile create` writes no
  # wrapper into the real ~/.local/bin). $1 = the bootstrap to run, $2 = the scratch name. Sets GP_HOME (the root).
  _gw_gate_boot() {
    GP_HOME="$root/gp-$2"; rm -rf "$GP_HOME" "$root/gph-$2"; mkdir -p "$GP_HOME" "$root/gph-$2"
    HOME="$root/gph-$2" HERMES_HOME="$GP_HOME" FORGE_PROFILES_ONLY=forge-gate bash "$1" >"$root/gp-$2.out" 2>&1
  }
  _gw_c_gateprofile() {
    local boot="${GW_BOOT:-$REPO_ROOT/hermes/profiles-bootstrap.sh}" j f cfg
    _gw_gate_boot "$boot" real || gwd="$gwd bootstrap-failed($(tail -3 "$root/gp-real.out" | tr '\n' ' ' | head -c 300))"
    j="$(_gw_probe "$GP_HOME")"
    f='.forge_gate'
    printf '%s' "$j" | jq -e "$f != null and $f.explicit == true and ($f.tools | length) == 0 and ($f.write_tools | length) == 0
          and ($f.toolsets | length) == 0 and $f.mcp_servers == 0 and $f.plugin_enabled == true and $f.plugin_link == true
          and $f.unauthorized_dm_behavior == \"ignore\" and $f.own_token == false and $f.allowed_users == \"none\"" >/dev/null 2>&1 \
      || gwd="$gwd forge-gate-as-hermes-resolves-it($(printf '%s' "$j" | jq -c '.forge_gate' 2>/dev/null | head -c 400))"
    cmp -s "$GP_HOME/profiles/forge-gate/SOUL.md" "$REPO_ROOT/hermes/profiles/forge-gate.SOUL.md" || gwd="$gwd the-soul-was-not-installed"
    [ ! -e "$root/gph-real/.local/bin/forge-gate" ] || gwd="$gwd a-wrapper-was-created"
    ! grep -q 'TELEGRAM_BOT_TOKEN\|TELEGRAM_ALLOWED_USERS' "$GP_HOME/profiles/forge-gate/.env" 2>/dev/null || gwd="$gwd the-script-wrote-a-secret"
    [ "$(readlink "$GP_HOME/profiles/forge-gate/plugins/forge-gateway")" = "$(cd "$(dirname "$boot")/.." && pwd)/hermes/plugins/forge-gateway" ] || gwd="$gwd the-plugin-link-points-elsewhere"
    grep -q '"forge-gate|[^|]*|"$' "$boot" || gwd="$gwd the-bootstrap-gives-forge-gate-a-toolset"
    # Controls: the same profile with one thing changed. Each must be SEEN by the probe, or "empty" proves nothing.
    cfg="$GP_HOME/profiles/forge-gate/config.yaml"
    cp "$cfg" "$cfg.good"
    sed '/^platform_toolsets:/,/^  telegram: \[\]/d' "$cfg.good" > "$cfg"
    j="$(_gw_probe "$GP_HOME")"; printf '%s' "$j" | jq -e '.forge_gate.explicit == false and (.forge_gate.write_tools | length) > 0' >/dev/null 2>&1 || gwd="$gwd no-entry-is-not-the-default-bundle($(printf '%s' "$j" | jq -c '.forge_gate' | head -c 160))"
    sed 's/^  telegram: \[\]/  telegram: [hermes-telegram]/' "$cfg.good" > "$cfg"
    j="$(_gw_probe "$GP_HOME")"; printf '%s' "$j" | jq -e '.forge_gate.explicit == true and (.forge_gate.write_tools | length) > 0' >/dev/null 2>&1 || gwd="$gwd the-bundle-form-is-not-seen"
    sed 's/^  telegram: \[\]/  telegram: [clarify]/' "$cfg.good" > "$cfg"
    j="$(_gw_probe "$GP_HOME")"; printf '%s' "$j" | jq -e '(.forge_gate.tools | length) > 0' >/dev/null 2>&1 || gwd="$gwd one-harmless-tool-is-not-seen"
    sed 's/^  telegram: \[\]/  telegram: [web]/' "$cfg.good" > "$cfg"
    j="$(_gw_probe "$GP_HOME")"; printf '%s' "$j" | jq -e '(.forge_gate.tools | length) > 0 and (.forge_gate.write_tools | length) == 0' >/dev/null 2>&1 || gwd="$gwd a-read-only-tool-is-not-told-from-a-write"
    { cat "$cfg.good"; printf 'mcp_servers:\n  github:\n    command: x\n'; } > "$cfg"
    j="$(_gw_probe "$GP_HOME")"; printf '%s' "$j" | jq -e '.forge_gate.mcp_servers == 1' >/dev/null 2>&1 || gwd="$gwd an-mcp-server-is-not-seen"
    grep -v '^unauthorized_dm_behavior' "$cfg.good" > "$cfg"
    j="$(_gw_probe "$GP_HOME")"; printf '%s' "$j" | jq -e '.forge_gate.unauthorized_dm_behavior == null' >/dev/null 2>&1 || gwd="$gwd pairing-codes-are-not-seen"
    cp "$cfg.good" "$cfg"
    # Another profile with the gate verbs enabled and tools of its own is seen too (the preflight FAILs it), and a token or
    # allowlist is reported as a fact and never as a value.
    mkdir -p "$GP_HOME/profiles/p9"
    printf 'plugins:\n  enabled:\n    - forge-gateway\n' > "$GP_HOME/profiles/p9/config.yaml"
    printf 'TELEGRAM_BOT_TOKEN=tok-fake-0123456789\nTELEGRAM_ALLOWED_USERS=1,*\n' > "$GP_HOME/profiles/p9/.env"
    printf 'TELEGRAM_BOT_TOKEN=tok-fake-0123456789\n' > "$GP_HOME/.env"
    j="$(_gw_probe "$GP_HOME")"
    printf '%s' "$j" | jq -e '.profiles.p9.plugin_enabled == true and (.profiles.p9.write_tools | length) > 0 and .profiles.p9.explicit == false
          and .profiles.p9.own_token == true and .profiles.p9.token_shared_with_root == true and .profiles.p9.allowed_users == "star"' >/dev/null 2>&1 \
      || gwd="$gwd another-profile-with-the-verbs-and-tools-is-not-seen($(printf '%s' "$j" | jq -c '.profiles.p9' | head -c 300))"
    printf '%s' "$j" | grep -q 'tok-fake' && gwd="$gwd the-probe-printed-a-token"
    rm -rf "$GP_HOME" "$root/gph-real"
  }
  if [ "$hermes_ok" = 1 ]; then
    gwd=""; _gw_c_gateprofile
    mnot=""
    local bm="$root/mut-boot"; rm -rf "$bm"; mkdir -p "$bm/hermes/profiles" "$bm/scripts" "$bm/skills" "$bm/hermes/plugins"
    cp "$REPO_ROOT/scripts/model-pins.sh" "$bm/scripts/"; cp "$REPO_ROOT"/hermes/profiles/*.SOUL.md "$bm/hermes/profiles/"
    cp -R "$REPO_ROOT/hermes/plugins/forge-gateway" "$bm/hermes/plugins/"; rm -rf "$bm/hermes/plugins/forge-gateway/__pycache__"
    local s2; for s2 in $(cd "$REPO_ROOT/skills" && ls -d */ 2>/dev/null | tr -d '/'); do mkdir -p "$bm/skills/$s2"; done
    local mk
    for mk in no-platform-toolsets no-ignore-for-strangers plugin-not-enabled makes-a-wrapper; do
      cp "$REPO_ROOT/hermes/profiles-bootstrap.sh" "$bm/hermes/profiles-bootstrap.sh"
      case "$mk" in
        no-platform-toolsets)     _gw_mut "$bm/hermes/profiles-bootstrap.sh" '      echo "platform_toolsets:"
      echo "  telegram: []"' '      echo "# nothing here"';;
        no-ignore-for-strangers)  _gw_mut "$bm/hermes/profiles-bootstrap.sh" '      echo "unauthorized_dm_behavior: ignore"' '      echo "# default"';;
        plugin-not-enabled)       _gw_mut "$bm/hermes/profiles-bootstrap.sh" '      echo "    - forge-gateway"' '      echo "    - nothing"';;
        makes-a-wrapper)          _gw_mut "$bm/hermes/profiles-bootstrap.sh" 'hermes profile create "$name" --no-alias --no-skills' 'hermes profile create "$name" --no-skills';;
      esac || { gwd="$gwd mutant-$mk-did-not-apply"; continue; }
      local keep="$gwd"; gwd=""
      GW_BOOT="$bm/hermes/profiles-bootstrap.sh" _gw_c_gateprofile
      [ -n "$gwd" ] || mnot="$mnot $mk"
      gwd="$keep"
    done
    GW_BOOT=""
    if [ -z "$gwd" ] && [ -z "$mnot" ]; then ok "forge-gate-profile-has-no-tools (the real bootstrap into a scratch root: forge-gate resolves, through Hermes' own resolver, to an explicit EMPTY Telegram toolset, no MCP server, the plugin linked and enabled, strangers ignored, its SOUL installed, no wrapper, no secret written; a missing entry (the default bundle), the bundle form, one harmless tool, an MCP server and pairing codes are each seen; a read-only tool is told from a write; another profile with the verbs and tools is seen; no token is printed; four mutants caught)"
    else bad "forge-gate-profile-has-no-tools" "the dedicated gate bot must resolve to no tools at all, as Hermes resolves it:${gwd}; mutants not caught:${mnot:- none}"; fi
  else
    skip "forge-gate-profile-has-no-tools" "needs the Hermes venv at ~/.hermes/hermes-agent and hermes on PATH"
  fi

  # ======================================================================
  # deployed-forge-gate-has-no-tools  (the live host; pending until the operator's steps)
  # ======================================================================
  if [ "$hermes_ok" != 1 ] || [ ! -f "$HOME/.hermes/config.yaml" ]; then
    skip "deployed-forge-gate-has-no-tools" "no installed Hermes with a config to read"
  else
    local lj lbad lverbs; lj="$(_gw_probe "$HOME/.hermes")"
    if ! printf '%s' "$lj" | jq -e '.platform == "telegram"' >/dev/null 2>&1; then
      bad "deployed-forge-gate-has-no-tools" "the probe could not ask Hermes about the live Telegram toolsets: $(printf '%s' "$lj" | head -c 300)"
    else
      # live = the gate verbs are enabled anywhere; bad = forge-gate is unsafe; verbs = a profile OTHER than forge-gate that has them and tools
      lbad="$(printf '%s' "$lj" | jq -r 'if .forge_gate == null then "" else
              ([ (if .forge_gate.explicit then empty else "no-explicit-toolset" end),
                 (if (.forge_gate.tools | length) == 0 then empty else "holds:" + (.forge_gate.tools | join(",")) end),
                 (if .forge_gate.mcp_servers == 0 then empty else "mcp-servers" end),
                 (if .forge_gate.unauthorized_dm_behavior == "ignore" then empty else "answers-strangers" end) ] | join(" ")) end')"
      lverbs="$(printf '%s' "$lj" | jq -r '[.profiles | to_entries[] | select(.key != "forge-gate" and .value.plugin_enabled and (.value.write_tools | length) > 0) | .key] | join(", ")')"
      if [ -n "$lbad" ] || [ -n "$lverbs" ]; then
        bad "deployed-forge-gate-has-no-tools" "the gate bot must have no tools and the verbs must be on it alone: forge-gate [${lbad}]; other profiles with the verbs and tools [${lverbs}]"
      elif [ "$(printf '%s' "$lj" | jq -r '.forge_gate != null')" = true ]; then
        ok "deployed-forge-gate-has-no-tools (the live forge-gate profile has an explicit, empty Telegram toolset, no MCP server and ignores strangers; no other profile has the gate verbs and tools)"
      elif [ "$(printf '%s' "$lj" | jq -r '.plugin_enabled or ([.profiles[]?.plugin_enabled] | any)')" = true ]; then
        bad "deployed-forge-gate-has-no-tools" "the gate verbs are enabled but the forge-gate profile does not exist: the plugin must never be live before forge-gate is"
      else
        skip "deployed-forge-gate-has-no-tools" "operator step pending: there is no forge-gate profile yet and the gate verbs are not enabled anywhere"
      fi
    fi
  fi

  # ======================================================================
  # The cron job and its arming file
  # ======================================================================
  # The product project the checkpoint probes: the checkpoint group's plan, frozen by the real acceptance-freeze,
  # as a git checkout on main (the cron refuses anything else). Variants are copies with one edit to src/reader.py.
  _gw_proj_base() {
    local p="$root/proj-base"
    rm -rf "$p"; mkdir -p "$p/docs/chunks" "$p/tests/features" "$p/tests/probes/m1" "$p/src"
    cat > "$p/docs/chunks/graph.json" <<'GW_GRAPH'
[
  {"id":"CHUNK-1","lane":"claude-interactive","tier":"human","depends_on":[]},
  {"id":"GATE-M1","lane":"claude-interactive","depends_on":["CHUNK-1"]}
]
GW_GRAPH
    cat > "$p/docs/chunks/CHUNK-1.md" <<'GW_CHUNK'
### CHUNK-1: Read records
- **Goal:** Read a record file and stop on a relabelled record.
- **Milestone:** M1 · **Depends on:** none
- **Scenarios:**
  - Given three records, When the reader runs, Then it advances.
- **Real sources:** none
- **Acceptance:** tests/features/chunk_1.feature
- **Lane:** claude-interactive · **Risk:** low
GW_CHUNK
    printf 'Feature: CHUNK-1 acceptance\n\n  Scenario: Read records\n    Given three records\n    When the reader runs\n    Then it advances\n' > "$p/tests/features/chunk_1.feature"
    printf '### GATE-M1: Milestone 1\n- **Milestone:** M1\n- **Probe:** tests/probes/gate_m1.json\n- **Estimate:** 1 chunk\n- **Lane:** claude-interactive\n' > "$p/docs/chunks/GATE-M1.md"
    cat > "$p/src/reader.py" <<'GW_READER'
import sys

records = open(sys.argv[1]).read().split()
foreign = [r for r in records if r == "foreign"]
if foreign:
    print("stop: " + foreign[0])
    sys.exit(3)
print("advance %d" % len(records))
GW_READER
    printf 'a\nb\nc\n' > "$p/tests/probes/m1/corpus.txt"
    printf 'a\nforeign\nc\n' > "$p/tests/probes/m1/relabelled.txt"
    cat > "$p/tests/probes/gate_m1.json" <<'GW_PROBE'
{
  "probe": "forge.probe.v1",
  "milestone": "M1",
  "cases": [
    {"name": "three records advance", "kind": "realistic", "records": 3,
     "input": "tests/probes/m1",
     "run": ["python3", "src/reader.py", "{input}/corpus.txt"],
     "expect": {"exit": 0, "stdout": "advance 3"}},
    {"name": "a relabelled record is stopped", "kind": "adversarial",
     "input": "tests/probes/m1",
     "run": ["python3", "src/reader.py", "{input}/relabelled.txt"],
     "expect": {"exit": 3, "stdout": "stop: foreign"}}
  ]
}
GW_PROBE
    "$REPO_ROOT/scripts/acceptance-freeze.sh" "$p" >"$p.freeze.log" 2>&1
  }
  _gw_proj() { # name [sed expression on src/reader.py]: a committed checkout on main
    local d="$root/proj-$1"
    rm -rf "$d"; cp -R "$root/proj-base" "$d"
    [ -z "${2:-}" ] || { sed -i.bak "$2" "$d/src/reader.py"; rm -f "$d/src/reader.py.bak"; }
    ( cd "$d" && git init -q -b main . && git add -A && git -c user.email=gw@forge -c user.name=gw commit -qm fixture ) >/dev/null 2>&1
  }
  _gw_proj_with() { # name prelude: a committed checkout whose reader.py (the probe runs it) begins with the prelude
    local d="$root/proj-$1"
    rm -rf "$d"; cp -R "$root/proj-base" "$d"
    { printf '%s\n' "$2"; cat "$root/proj-base/src/reader.py"; } > "$d/src/reader.py"
    ( cd "$d" && git init -q -b main . && git add -A && git -c user.email=gw@forge -c user.name=gw commit -qm fixture ) >/dev/null 2>&1
  }
  # The cron under test (the real one, or the mutant in GW_REPO) in a directory of its own, beside a checkpoint.sh
  # that counts the runs it is asked for and then hands over to the real one ($2 = an exit code to return instead).
  _gw_cronrepo() { # name [fault-exit-code]
    local src="${GW_REPO:-$REPO_ROOT}" d="$root/cr-$1" f
    rm -rf "$d"; mkdir -p "$d/scripts"
    for f in checkpoint-cron checkpoint-arm gate-reply forge-state board-snapshot; do cp "$src/scripts/$f.sh" "$d/scripts/"; done
    : > "$d/runs.log"
    if [ -n "${2:-}" ]; then
      printf '#!/bin/sh\necho "$*" >> "%s/runs.log"\necho "boom" >&2\nexit %s\n' "$d" "$2" > "$d/scripts/checkpoint.sh"
    else
      printf '#!/bin/sh\necho "$*" >> "%s/runs.log"\nexec "%s/scripts/checkpoint.sh" "$@"\n' "$d" "$src" > "$d/scripts/checkpoint.sh"
    fi
    chmod +x "$d/scripts/"*.sh
    printf '%s' "$d"
  }
  _gw_tick() { # world cronrepo -> cout, crc
    cout="$(cd / && env HERMES_HOME="$1/home" FORGE_STATE_ROOT="$1/state" GW_STUB_LOG="$1/stub.log" GW_WLOG="$1/wlog.log" \
              GW_STUB_ALLOW="${GW_ALLOW:-}" PATH="$root/bin:$PATH" bash "$2/scripts/checkpoint-cron.sh" 2>"$1/cron.err")"; crc=$?
  }
  _gw_armit() { # world project mode [extra flag] -> the real checkpoint-arm.sh
    ( cd / && env FORGE_STATE_ROOT="$1/state" bash "${GW_REPO:-$REPO_ROOT}/scripts/checkpoint-arm.sh" arm --board ck --gate GATE-M1 --project "$2" --mode "$3" ${4:+"$4"} ) >"$1/arm.out" 2>&1
  }
  _gw_runs() { wc -l < "$1/runs.log" | tr -d ' '; }
  local cron_ok=1
  if _gw_proj_base && command -v git >/dev/null 2>&1; then
    _gw_proj pass ''
    _gw_proj find 's/if foreign:/if False:/'
  else
    cron_ok=0
  fi

  # ======================================================================
  # unarmed-gate-never-completes
  # ======================================================================
  _gw_c_unarmed() {
    local W cr h0 n
    GW_ALLOW="complete comment"
    # A: nobody armed it. The probe would pass (5 of 5 chunks done, the cost within its estimate), and nothing happens.
    W="$(_gw_world un-a)"; cr="$(_gw_cronrepo un-a)"; h0="$(_gw_hash "$W")"
    _gw_tick "$W" "$cr"
    [ -z "$cout" ] && [ "$crc" = 0 ] && [ ! -s "$W/stub.log" ] && [ "$(_gw_runs "$cr")" = 0 ] && _gw_nowrites "$W" "$h0" || gwd="$gwd unarmed-did-something(rc=$crc,out=$cout,runs=$(_gw_runs "$cr"))"
    # B: armed rehearse. It probes, says what it would do, and completes nothing.
    W="$(_gw_world un-b)"; cr="$(_gw_cronrepo un-b)"; h0="$(_gw_hash "$W")"
    _gw_armit "$W" "$root/proj-pass" rehearse || gwd="$gwd arm-rehearse-failed($(cat "$W/arm.out"))"
    _gw_tick "$W" "$cr"
    printf '%s' "$cout" | grep -q 'checkpoint: GATE-M1 passes' && printf '%s' "$cout" | grep -q 'rehearsal: nothing was written to the board' && [ "$crc" = 0 ] \
      || gwd="$gwd rehearse-said($crc:$(printf '%s' "$cout" | head -c 200))"
    [ "$(_gw_runs "$cr")" = 1 ] && grep -q -- ' --rehearse --before-complete ' "$cr/runs.log" || gwd="$gwd rehearse-ran-$(cat "$cr/runs.log")"
    _gw_nowrites "$W" "$h0" && [ "$(_gw_status "$W")" = blocked ] || gwd="$gwd rehearse-completed-the-gate"
    # C: armed apply. The same pass completes the gate: exactly one write, and the file goes.
    W="$(_gw_world un-c)"; cr="$(_gw_cronrepo un-c)"
    _gw_armit "$W" "$root/proj-pass" apply
    [ "$?" = 2 ] && [ ! -e "$W/state/checkpoint/armed/ck--GATE-M1" ] || gwd="$gwd apply-armed-without---confirm-release"
    _gw_armit "$W" "$root/proj-pass" apply --confirm-release || gwd="$gwd arm-apply-failed($(cat "$W/arm.out"))"
    printf '%s' "$(cat "$W/arm.out")" | grep -q '^ARMED APPLY: GATE-M1' || gwd="$gwd arm-apply-did-not-shout"
    _gw_tick "$W" "$cr"
    n="$(wc -l < "$W/wlog.log" | tr -d ' ')"
    [ "$crc" = 0 ] && [ "$n" = 1 ] && grep -q '^hermes WRITE complete kanban --board ck complete t_g1 --result checkpoint pass: ' "$W/wlog.log" && [ "$(_gw_status "$W")" = done ] \
      || gwd="$gwd apply-did-not-complete-exactly-once(rc=$crc,writes=$n,status=$(_gw_status "$W"))"
    printf '%s' "$cout" | grep -q 'completed t_g1' || gwd="$gwd apply-said-nothing-about-completing"
    [ ! -e "$W/state/checkpoint/armed/ck--GATE-M1" ] || gwd="$gwd the-gate-stayed-armed-after-completing"
    _gw_tick "$W" "$cr"
    [ -z "$cout" ] && [ "$(_gw_runs "$cr")" = 1 ] || gwd="$gwd a-second-tick-did-something"
    # D: a malformed arming file reads as not armed, whatever it says.
    W="$(_gw_world un-d)"; cr="$(_gw_cronrepo un-d)"; h0="$(_gw_hash "$W")"
    printf 'mode=apply\nproject=%s\nextra=1\n' "$root/proj-pass" > "$W/state/checkpoint/armed/ck--GATE-M1"
    _gw_tick "$W" "$cr"
    printf '%s' "$cout" | grep -q 'malformed, so the gate is NOT armed' && [ "$crc" = 0 ] && [ "$(_gw_runs "$cr")" = 0 ] && _gw_nowrites "$W" "$h0" \
      || gwd="$gwd malformed-arming-acted(rc=$crc,runs=$(_gw_runs "$cr"),out=$(printf '%s' "$cout" | head -c 160))"
    _gw_tick "$W" "$cr"; [ -z "$cout" ] || gwd="$gwd malformed-arming-said-it-twice"
    # E: another gate's arming does nothing to this one; and a disarmed gate is not looked at.
    W="$(_gw_world un-e)"; cr="$(_gw_cronrepo un-e)"; h0="$(_gw_hash "$W")"
    printf 'mode=apply\nproject=%s\n' "$root/proj-pass" > "$W/state/checkpoint/armed/ck--GATE-M2"
    _gw_tick "$W" "$cr"
    [ "$crc" = 0 ] && [ "$(_gw_runs "$cr")" = 0 ] && _gw_nowrites "$W" "$h0" || gwd="$gwd another-gates-arming-acted"
    rm -f "$W/state/checkpoint/armed/ck--GATE-M2"; _gw_armit "$W" "$root/proj-pass" apply --confirm-release
    ( cd / && env FORGE_STATE_ROOT="$W/state" bash "$REPO_ROOT/scripts/checkpoint-arm.sh" disarm --board ck --gate GATE-M1 ) >/dev/null 2>&1
    _gw_tick "$W" "$cr"
    [ -z "$cout" ] && [ "$(_gw_runs "$cr")" = 0 ] && _gw_nowrites "$W" "$h0" || gwd="$gwd a-disarmed-gate-was-looked-at"
    GW_ALLOW=""
  }
  if [ "$cron_ok" = 1 ]; then
    gwd=""; _gw_c_unarmed
    mnot=""
    _gw_caught _gw_c_unarmed scripts rehearse-runs-apply checkpoint-cron.sh 'flag=--rehearse; [ "$mode" = apply ] && flag=--apply' 'flag=--apply' 'rehearse-completed-the-gate' || mnot="$mnot rehearse-runs-apply"
    _gw_caught _gw_c_unarmed scripts malformed-arming-acts gate-reply.sh 'if [ "$(cat "$f"; printf x)" != "$(printf '"'"'mode=%s\nproject=%s\n'"'"' "$GR_ARM_MODE" "$GR_ARM_PROJECT"; printf x)" ]; then' 'if false; then' 'malformed-arming-acted' || mnot="$mnot malformed-arming-acts"
    _gw_caught _gw_c_unarmed scripts apply-needs-no-confirmation checkpoint-arm.sh 'if [ "$MODE" = apply ] && [ "$CONFIRM" != 1 ]; then' 'if false; then' 'apply-armed-without---confirm-release' || mnot="$mnot apply-needs-no-confirmation"
    if [ -z "$gwd" ] && [ -z "$mnot" ]; then ok "unarmed-gate-never-completes (the probe passes and the cost is within its estimate: unarmed, nothing runs or is written; armed rehearse runs the rehearsal and writes nothing; armed apply, which needs --confirm-release, completes exactly once and goes; a malformed or another gate's arming, and a disarmed gate, do nothing; three mutants caught)"
    else bad "unarmed-gate-never-completes" "only a gate armed apply may be completed by the cron:${gwd}; mutants not caught:${mnot:- none}"; fi
  else
    skip "unarmed-gate-never-completes" "the fixture project could not be built (git or the real acceptance-freeze is missing)"
  fi

  # ======================================================================
  # cron-silent-and-exit-0
  # ======================================================================
  _gw_c_silent() {
    local W cr h0 n
    GW_ALLOW="complete comment"
    # World A: the accept path end to end. Before the cron has reported a block there is nothing to answer.
    W="$(_gw_world si-a)"; cr="$(_gw_cronrepo si-a)"
    _gw_armit "$W" "$root/proj-find" apply --confirm-release
    h0="$(_gw_hash "$W")"
    _gw_s "$W" gate-accept.sh --board ck --gate GATE-M1 --apply
    [ "$grc" = 1 ] && _gw_nowrites "$W" "$h0" || gwd="$gwd accept-before-any-report-got-rc$grc"
    _gw_tick "$W" "$cr"
    printf '%s' "$cout" | grep -q "^checkpoint: GATE-M1's probe found a failing case: a relabelled record is stopped" && [ "$crc" = 0 ] \
      || gwd="$gwd block-not-delivered(rc=$crc,out=$(printf '%s' "$cout" | head -c 200))"
    printf '%s' "$cout" | grep '^Reply: ' | grep -Fq '`/accept ck GATE-M1 [why]`' || gwd="$gwd reply-does-not-name-accept"
    [ ! -s "$W/wlog.log" ] || gwd="$gwd a-block-wrote-to-the-board"
    jq -e '.schema == "forge.checkpoint-pending.v1" and .board == "ck" and .gate == "GATE-M1" and .hold == 1 and .outcome == "block"' "$W/state/checkpoint/pending/ck--GATE-M1.json" >/dev/null 2>&1 \
      || gwd="$gwd pending-record-wrong($(head -c 200 "$W/state/checkpoint/pending/ck--GATE-M1.json" 2>/dev/null))"
    _gw_s "$W" gate-accept.sh --board ck --gate GATE-M1 --text "seen it" --apply
    [ "$grc" = 0 ] && [ "$(wc -l < "$W/wlog.log" | tr -d ' ')" = 1 ] && [ "$(_gw_status "$W")" = done ] || gwd="$gwd accept-after-the-report-got-rc$grc($gout)"
    # World B: the standing conditions, each said once.
    W="$(_gw_world si-b)"; cr="$(_gw_cronrepo si-b)"
    _gw_proj b-live 's/if foreign:/if False:/'
    _gw_armit "$W" "$root/proj-b-live" apply --confirm-release
    h0="$(_gw_hash "$W")"
    _gw_tick "$W" "$cr"; [ -n "$cout" ] && [ "$crc" = 0 ] || gwd="$gwd first-tick(rc=$crc)"
    _gw_tick "$W" "$cr"; [ -z "$cout" ] && [ "$crc" = 0 ] || gwd="$gwd second-tick-spoke(rc=$crc,$(printf '%s' "$cout" | head -c 100))"
    _gw_tick "$W" "$cr"; [ -z "$cout" ] && [ "$crc" = 0 ] || gwd="$gwd third-tick-spoke"
    [ "$(_gw_runs "$cr")" = 1 ] || gwd="$gwd probed-$(_gw_runs "$cr")-times-for-one-gate-hold-and-HEAD"
    _gw_nowrites "$W" "$h0" || gwd="$gwd a-block-tick-wrote"
    # A new HEAD within the same hold is probed again; the same failing text is not said again.
    ( cd "$root/proj-b-live" && echo "# note" > NOTES.md && git add NOTES.md && git -c user.email=gw@forge -c user.name=gw commit -qm "a new head" ) >/dev/null 2>&1
    _gw_tick "$W" "$cr"
    [ "$(_gw_runs "$cr")" = 2 ] && [ -z "$cout" ] && [ "$crc" = 0 ] || gwd="$gwd new-head(runs=$(_gw_runs "$cr"),out=$(printf '%s' "$cout" | head -c 100),rc=$crc)"
    # A dirty or non-main checkout is said once and not probed.
    echo x > "$root/proj-b-live/untracked.txt"
    _gw_tick "$W" "$cr"; printf '%s' "$cout" | grep -q 'has uncommitted changes' && [ "$crc" = 0 ] || gwd="$gwd dirty-not-said(rc=$crc,$(printf '%s' "$cout" | head -c 100))"
    _gw_tick "$W" "$cr"; [ -z "$cout" ] && [ "$crc" = 0 ] || gwd="$gwd dirty-said-twice"
    rm -f "$root/proj-b-live/untracked.txt"
    ( cd "$root/proj-b-live" && git checkout -q -b feature ) >/dev/null 2>&1
    _gw_tick "$W" "$cr"; printf '%s' "$cout" | grep -q "not main" && [ "$crc" = 0 ] || gwd="$gwd non-main-not-said(rc=$crc,$(printf '%s' "$cout" | head -c 100))"
    _gw_tick "$W" "$cr"; [ -z "$cout" ] || gwd="$gwd non-main-said-twice"
    ( cd "$root/proj-b-live" && git checkout -q main ) >/dev/null 2>&1
    [ "$(_gw_runs "$cr")" = 2 ] || gwd="$gwd a-bad-checkout-was-probed"
    # A park stops it for this hold; arming again starts over.
    _gw_s "$W" gate-park.sh --board ck --gate GATE-M1 --text "not now" --apply
    [ "$grc" = 0 ] || gwd="$gwd park-got-rc$grc($gout)"
    _gw_tick "$W" "$cr"; [ -z "$cout" ] && [ "$(_gw_runs "$cr")" = 2 ] && [ "$crc" = 0 ] || gwd="$gwd after-a-park(runs=$(_gw_runs "$cr"),out=$(printf '%s' "$cout" | head -c 100))"
    # The decision is a wall of its own: an arming file put back by hand (not through checkpoint-arm.sh, which
    # starts the gate over) must not bring the cron back for a hold that was decided.
    ( cd "$root/proj-b-live" && echo "# later" >> NOTES.md && git add NOTES.md && git -c user.email=gw@forge -c user.name=gw commit -qm "after the park" ) >/dev/null 2>&1
    printf 'mode=rehearse\nproject=%s\n' "$root/proj-b-live" > "$W/state/checkpoint/armed/ck--GATE-M1"
    _gw_tick "$W" "$cr"; [ -z "$cout" ] && [ "$(_gw_runs "$cr")" = 2 ] && [ "$crc" = 0 ] || gwd="$gwd after-a-park-and-a-hand-written-arming(runs=$(_gw_runs "$cr"),out=$(printf '%s' "$cout" | head -c 100))"
    _gw_armit "$W" "$root/proj-b-live" rehearse
    _gw_tick "$W" "$cr"; [ -n "$cout" ] && [ "$(_gw_runs "$cr")" = 3 ] && [ "$crc" = 0 ] || gwd="$gwd after-arming-again(runs=$(_gw_runs "$cr"),rc=$crc)"
    # World C: an unfinished milestone, and a gate that is not held, are silent forever.
    W="$(_gw_world si-c "UPDATE tasks SET status='ready' WHERE id='t_c5';")"; cr="$(_gw_cronrepo si-c)"
    _gw_armit "$W" "$root/proj-pass" apply --confirm-release; h0="$(_gw_hash "$W")"
    _gw_tick "$W" "$cr"; [ -z "$cout" ] && [ "$crc" = 0 ] && [ "$(_gw_runs "$cr")" = 0 ] && _gw_nowrites "$W" "$h0" || gwd="$gwd unfinished-milestone(rc=$crc,runs=$(_gw_runs "$cr"),out=$(printf '%s' "$cout" | head -c 100))"
    W="$(_gw_world si-d "UPDATE tasks SET status='done' WHERE id='t_g1';")"; cr="$(_gw_cronrepo si-d)"
    _gw_armit "$W" "$root/proj-pass" apply --confirm-release; h0="$(_gw_hash "$W")"
    _gw_tick "$W" "$cr"; [ -z "$cout" ] && [ "$crc" = 0 ] && [ "$(_gw_runs "$cr")" = 0 ] && _gw_nowrites "$W" "$h0" || gwd="$gwd gate-not-held(rc=$crc,runs=$(_gw_runs "$cr"))"
    # World E: only the job's own faults are non-zero, and they go to stderr.
    W="$(_gw_world si-e)"; cr="$(_gw_cronrepo si-e 9)"
    _gw_armit "$W" "$root/proj-pass" rehearse
    _gw_tick "$W" "$cr"
    [ "$crc" = 2 ] && [ -z "$cout" ] && grep -q 'checkpoint.sh exited 9' "$W/cron.err" && [ ! -e "$W/state/checkpoint/pending/ck--GATE-M1.json" ] \
      || gwd="$gwd a-fault-was-not-a-fault(rc=$crc,out=$(printf '%s' "$cout" | head -c 100),err=$(head -c 160 "$W/cron.err"))"
    GW_ALLOW=""
  }
  if [ "$cron_ok" = 1 ]; then
    gwd=""; _gw_c_silent
    mnot=""
    _gw_caught _gw_c_silent scripts probes-every-tick checkpoint-cron.sh '  [ ! -e "$probed" ] || continue' '  :' 'probed-' || mnot="$mnot probes-every-tick"
    _gw_caught _gw_c_silent scripts says-it-every-tick checkpoint-cron.sh '  [ "$(cat "$f" 2>/dev/null)" != "$now" ] || return 0' '  :' || mnot="$mnot says-it-every-tick"
    _gw_caught _gw_c_silent scripts ignores-a-decision checkpoint-arm.sh "    if jq -e --argjson h \"\$HOLD\" '.hold == \$h' \"\$STATE/decided/\$(gr_key \"\$BOARD\" \"\$GATE\").json\" >/dev/null 2>&1; then exit 1; fi" '    :' 'after-a-park' || mnot="$mnot ignores-a-decision"
    _gw_caught _gw_c_silent scripts probes-an-unfinished-milestone checkpoint-cron.sh '  [ "$open" = 0 ] && [ "${total:-0}" -gt 0 ] 2>/dev/null || continue' '  :' 'unfinished-milestone' || mnot="$mnot probes-an-unfinished-milestone"
    _gw_caught _gw_c_silent scripts a-fault-exits-zero checkpoint-cron.sh '[ "$FAULT" = 0 ] || exit 2' ':' 'a-fault-was-not-a-fault' || mnot="$mnot a-fault-exits-zero"
    _gw_caught _gw_c_silent scripts no-block-record checkpoint-cron.sh '        && mv -f "$STATE/pending/$key.json.tmp" "$STATE/pending/$key.json" \' '        && true \' 'pending-record-wrong' || mnot="$mnot no-block-record"
    if [ -z "$gwd" ] && [ -z "$mnot" ]; then ok "cron-silent-and-exit-0 (a block is delivered once with the three replies and recorded for its hold, /accept refuses before it and completes after it; repeat ticks say nothing and probe nothing; a new HEAD is probed and a dirty or non-main checkout is said once; a park stops the hold and arming again starts over; an unfinished milestone and a gate that is not held are silent; every tick exits 0 and only the job's own fault does not; six mutants caught)"
    else bad "cron-silent-and-exit-0" "under --no-agent stdout is the message and any non-zero exit an alert, so the job speaks once and fails only for itself:${gwd}; mutants not caught:${mnot:- none}"; fi
  else
    skip "cron-silent-and-exit-0" "the fixture project could not be built (git or the real acceptance-freeze is missing)"
  fi

  # ======================================================================
  # arming-is-explicit
  # ======================================================================
  _gw_c_arming() {
    local W st out rc A="${GW_REPO:-$REPO_ROOT}/scripts/checkpoint-arm.sh"
    W="$(_gw_world arm)"; st="$W/state"
    _a() { out="$(cd / && env FORGE_STATE_ROOT="$st" bash "$A" "$@" 2>&1)"; rc=$?; }
    _a arm --board ck --gate GATE-M1 --project "$root/proj-pass"; [ "$rc" = 2 ] && [ ! -e "$st/checkpoint/armed/ck--GATE-M1" ] || gwd="$gwd arm-with-no-mode(rc=$rc)"
    _a arm --board ck --gate GATE-M1 --project "$root/proj-pass" --mode both; [ "$rc" = 2 ] || gwd="$gwd arm-with-a-bad-mode(rc=$rc)"
    _a arm --board ck --gate GATE-M1 --project "$root/proj-pass" --mode apply; [ "$rc" = 2 ] && [ ! -e "$st/checkpoint/armed/ck--GATE-M1" ] || gwd="$gwd apply-without-confirmation(rc=$rc)"
    _a arm --board ck --gate GATE-M1 --project "relative/dir" --mode rehearse; [ "$rc" = 2 ] || gwd="$gwd relative-project(rc=$rc)"
    _a arm --board ck --gate GATE-M1 --project "$root/does-not-exist" --mode rehearse; [ "$rc" = 2 ] || gwd="$gwd missing-project(rc=$rc)"
    _a arm --board 'a--b' --gate GATE-M1 --project "$root/proj-pass" --mode rehearse; [ "$rc" = 2 ] || gwd="$gwd ambiguous-board(rc=$rc)"
    _a arm --board ck --gate CHUNK-1 --project "$root/proj-pass" --mode rehearse; [ "$rc" = 2 ] || gwd="$gwd not-a-gate(rc=$rc)"
    # A record of an earlier hold does not survive arming.
    mkdir -p "$st/checkpoint/pending" "$st/checkpoint/decided" "$st/checkpoint/probed" "$st/checkpoint/reported"
    echo '{}' > "$st/checkpoint/pending/ck--GATE-M1.json"; echo '{}' > "$st/checkpoint/decided/ck--GATE-M1.json"
    : > "$st/checkpoint/probed/ck--GATE-M1--1--abc123"; : > "$st/checkpoint/reported/ck--GATE-M1.block.1"; : > "$st/checkpoint/probed/ck--GATE-M2--1--keep"
    _a arm --board ck --gate GATE-M1 --project "$root/proj-pass" --mode rehearse
    [ "$rc" = 0 ] && [ "$(wc -l < "$st/checkpoint/armed/ck--GATE-M1" | tr -d ' ')" = 2 ] && [ "$(sed -n 1p "$st/checkpoint/armed/ck--GATE-M1")" = "mode=rehearse" ] \
      && [ ! -e "$st/checkpoint/pending/ck--GATE-M1.json" ] && [ ! -e "$st/checkpoint/decided/ck--GATE-M1.json" ] \
      && [ ! -e "$st/checkpoint/probed/ck--GATE-M1--1--abc123" ] && [ ! -e "$st/checkpoint/reported/ck--GATE-M1.block.1" ] \
      && [ -e "$st/checkpoint/probed/ck--GATE-M2--1--keep" ] || gwd="$gwd arm-rehearse(rc=$rc,$out)"
    _a list; printf '%s' "$out" | grep -qx "ck GATE-M1 rehearse $root/proj-pass" && [ "$rc" = 0 ] || gwd="$gwd list($out)"
    printf 'mode=apply\n' > "$st/checkpoint/armed/ck--GATE-M2"
    _a list; [ "$rc" = 1 ] && printf '%s' "$out" | grep -q 'MALFORMED .*ck--GATE-M2 (not armed)' || gwd="$gwd list-malformed(rc=$rc,$out)"
    rm -f "$st/checkpoint/armed/ck--GATE-M2"
    _a disarm --board ck --gate GATE-M1; [ "$rc" = 0 ] && [ ! -e "$st/checkpoint/armed/ck--GATE-M1" ] || gwd="$gwd disarm(rc=$rc)"
    _a list; printf '%s' "$out" | grep -q 'no gate is armed' || gwd="$gwd list-empty($out)"
  }
  if [ "$cron_ok" = 1 ]; then
    gwd=""; _gw_c_arming
    mnot=""
    _gw_caught _gw_c_arming scripts mode-defaults checkpoint-arm.sh 'case "$MODE" in rehearse|apply) ;; "") die' 'case "$MODE" in rehearse|apply) ;; "") MODE=rehearse;; "x") die' || mnot="$mnot mode-defaults"
    _gw_caught _gw_c_arming scripts arming-keeps-old-records checkpoint-arm.sh '    rm -f "$STATE/pending/$KEY.json" "$STATE/decided/$KEY.json" "$STATE/reported/$KEY".* "$STATE/probed/$KEY"--* 2>/dev/null' '    :' || mnot="$mnot arming-keeps-old-records"
    if [ -z "$gwd" ] && [ -z "$mnot" ]; then ok "arming-is-explicit (no mode, a bad mode, apply without --confirm-release, a relative or missing project, a '--' board and a non-gate are refused; arming writes exactly two lines and clears an earlier hold's records; list shows a malformed file as not armed with exit 1; disarm removes it; two mutants caught)"
    else bad "arming-is-explicit" "the switch must be explicit and fail closed:${gwd}; mutants not caught:${mnot:- none}"; fi
  else
    skip "arming-is-explicit" "the fixture project could not be built (git or the real acceptance-freeze is missing)"
  fi

  # ======================================================================
  # gate-scripts-run-under-the-minis-bash
  # ======================================================================
  # The mini has no Homebrew bash: a gateway on launchd runs `bash` = /bin/bash 3.2.57, and CI runs bash 5. The two parse
  # the backslash-quote substitution idiom differently (3.2 keeps the backslashes), so `/park sq GATE-M1 don't proceed` was a
  # SQL syntax error, the read-back failed, exit 3, and the decision was never recorded (the gate stayed armed and
  # undecided). CI cannot see that by running; so this reads the scripts for the idiom, and runs the verbs under /bin/bash.
  _gw_c_bash3() {
    local f file hits W h0 v q
    cat > "$root/bash4.pat" <<'GW_PAT'
\$\{[A-Za-z_0-9@*]*//[^}]*\\'
\$\{[A-Za-z_0-9]*(,,|\^\^)
declare -A
mapfile
readarray
&>>
\|&
GW_PAT
    for f in gate-reply gate-accept gate-redirect gate-park checkpoint-cron checkpoint-arm checkpoint; do
      file="${GW_REPO:-$REPO_ROOT}/scripts/$f.sh"
      hits="$(grep -nE -f "$root/bash4.pat" "$file" | grep -v '^[0-9]*:[[:space:]]*#' || true)"
      [ -z "$hits" ] || gwd="$gwd $f-uses-a-bash-4-idiom($(printf '%s' "$hits" | head -1 | cut -c1-90))"
      if [ -x /bin/bash ]; then /bin/bash -n "$file" 2>/dev/null || gwd="$gwd $f-does-not-parse-under-/bin/bash"; fi
    done
    # The verbs with text that holds every character a phone can send and SQL, the shell or argparse could mind.
    local texts=("don't proceed: it's wrong" 'say "no" & stop; `echo x` $HOME \\ 100% sure' "--not-an-option 'quoted'")
    for v in park redirect; do
      for q in 0 1 2; do
        W="$(_gw_world bash3)"; _gw_arm "$W" apply; _gw_pend "$W" 1; h0="$(_gw_hash "$W")"
        GW_ALLOW="complete comment"
        if [ -x /bin/bash ]; then GW_BASH=/bin/bash; else GW_BASH=bash; fi
        _gw_s "$W" "gate-$v.sh" --board ck --gate GATE-M1 --text "${texts[$q]}" --apply
        GW_BASH=""
        if [ "$grc" != 0 ] || [ "$(wc -l < "$W/wlog.log" | tr -d ' ')" != 1 ]; then
          gwd="$gwd $v-text$q-rc$grc($(printf '%s' "$gout$gerr" | head -c 120))"; GW_ALLOW=""; continue
        fi
        grep -qF -- "${texts[$q]}" "$W/wlog.log" || gwd="$gwd $v-text$q-was-altered($(head -c 150 "$W/wlog.log"))"
        [ ! -e "$W/state/checkpoint/armed/ck--GATE-M1" ] && jq -e --arg v "$v" '.verb == $v and .hold == 1' "$W/state/checkpoint/decided/ck--GATE-M1.json" >/dev/null 2>&1 \
          || gwd="$gwd $v-text$q-was-not-decided"
        GW_ALLOW=""
      done
    done
    # And through the handler, whose child is the `bash` on PATH.
    GW_ALLOW="complete comment"
    W="$(_gw_world bash3h)"; _gw_arm "$W" apply; _gw_pend "$W" 1
    _gw_h "$W" park "ck GATE-M1 don't proceed" 6900
    case "$(_gw_reply)" in "parked: GATE-M1"*) ;; *) gwd="$gwd handler-park-with-an-apostrophe($(_gw_reply))";; esac
    GW_ALLOW=""
  }
  gwd=""; _gw_c_bash3
  mnot=""
  _gw_caught _gw_c_bash3 scripts the-bash-4-idiom gate-reply.sh 'gr_sql_escape() { local q="'"'"'"; printf '"'"'%s'"'"' "${1//$q/$q$q}"; }' 'gr_sql_escape() { printf '"'"'%s'"'"' "${1//\'"'"'/\'"'"'\'"'"'}"; }' 'uses-a-bash-4-idiom' || mnot="$mnot the-bash-4-idiom"
  _gw_caught _gw_c_bash3 scripts no-escaping gate-reply.sh 'gr_sql_escape() { local q="'"'"'"; printf '"'"'%s'"'"' "${1//$q/$q$q}"; }' 'gr_sql_escape() { printf '"'"'%s'"'"' "$1"; }' '-rc3' || mnot="$mnot no-escaping"
  if [ -z "$gwd" ] && [ -z "$mnot" ]; then ok "gate-scripts-run-under-the-minis-bash (no bash-4 idiom in the gate, arming, cron or checkpoint scripts and each parses under /bin/bash; /park and /redirect with an apostrophe, quotes, an ampersand, a backtick, a dollar sign, a backslash and a leading '--' complete, record their decision and disarm under /bin/bash and through the handler; two mutants caught)"
  else bad "gate-scripts-run-under-the-minis-bash" "the gateway runs these under the mini's /bin/bash 3.2, which CI's bash 5 hides:${gwd}; mutants not caught:${mnot:- none}"; fi

  # ======================================================================
  # a-decision-during-the-probe-wins
  # ======================================================================
  _gw_c_during() {
    local W cr armed dec k
    GW_ALLOW="complete comment"
    # A probe can take minutes. A /park or a disarm that lands while it runs must win: the gate is NOT completed and
    # the cron says nothing. The probe here is the product's own code, so it can do what the operator does mid-run.
    for k in disarm decide; do
      W="$(_gw_world during-$k)"; cr="$(_gw_cronrepo during-$k)"
      armed="$W/state/checkpoint/armed/ck--GATE-M1"; dec="$W/state/checkpoint/decided/ck--GATE-M1.json"
      if [ "$k" = disarm ]; then
        _gw_proj_with "during-$k" "$(printf 'import os\ntry:\n    os.remove("%s")\nexcept OSError:\n    pass' "$armed")"
      else
        _gw_proj_with "during-$k" "$(printf 'import os\nos.makedirs("%s", exist_ok=True)\nopen("%s", "w").write("{\\"hold\\": 1}")' "$(dirname "$dec")" "$dec")"
      fi
      _gw_armit "$W" "$root/proj-during-$k" apply --confirm-release
      _gw_tick "$W" "$cr"
      [ "$(_gw_runs "$cr")" = 1 ] || gwd="$gwd $k-did-not-probe-$(_gw_runs "$cr")"
      [ ! -s "$W/wlog.log" ] || gwd="$gwd $k-completed-while-disarmed($(head -c 120 "$W/wlog.log"))"
      [ "$(_gw_status "$W")" = blocked ] || gwd="$gwd $k-the-gate-is-$(_gw_status "$W")"
      [ -z "$cout" ] && [ "$crc" = 0 ] || gwd="$gwd $k-spoke(rc=$crc,$(printf '%s' "$cout" | head -c 100))"
    done
    # The control: the same probe with nothing in its way completes the gate (so the refusals above are about the decision).
    W="$(_gw_world during-ctl)"; cr="$(_gw_cronrepo during-ctl)"
    _gw_armit "$W" "$root/proj-pass" apply --confirm-release
    _gw_tick "$W" "$cr"
    [ "$(wc -l < "$W/wlog.log" | tr -d ' ')" = 1 ] && [ "$(_gw_status "$W")" = done ] || gwd="$gwd control-did-not-complete"
    GW_ALLOW=""
  }
  if [ "$cron_ok" = 1 ]; then
    gwd=""; _gw_c_during
    mnot=""
    _gw_caught _gw_c_during scripts no-last-look checkpoint.sh '      if [ "${#BEFORE[@]}" -gt 0 ]; then' '      if false; then' 'completed-while-disarmed' || mnot="$mnot no-last-look"
    _gw_caught _gw_c_during scripts cron-does-not-ask checkpoint-cron.sh '--before-complete "$HERE/checkpoint-arm.sh" still-armed --board "$board" --gate "$gate" --mode "$mode" --hold "$hold" \' '\' 'completed-while-disarmed' || mnot="$mnot cron-does-not-ask"
    _gw_caught _gw_c_during scripts still-armed-ignores-the-file checkpoint-arm.sh '    gr_read_armed "$BOARD" "$GATE" && [ "$GR_ARM_MODE" = "$MODE" ] || exit 1' '    :' 'disarm-completed-while-disarmed' || mnot="$mnot still-armed-ignores-the-file"
    _gw_caught _gw_c_during scripts still-armed-ignores-a-decision checkpoint-arm.sh "    if jq -e --argjson h \"\$HOLD\" '.hold == \$h' \"\$STATE/decided/\$(gr_key \"\$BOARD\" \"\$GATE\").json\" >/dev/null 2>&1; then exit 1; fi" '    :' 'decide-completed-while-disarmed' || mnot="$mnot still-armed-ignores-a-decision"
    if [ -z "$gwd" ] && [ -z "$mnot" ]; then ok "a-decision-during-the-probe-wins (a probe that removes the arming file, or records a decision for the hold, while it runs: the gate is not completed and the cron says nothing; the same probe left alone completes it; four mutants caught)"
    else bad "a-decision-during-the-probe-wins" "a /park or a disarm that lands during a minutes-long probe must beat the completion:${gwd}; mutants not caught:${mnot:- none}"; fi
  else
    skip "a-decision-during-the-probe-wins" "the fixture project could not be built (git or the real acceptance-freeze is missing)"
  fi

  # ======================================================================
  # every-hermes-kanban-call-carries-board
  # ======================================================================
  _gw_c_boardflag() {
    local f file bare n
    for f in gate-accept gate-redirect gate-park gate-reply checkpoint-cron checkpoint-arm; do
      file="${GW_REPO:-$REPO_ROOT}/scripts/$f.sh"
      [ -f "$file" ] || { gwd="$gwd $f-missing"; continue; }
      bare="$(grep -n 'hermes kanban' "$file" | grep -v -- '--board' | grep -v '^[0-9]*:[[:space:]]*#' || true)"
      [ -z "$bare" ] || gwd="$gwd $f:$(printf '%s' "$bare" | head -1 | cut -c1-80)"
    done
    for f in gate-accept gate-redirect gate-park; do
      n="$(grep -c 'OUT="\$(hermes kanban --board "\$GR_BOARD" ' "${GW_REPO:-$REPO_ROOT}/scripts/$f.sh")"
      [ "$n" = 1 ] || gwd="$gwd $f-has-$n-board-calls"
    done
  }
  gwd=""; _gw_c_boardflag
  mnot=""
  _gw_caught _gw_c_boardflag scripts accept-without-board gate-accept.sh 'OUT="$(hermes kanban --board "$GR_BOARD" complete' 'OUT="$(hermes kanban complete' || mnot="$mnot accept-without-board"
  _gw_caught _gw_c_boardflag scripts a-second-bare-call gate-reply.sh 'gr_cleanup() {' 'gr_probe_board() { hermes kanban list; }
gr_cleanup() {' || mnot="$mnot a-second-bare-call"
  if [ -z "$gwd" ] && [ -z "$mnot" ]; then ok "every-hermes-kanban-call-carries-board (no hermes kanban call in the gate, arming or cron scripts is without --board, and each verb script makes exactly one board call; two mutants caught)"
  else bad "every-hermes-kanban-call-carries-board" "a call that omitted --board would land on whatever board is current:${gwd}; mutants not caught:${mnot:- none}"; fi

  # ======================================================================
  # state-root-agrees-with-forge-state
  # ======================================================================
  _gw_c_stateroot() {
    local fh="$root/fakehome" v py br
    mkdir -p "$fh"
    for v in "" "$root/custom-state"; do
      py="$(cd / && env -u FORGE_STATE_ROOT HOME="$fh" ${v:+FORGE_STATE_ROOT="$v"} python3 -I "$drive" table --plugin "${GW_PLUG:-$plug}" 2>/dev/null | jq -r '.state_root // empty')"
      br="$(cd / && env -u FORGE_STATE_ROOT HOME="$fh" ${v:+FORGE_STATE_ROOT="$v"} bash -c '. "$1"; forge_state_root' _ "$REPO_ROOT/scripts/forge-state.sh" 2>/dev/null)"
      [ -n "$py" ] && [ "$py" = "$br" ] || gwd="$gwd python[$py]-bash[$br]-for-'${v:-unset}'"
    done
  }
  gwd=""; _gw_c_stateroot
  mnot=""
  _gw_caught _gw_c_stateroot plugin another-default __init__.py 'os.path.join(_home(), ".forge")' 'os.path.join(_home(), ".forge2")' || mnot="$mnot another-default"
  if [ -z "$gwd" ] && [ -z "$mnot" ]; then ok "state-root-agrees-with-forge-state (the plugin's ledger root and forge-state.sh's forge_state_root are the same path with FORGE_STATE_ROOT unset and set; one mutant caught)"
  else bad "state-root-agrees-with-forge-state" "the plugin and the scripts must keep the ledger and the arming under one root:${gwd}; mutants not caught:${mnot:- none}"; fi


  # ======================================================================
  # preflight-asks-the-gateway  (section 14 EXECUTED against scratch hosts; the real host is the operator's `make preflight`)
  # ======================================================================
  # The section is cut out of preflight.sh and run with its helpers stubbed, against a scratch HOME whose ~/.hermes is a scratch
  # Hermes root (the real checkout linked in so the probe can import it). Each scenario is a host the operator might have.
  _gw_pf_host() { # name -> PFH: a scratch HOME with a bare root
    PFH="$root/pf-$1"; rm -rf "$PFH"; mkdir -p "$PFH/.hermes/profiles" "$PFH/.hermes/plugins"
    ln -s "$HOME/.hermes/hermes-agent" "$PFH/.hermes/hermes-agent"
    : > "$PFH/.hermes/config.yaml"
  }
  _gw_pf_gate() { # PFH, then the facts to change: a good forge-gate profile
    local d="$PFH/.hermes/profiles/forge-gate"
    mkdir -p "$d/plugins"; ln -s "$plug" "$d/plugins/forge-gateway"
    printf 'toolsets: []\nplatform_toolsets:\n  telegram: []\nplugins:\n  enabled:\n    - forge-gateway\nunauthorized_dm_behavior: ignore\n' > "$d/config.yaml"
    printf 'TELEGRAM_BOT_TOKEN=gate-token-0001\nTELEGRAM_ALLOWED_USERS=424242\n' > "$d/.env"
  }
  _gw_pf_root() { # PFH: the root side of a finished deploy
    mkdir -p "$PFH/.hermes/plugins"; ln -s "$plug" "$PFH/.hermes/plugins/forge-gateway"
    printf 'plugins:\n  enabled:\n    - forge-gateway\n' > "$PFH/.hermes/config.yaml"
    printf 'TELEGRAM_BOT_TOKEN=main-token-0002\nFORGE_OPERATOR_TELEGRAM_ID=424242\n' > "$PFH/.hermes/.env"
    mkdir -p "$PFH/.hermes/scripts"
    printf '#!/usr/bin/env bash\nexec bash "$HOME/.forge/repo/scripts/checkpoint-cron.sh" "$@"\n' > "$PFH/.hermes/scripts/forge-checkpoint.sh"
  }
  _gw_pf_run() { # PFH -> pfout: preflight section 14 as that host reads it
    local pf="${GW_REPO:-$REPO_ROOT}/scripts/preflight.sh" sec="$root/pf-section.sh"
    python3 -I - "$pf" "$sec" <<'GW_PFCUT'
import sys
src = open(sys.argv[1]).read()
a = src.index('sect "14. ')
b = src.index('# ---------------------------------------------------------------------------\nsay ""\nsay "## Summary"')
open(sys.argv[2], "w").write(src[a:b])
GW_PFCUT
    cat > "$root/pf-harness.sh" <<'GW_PFH'
set -u
say()  { printf '%s\n' "$*"; }
sect() { say "## $*"; }
pass() { say "PASS  $*"; }
fail() { say "FAIL  $*"; }
warn() { say "WARN  $*"; }
info() { say "info  $*"; }
PIPED=0
PF_SELF_REPO="$1"; PF_PY="$2"
. "$3"
GW_PFH
    pfout="$(cd / && env HOME="$PFH" bash "$root/pf-harness.sh" "${GW_REPO:-$REPO_ROOT}" "$hpy" "$sec" 2>&1)"
  }
  _gw_c_preflight() {
    local pf="${GW_REPO:-$REPO_ROOT}/scripts/preflight.sh" sec loop s sc
    # static: what the scenarios cannot reach (the runtime's own scripts do not exist in a scratch HOME)
    loop="$(sed -n '/^for _lscript in /,/; do$/p' "$pf")"
    for s in gate-reply.sh gate-accept.sh gate-redirect.sh gate-park.sh checkpoint-cron.sh checkpoint-arm.sh; do
      printf '%s' "$loop" | grep -Fq " $s" || gwd="$gwd $s-is-not-resolved-through-the-runtime"
    done
    sec="$(sed -n '/^sect "14\. /,/^say ""$/p' "$pf")"
    [ -n "$sec" ] || { gwd="$gwd section-14-is-missing"; return; }
    printf '%s' "$sec" | grep -Fq 'PATH="/usr/bin:/bin"' && printf '%s' "$sec" | grep -Fq -- '--check' || gwd="$gwd the-scripts-check-is-not-run-under-a-bare-path"
    printf '%s' "$sec" | grep -Fq 'is a symlink: Hermes cron refuses' || gwd="$gwd does-not-refuse-a-symlinked-cron-script"
    printf '%s' "$sec" | grep -Fq '*" GATE-M1 apply "*) warn "GATE-M1 is armed APPLY' || gwd="$gwd no-warn-for-gate-m1-armed-apply"
    printf '%s' "$sec" | grep -Fq 'checkpoint-arm.sh" list' || gwd="$gwd does-not-list-what-is-armed"
    local W st line
    W="$(_gw_world pf)"; st="$W/state"; mkdir -p "$st/checkpoint/armed"
    printf 'mode=apply\nproject=/p\n' > "$st/checkpoint/armed/ck--GATE-M1"
    line="$(cd / && env FORGE_STATE_ROOT="$st" bash "$REPO_ROOT/scripts/checkpoint-arm.sh" list 2>&1)"
    case "$line" in *" GATE-M1 apply "*) ;; *) gwd="$gwd list-shape($line)";; esac
    [ "$hermes_ok" = 1 ] || return 0
    # executed: nothing deployed yet (WARN only), then the ways a deploy goes wrong (FAIL), then a good one (no WARN, no FAIL)
    _gw_pf_host s0; _gw_pf_run
    ! printf '%s' "$pfout" | grep -q '^FAIL' && printf '%s' "$pfout" | grep -q '^WARN  operator step pending: the forge-gate profile does not exist' \
      || gwd="$gwd nothing-deployed-should-only-warn($(printf '%s' "$pfout" | grep '^FAIL' | head -2 | tr '\n' ' ' | head -c 200))"
    _gw_pf_host s1; _gw_pf_root; _gw_pf_run
    printf '%s' "$pfout" | grep -q '^FAIL  operator step pending\|^FAIL  the forge-gate profile does not exist' \
      || gwd="$gwd the-plugin-live-before-forge-gate-is-not-a-fail"
    _gw_pf_host s2; _gw_pf_gate; _gw_pf_root; _gw_pf_run
    ! printf '%s' "$pfout" | grep -q '^FAIL\|^WARN' && printf '%s' "$pfout" | grep -q '^PASS  forge-gate has an explicit, EMPTY Telegram toolset' \
      && printf '%s' "$pfout" | grep -q "^PASS  forge-gate has a bot token of its own" \
      || gwd="$gwd a-good-deploy-should-be-clean($(printf '%s' "$pfout" | grep '^FAIL\|^WARN' | head -3 | tr '\n' ' ' | head -c 300))"
    # each bad host and the line it must draw
    local sc_name sc_change sc_want
    while IFS='|' read -r sc_name sc_change sc_want; do
      [ -n "$sc_name" ] || continue
      _gw_pf_host "$sc_name"; _gw_pf_gate; _gw_pf_root
      eval "$sc_change"
      _gw_pf_run
      printf '%s' "$pfout" | grep -q "^FAIL  .*$sc_want" || gwd="$gwd $sc_name-should-FAIL($sc_want)"
    done <<'GW_PFSCEN'
a-tool|sed -i.bak 's/^  telegram: \[\]/  telegram: [web]/' "$PFH/.hermes/profiles/forge-gate/config.yaml"|forge-gate holds tools
the-default-bundle|sed -i.bak '/^platform_toolsets:/,/^  telegram: \[\]/d' "$PFH/.hermes/profiles/forge-gate/config.yaml"|forge-gate has no platform_toolsets.telegram entry
an-mcp-server|printf 'mcp_servers:\n  github:\n    command: x\n' >> "$PFH/.hermes/profiles/forge-gate/config.yaml"|lists 1 MCP server
pairing-codes|sed -i.bak '/^unauthorized_dm_behavior/d' "$PFH/.hermes/profiles/forge-gate/config.yaml"|does not ignore a stranger
the-mains-token|printf 'TELEGRAM_BOT_TOKEN=gate-token-0001\n' > "$PFH/.hermes/.env"; printf 'FORGE_OPERATOR_TELEGRAM_ID=424242\n' >> "$PFH/.hermes/.env"|is the main bot's
a-star-allowlist|printf 'TELEGRAM_BOT_TOKEN=gate-token-0001\nTELEGRAM_ALLOWED_USERS=1,*\n' > "$PFH/.hermes/profiles/forge-gate/.env"|holds \*
another-bot-with-the-verbs|mkdir -p "$PFH/.hermes/profiles/p9"; printf 'plugins:\n  enabled:\n    - forge-gateway\n' > "$PFH/.hermes/profiles/p9/config.yaml"; printf 'TELEGRAM_BOT_TOKEN=other-0003\n' > "$PFH/.hermes/profiles/p9/.env"|profile p9 has the gate verbs enabled
no-operator-id|printf 'TELEGRAM_BOT_TOKEN=main-token-0002\n' > "$PFH/.hermes/.env"|FORGE_OPERATOR_TELEGRAM_ID is not a number
GW_PFSCEN
  }
  gwd=""; _gw_c_preflight
  mnot=""
  # The first three mutants live in the EXECUTED scenarios, which ask Hermes' own resolver (gateway-toolset-probe.py runs under the
  # Hermes venv python). A host without Hermes (CI) cannot catch them, so they are only judged where that resolver exists.
  _gw_caught _gw_c_preflight scripts no-gate-m1-warning preflight.sh '*" GATE-M1 apply "*) warn "GATE-M1 is armed APPLY' '*" GATE-M1 apply "*) info "GATE-M1 is armed APPLY' || mnot="$mnot no-gate-m1-warning"
  _gw_caught _gw_c_preflight scripts new-script-not-resolved preflight.sh '                gate-reply.sh gate-accept.sh gate-redirect.sh gate-park.sh checkpoint-cron.sh checkpoint-arm.sh; do' '                gate-reply.sh gate-accept.sh gate-redirect.sh gate-park.sh checkpoint-cron.sh; do' || mnot="$mnot new-script-not-resolved"
  if [ "$hermes_ok" = 1 ]; then
    _gw_caught _gw_c_preflight scripts a-tool-is-only-a-warning preflight.sh 'fail "forge-gate holds tools: ' 'warn "forge-gate holds tools: ' 'forge-gate holds tools' || mnot="$mnot a-tool-is-only-a-warning"
    _gw_caught _gw_c_preflight scripts the-order-is-not-checked preflight.sh '        if [ "$PF_GW_LIVE" = 1 ]; then fail "$*"; else warn "operator step pending: $*"; fi' '        warn "operator step pending: $*"' 'plugin-live-before-forge-gate' || mnot="$mnot the-order-is-not-checked"
    _gw_caught _gw_c_preflight scripts other-bots-are-not-judged preflight.sh 'fail "profile ${_gwp%%|*} has the gate verbs enabled' 'info "profile ${_gwp%%|*} has the gate verbs enabled' 'another-bot-with-the-verbs' || mnot="$mnot other-bots-are-not-judged"
  fi
  if [ -n "$gwd" ] || [ -n "$mnot" ]; then bad "preflight-asks-the-gateway" "the host check must ask what the unit tests cannot:${gwd}; mutants not caught:${mnot:- none}"
  elif [ "$hermes_ok" != 1 ]; then skip "preflight-asks-the-gateway" "hermes (and its venv python) not installed: section 14's static checks and two mutants held, but its executed scenarios and the other three mutants need Hermes' own toolset resolver"
  else ok "preflight-asks-the-gateway (section 14, run against scratch hosts: nothing deployed only warns; the plugin live before forge-gate exists, a tool, the default bundle, an MCP server, pairing codes, the main bot's token, a * allowlist, another bot with the verbs and no operator id each FAIL; a good deploy is clean; the six new scripts are resolved through ~/.forge/repo and run under a bare PATH; five mutants caught)"
  fi
}
wants gateway && run_gateway_group

# ---------------------------------------------------------------------------
# gate/ — the merge gate, asked as a program.
#
# F79's first executable check was written inline in preflight.sh and driven by
# nothing. It shipped with two crashes and two false verdicts, and CI stayed
# green throughout, because no case could reach it: the decision was tangled up
# with a live API call and a live repo. Extracting it into merge-gate.sh is what
# makes it assertable (ADR-0003), and this group is the assertion.
#
# Every case runs the real script against a `gh` stub. None of them greps it.
# Two of them — checks-without-a-pr-rule and other-branch-ruleset — are the
# shapes the first version reported as GATED, so they are the regression cases
# that must stay red if this ever collapses back to "any rule anywhere".
# ---------------------------------------------------------------------------
run_gate_group() {
  group "gate"

  local lab="$TMPROOT/gate"
  mkdir -p "$lab/bin" "$lab/fix" 2>/dev/null

  # The stub answers the four endpoints merge-gate.sh uses, out of files the
  # cases write. A missing file is a FAILED call, which is how 403 and 404 are
  # expressed; `$FIX/protection.403` distinguishes "not answered" from "no".
  cat > "$lab/bin/gh" <<'STUB'
#!/usr/bin/env bash
last=""; for a in "$@"; do last="$a"; done
upgrade() {
  # Both lines, because that is what `gh` really writes: its own summary AND
  # the raw body, both on stderr. Copied from a live 403 (wielas/JobApp).
  echo "gh: Upgrade to GitHub Pro or make this repository public to enable this feature. (HTTP 403)" >&2
  echo '{"message":"Upgrade to GitHub Pro or make this repository public to enable this feature.","status":"403"}' >&2
  exit 1
}
case "$last" in
  */rulesets)
    [ -f "$FIX/rulesets.upgrade403" ] && upgrade
    [ -f "$FIX/rulesets.403" ] && { echo "HTTP 403: Resource not accessible" >&2; exit 1; }
    cat "$FIX/rulesets.json" 2>/dev/null || echo '[]' ;;
  */rulesets/*)
    id="${last##*/}"
    cat "$FIX/ruleset-$id.json" 2>/dev/null || exit 1 ;;
  */protection)
    [ -f "$FIX/protection.upgrade403" ] && upgrade
    [ -f "$FIX/protection.403" ] && { echo "HTTP 403: Must have admin rights to Repository." >&2; exit 1; }
    [ -f "$FIX/protection.json" ] || { echo "HTTP 404: Branch not protected" >&2; exit 1; }
    cat "$FIX/protection.json" ;;
  repos/*)
    [ -f "$FIX/norepo" ] && { echo "HTTP 404" >&2; exit 1; }
    cat "$FIX/repo.json" 2>/dev/null || echo '{"default_branch":"main"}' ;;
  *) exit 1 ;;
esac
STUB
  chmod +x "$lab/bin/gh" 2>/dev/null

  if [ ! -x "$lab/bin/gh" ]; then
    bad "fixture-builds" "could not construct the gh stub under $lab"
    return
  fi

  # A fixture that cannot be built is a FAILURE, not a skip: a group that
  # silently collapses to one skip is how a whole thesis goes unchecked (F5).
  local script="$REPO_ROOT/scripts/merge-gate.sh"
  if [ ! -x "$script" ]; then
    bad "merge-gate-is-executable" "scripts/merge-gate.sh is missing or not executable"
    return
  fi

  # $1=case name  $2=expected rc  $3=grep -E pattern the stdout verdict must match
  # (empty to skip the pattern)  $4..=extra args to merge-gate.sh
  _gate_run() {
    local name="$1" want_rc="$2" pat="$3"; shift 3
    local out rc
    out="$(PATH="$lab/bin:$PATH" FIX="$lab/fix" "$script" owner/repo "$@" 2>/dev/null)"
    rc=$?
    if [ "$rc" != "$want_rc" ]; then
      bad "$name" "expected exit $want_rc, got $rc (stdout: ${out:-<empty>})"
      return
    fi
    if [ -n "$pat" ] && ! printf '%s\n' "$out" | grep -Eq "$pat"; then
      bad "$name" "exit $rc was right but the verdict line was '${out:-<empty>}', expected /$pat/"
      return
    fi
    ok "$name"
  }

  _fix_reset() { rm -f "$lab/fix"/* 2>/dev/null; }

  local RS_PR_CHECKS='[{"id":1,"enforcement":"active"}]'
  local RULE_PR_CHECKS='{"conditions":{"ref_name":{"include":["~DEFAULT_BRANCH"],"exclude":[]}},"rules":[{"type":"pull_request"},{"type":"required_status_checks","parameters":{"required_status_checks":[{"context":"validate"},{"context":"verify"}]}}]}'

  # --- the shape `make protect` creates, and the one the first version FAILed --
  # templates/python-service/template/Makefile issues PUT /branches/main/protection
  # and creates ZERO rulesets. wielas/forgeboard-report — the repo docs/state.md
  # cites as the proof branch protection works — is exactly this, and the
  # rulesets-only check reported "nothing gates a direct push" for it.
  _fix_reset
  printf '[]' > "$lab/fix/rulesets.json"
  printf '{"required_pull_request_reviews":{"required_approving_review_count":0},"required_status_checks":{"contexts":["validate","verify"]}}' \
    > "$lab/fix/protection.json"
  _gate_run "classic-protection-is-a-gate" 0 'GATED.*via=classic.*pr=yes' --require validate,verify

  # --- rulesets, the modern mechanism ---------------------------------------
  _fix_reset
  printf '%s' "$RS_PR_CHECKS"  > "$lab/fix/rulesets.json"
  printf '%s' "$RULE_PR_CHECKS" > "$lab/fix/ruleset-1.json"
  _gate_run "rulesets-are-a-gate" 0 'GATED.*via=rulesets.*checks=validate,verify' --require validate,verify

  # --- REGRESSION: required checks alone are not a gate ----------------------
  # The first version tested required_status_checks FIRST and short-circuited,
  # so this exact shape printed "main is gated: PR + required status checks"
  # while a direct push to main bypassed every check.
  _fix_reset
  printf '%s' "$RS_PR_CHECKS" > "$lab/fix/rulesets.json"
  printf '{"conditions":{"ref_name":{"include":["~ALL"],"exclude":[]}},"rules":[{"type":"required_status_checks","parameters":{"required_status_checks":[{"context":"validate"},{"context":"verify"}]}}]}' \
    > "$lab/fix/ruleset-1.json"
  _gate_run "checks-without-a-pr-rule-is-not-a-gate" 3 'PARTIAL.*pr=no' --require validate,verify

  # --- a PR with nothing required is the state this repo was actually in -----
  _fix_reset
  printf '%s' "$RS_PR_CHECKS" > "$lab/fix/rulesets.json"
  printf '{"conditions":{"ref_name":{"include":["~ALL"],"exclude":[]}},"rules":[{"type":"pull_request"}]}' \
    > "$lab/fix/ruleset-1.json"
  _gate_run "a-pr-requiring-no-checks-is-not-a-gate" 3 'PARTIAL.*checks=none'

  # --- REGRESSION: a rule for another branch says nothing about main ---------
  # Nothing in the first version read conditions.ref_name, so rules were
  # flattened across every active ruleset and a release/* ruleset gated main.
  _fix_reset
  printf '%s' "$RS_PR_CHECKS" > "$lab/fix/rulesets.json"
  printf '{"conditions":{"ref_name":{"include":["refs/heads/release/*"],"exclude":[]}},"rules":[{"type":"pull_request"},{"type":"required_status_checks","parameters":{"required_status_checks":[{"context":"validate"}]}}]}' \
    > "$lab/fix/ruleset-1.json"
  _gate_run "a-ruleset-for-another-branch-does-not-gate-main" 4 'NONE'

  # --- exclude beats include ------------------------------------------------
  _fix_reset
  printf '%s' "$RS_PR_CHECKS" > "$lab/fix/rulesets.json"
  printf '{"conditions":{"ref_name":{"include":["~ALL"],"exclude":["refs/heads/main"]}},"rules":[{"type":"pull_request"},{"type":"required_status_checks","parameters":{"required_status_checks":[{"context":"validate"}]}}]}' \
    > "$lab/fix/ruleset-1.json"
  _gate_run "an-excluded-branch-is-not-gated" 4 'NONE'

  # --- an inactive ruleset is not a gate ------------------------------------
  _fix_reset
  printf '[{"id":1,"enforcement":"disabled"}]' > "$lab/fix/rulesets.json"
  printf '%s' "$RULE_PR_CHECKS" > "$lab/fix/ruleset-1.json"
  _gate_run "an-inactive-ruleset-is-not-a-gate" 4 'NONE'

  # --- the contexts are checked BY NAME -------------------------------------
  # The first version printed "PR + required status checks" without inspecting
  # which, so swapping validate/verify for a context that never runs still
  # passed — while docs/state.md and CLAUDE.md both name the two specifically.
  _fix_reset
  printf '%s' "$RS_PR_CHECKS" > "$lab/fix/rulesets.json"
  printf '{"conditions":{"ref_name":{"include":["~ALL"],"exclude":[]}},"rules":[{"type":"pull_request"},{"type":"required_status_checks","parameters":{"required_status_checks":[{"context":"lint"}]}}]}' \
    > "$lab/fix/ruleset-1.json"
  _gate_run "required-contexts-are-checked-by-name" 3 'missing=validate,verify' --require validate,verify

  # --- nothing anywhere ------------------------------------------------------
  _fix_reset
  printf '[]' > "$lab/fix/rulesets.json"
  _gate_run "no-rule-from-either-mechanism-is-exit-4" 4 'NONE.*via=none'

  # --- ADR-0017: a paid feature this repository does not have ----------------
  # Branch protection and rulesets are Pro/Team features. On a PRIVATE repo on a
  # free plan both endpoints answer 403 with GitHub's own "Upgrade to GitHub
  # Pro" sentence. That is an ANSWER — no gate can exist, so none was missed —
  # and reporting it as exit 2 refused every private product at commissioning
  # time (F120). The verdict must never be GATED, and must never be 4 either:
  # "no rule exists" and "no rule CAN exist" are different facts.
  local REPO_PRIVATE='{"default_branch":"main","private":true}'
  local REPO_PUBLIC='{"default_branch":"main","private":false}'

  _fix_reset
  printf '%s' "$REPO_PRIVATE" > "$lab/fix/repo.json"
  : > "$lab/fix/rulesets.upgrade403"
  : > "$lab/fix/protection.upgrade403"
  _gate_run "an-unavailable-plan-is-exit-5-not-exit-2" 5 \
            '^UNAVAILABLE via=none pr=no checks=none missing=check$' --require check

  # The same fixture, asserted from the other side: whatever else this verdict
  # says, it may not say the repository is gated. UNAVAILABLE means ungated for
  # a reason no configuration can fix, and a caller reading exit 5 as success
  # would launch unattended work against an unprotected main.
  _fix_reset
  printf '%s' "$REPO_PRIVATE" > "$lab/fix/repo.json"
  : > "$lab/fix/rulesets.upgrade403"
  : > "$lab/fix/protection.upgrade403"
  out="$(PATH="$lab/bin:$PATH" FIX="$lab/fix" "$script" owner/repo --require check 2>/dev/null)"
  rc=$?
  if [ "$rc" != 0 ] && ! printf '%s\n' "$out" | grep -q 'GATED'; then
    ok "an-unavailable-repo-is-never-reported-gated"
  else
    bad "an-unavailable-repo-is-never-reported-gated" \
        "an ungatable repository must never report a gate (exit $rc, verdict '${out:-<empty>}')"
  fi

  # REGRESSION: the sentinel is a GitHub-owned prose string, so it is only ever
  # read as a conjunction with what GitHub says about the repo itself. A public
  # repository cannot be short of a paid feature; that reading is incoherent and
  # incoherent is UNKNOWN, never a licence to skip the gate.
  #
  # THE EXIT CODE ALONE DOES NOT PIN THIS, which a mutation run proved: drop the
  # `.private` conjunct from the RULESETS arm only, and the classic arm's
  # generic `HTTP 403` grep still refuses, so exit 2 survives and the case stays
  # green over a live hole. The refusal is therefore asserted by WHICH ARM
  # produced it — the one under test — and not merely by its status.
  _fix_reset
  printf '%s' "$REPO_PUBLIC" > "$lab/fix/repo.json"
  : > "$lab/fix/rulesets.upgrade403"
  : > "$lab/fix/protection.upgrade403"
  err="$(PATH="$lab/bin:$PATH" FIX="$lab/fix" "$script" owner/repo --require check 2>&1 >/dev/null)"
  rc=$?
  if [ "$rc" = 2 ] && printf '%s\n' "$err" | grep -Fq 'cannot read rulesets'; then
    ok "a-public-repo-upgrade-403-is-exit-2"
  else
    bad "a-public-repo-upgrade-403-is-exit-2" \
        "a public repo claiming a paid-feature 403 is incoherent and must be refused BY THE RULESETS ARM (exit $rc: $(printf '%s' "$err" | head -1))"
  fi

  # The SAME conjunct, on the classic arm, needs its own fixture: with both
  # mechanisms unavailable the rulesets arm refuses first and the classic arm is
  # never reached, so the case above cannot see it. Here rulesets ANSWERS (`[]`)
  # and only classic claims the paid-feature 403. Both readings exit 2, so once
  # again the status alone pins nothing — it is the diagnostic that says which
  # branch decided, and "needs admin" is the correct one for a public repo.
  _fix_reset
  printf '%s' "$REPO_PUBLIC" > "$lab/fix/repo.json"
  printf '[]' > "$lab/fix/rulesets.json"
  : > "$lab/fix/protection.upgrade403"
  err="$(PATH="$lab/bin:$PATH" FIX="$lab/fix" "$script" owner/repo --require check 2>&1 >/dev/null)"
  rc=$?
  if [ "$rc" = 2 ] && printf '%s\n' "$err" | grep -Fq 'cannot read classic protection'; then
    ok "a-public-repo-classic-upgrade-403-is-needs-admin"
  else
    bad "a-public-repo-classic-upgrade-403-is-needs-admin" \
        "a public repo cannot lack a paid feature; the classic arm must refuse it as a permissions problem (exit $rc: $(printf '%s' "$err" | head -1))"
  fi

  # REGRESSION: the new branch must not swallow the 403 that was always exit 2.
  # "Must have admin" on a private repo is a token problem, not a plan problem.
  #
  # BOTH mechanisms carry the generic 403 deliberately. With only one of them
  # set, a widened sentinel (matching any "403" rather than the sentence) still
  # produced exit 2 — via the one-mechanism-disagrees branch — and this case
  # passed over the defect. With both set, a widened sentinel reaches exit 5 and
  # the case goes red, which is also the realistic shape: a token short of admin
  # fails to read either mechanism.
  _fix_reset
  printf '%s' "$REPO_PRIVATE" > "$lab/fix/repo.json"
  : > "$lab/fix/rulesets.403"
  : > "$lab/fix/protection.403"
  _gate_run "a-needs-admin-403-is-still-exit-2" 2 "" --require check

  # One mechanism unavailable while the other ANSWERS (404 = "not protected")
  # cannot both be true of one repository. Rather than pick a reading, refuse.
  _fix_reset
  printf '%s' "$REPO_PRIVATE" > "$lab/fix/repo.json"
  : > "$lab/fix/rulesets.upgrade403"
  _gate_run "one-mechanism-unavailable-is-exit-2" 2 "" --require check

  # --- F5: a control that could not run has NOT passed ----------------------
  # Both of these used to be indistinguishable from "ungated", which would have
  # turned preflight red on every private free-plan repo — F79's own condition.
  _fix_reset
  : > "$lab/fix/rulesets.403"
  _gate_run "unreadable-rulesets-is-exit-2-not-exit-4" 2 ""

  _fix_reset
  printf '[]' > "$lab/fix/rulesets.json"
  : > "$lab/fix/protection.403"
  _gate_run "unreadable-classic-protection-is-exit-2" 2 ""

  # A repo that cannot be read at all is also 2, not 4.
  _fix_reset
  : > "$lab/fix/norepo"
  _gate_run "an-unreadable-repo-is-exit-2" 2 ""

  # --- a malformed slug is a naming bug, not a permissions problem -----------
  # `ssh://git@github.com/o/r` used to be passed through verbatim; every call
  # 404'd and the operator was told they had no access.
  local out rc
  out="$(PATH="$lab/bin:$PATH" FIX="$lab/fix" "$script" 'ssh://git@github.com/o/r' 2>&1 >/dev/null)"
  rc=$?
  if printf '%s' "$out" | grep -q 'not an owner/repo slug'; then
    ok "a-malformed-slug-is-named-not-misreported"
  else
    bad "a-malformed-slug-is-named-not-misreported" \
        "expected a slug-shape refusal, got: ${out:-<empty>}"
  fi

  # --- one implementation ----------------------------------------------------
  # preflight must ASK the primitive, not re-derive the answer. A second copy is
  # how the metrics/verify pair drifted for weeks (F67), and this check exists
  # because that exact drift is the reason merge-gate.sh was extracted.
  if grep -q 'merge-gate\.sh' scripts/preflight.sh \
     && ! grep -q '/rulesets' scripts/preflight.sh; then
    ok "preflight-has-no-second-implementation"
  else
    bad "preflight-has-no-second-implementation" \
        "preflight.sh must route the gate question through scripts/merge-gate.sh and must not call the rulesets API itself"
  fi

  # --- the check cannot vanish when gh is absent -----------------------------
  # The first version was nested inside `if command -v gh`, so on a host without
  # gh it emitted no PASS, no FAIL and no WARN — it simply did not appear, which
  # is the "could not run has NOT passed" violation its own comment invoked.
  if grep -q 'gh is not on PATH — cannot ask whether main is gated' scripts/preflight.sh; then
    ok "a-missing-gh-warns-rather-than-vanishing"
  else
    bad "a-missing-gh-warns-rather-than-vanishing" \
        "preflight must WARN when gh is absent; a check that emits nothing has not passed (F5)"
  fi

  # --- help is anchored to content, not to line numbers ---------------------
  if PATH="$lab/bin:$PATH" "$script" --help 2>/dev/null | grep -q 'Exit codes'; then
    ok "help-is-anchored-to-the-header-rules"
  else
    bad "help-is-anchored-to-the-header-rules" \
        "--help must print the header block; a sed line range goes blind the first time a paragraph moves"
  fi
}
wants gate      && run_gate_group

# ---------------------------------------------------------------------------
# docs/ — CHUNK-10's launch ledger is an operator contract, not four essays.
# These assertions deliberately use stable headings and disposition tokens;
# historical measurements beneath the audit headers remain untouched.
# ---------------------------------------------------------------------------
run_docs_group() {
  group docs
  local audit=docs/audit-forgeboard-2026-07-30.md
  local roadmap=docs/roadmap-first-run.md
  local state=docs/state.md
  local guide=docs/operator-guide.md
  local id expected header bad_headers=0

  _docs_slice_contract_ok() { # $1=guide $2=audit
    local checked_guide="$1" checked_audit="$2" slice f40
    slice="$(awk '
      /^\*\*Isolate every human-driven slice/ { printing=1 }
      printing && /^\*\*Reclaim merged chunk worktrees/ { exit }
      printing { print }
    ' "$checked_guide" | tr '\n' ' ' | tr -s ' ')"
    f40="$(awk '
      /^### F40([^0-9]|$)/ { printing=1 }
      printing && /^## Priority order/ { exit }
      printing { print }
    ' "$checked_audit" | tr '\n' ' ' | tr -s ' ')"
    grep -Fq 'Reserve the main checkout for the manager/orchestrator' <<<"$slice" \
      && grep -Fq 'git worktree add ../forge-slices/<slice-id> -b slice/<slice-id> main' <<<"$slice" \
      && grep -Fq "The audit ledger is the manager's file" <<<"$slice" \
      && grep -Fq 'may read it and commit it once' <<<"$slice" \
      && grep -Fq 'must never be the only writer' <<<"$slice" \
      && grep -Fq 'exact worktree path, branch, HEAD, clean/dirty' <<<"$slice" \
      && grep -Fq 'unpushed commits' <<<"$slice" \
      && grep -Fq '**Reconciled by CHUNK-10.**' <<<"$f40" \
      && grep -Fq 'docs suite mutates those ownership and creation clauses' <<<"$f40"
  }

  _docs_f102_contract_ok() { # $1=audit $2=state
    local checked_audit="$1" checked_state="$2" f102
    f102="$(awk '
      /^### F102([^0-9]|$)/ { printing=1 }
      printing && /^### F103([^0-9]|$)/ { exit }
      printing { print }
    ' "$checked_audit" | tr '\n' ' ' | tr -s ' ')"
    grep -Fq '**Resolution evidence (CHUNK-9 independent review, 2026-08-11).**' <<<"$f102" \
      && grep -Fq '`wielas/forgeboard-report`' <<<"$f102" \
      && grep -Fq '6 pass / 3 warn / 0 skip' <<<"$f102" \
      && grep -Fq 'does not authorize the future advisory-to-blocking flip' <<<"$f102" \
      && grep -Fq '`wielas/forgeboard-report`' "$checked_state" \
      && grep -Fq '813af7f013c301869079d49b408e53788049dd0bfec1e4a57c652066fb72bc80' "$checked_state"
  }

  while IFS='|' read -r id expected; do
    [ -n "$id" ] || continue
    header="$(grep -E "^### F${id}([^0-9]|$)" "$audit" | head -1)"
    if [ -z "$header" ] || ! printf '%s' "$header" | grep -Fq "$expected"; then
      bad_headers=$((bad_headers+1))
    fi
  done <<'DISPOSITIONS'
1|CHUNK-4 CONTRACTED — PRODUCT RUN PROOF REQUIRED
2|CHUNK-4 CONTRACTED — PRODUCT RUN PROOF REQUIRED
3|PARTLY FIXED — CHUNK-4 PRODUCT RUN PROOF REQUIRED
14|FIXED BY CHUNK-6/CHUNK-7
25|STAGED BY CHUNK-9 — PRODUCT RUN REQUIRED
26|CHUNK-4 CONTRACTED — PRODUCT RUN PROOF REQUIRED
31|FIXED BY CHUNK-5
34|FIXED BY CHUNK-1
36|FIXED BY CHUNK-1
40|FIXED — RECONCILED BY CHUNK-10
44|CHUNK-4 CONTRACTED — PRODUCT RUN PROOF REQUIRED
48|FIXED BY CHUNK-5
53|DECIDED BY ADR-0012 — PRODUCT RUN PROOF REQUIRED
57|FIXED BY CHUNK-2
81|SUPERSEDED BY CHUNK-10
91|FIXED BY CHUNK-3
92|FIXED BY CHUNK-3
93|FIXED BY CHUNK-3
101|RESOLVED BY CHUNK-3 / ADR-0012
102|RESOLVED BY CHUNK-9
103|RESOLVED BY ADR-0012 — RECONCILED BY CHUNK-10
DISPOSITIONS
  if [ "$bad_headers" = 0 ]; then
    ok "launch-ledger-reconciles-touched-findings"
  else
    bad "launch-ledger-reconciles-touched-findings" \
        "$bad_headers readiness finding header(s) lack their closing chunk or remaining proof"
  fi

  if grep -Fq '**Status: superseded as a planning proposal' "$roadmap" \
     && grep -Fq '### Landed tracks' "$roadmap" \
     && grep -Fq '### Remaining proof' "$roadmap" \
     && grep -Fq '### Operational run sequence' "$roadmap"; then
    ok "launch-roadmap-separates-state-and-sequence"
  else
    bad "launch-roadmap-separates-state-and-sequence" \
        "roadmap must label the proposal superseded and separate landed tracks, remaining proof, and run sequence"
  fi

  if _docs_slice_contract_ok "$guide" "$audit"; then
    ok "launch-slices-own-worktrees-and-manager-owned-ledger"
  else
    bad "launch-slices-own-worktrees-and-manager-owned-ledger" \
        "F40 requires an isolated sibling worktree, manager-owned main/ledger, and an explicit handoff"
  fi

  local mutated="$TMPROOT/docs-contract-mutations"
  mkdir -p "$mutated"
  sed 's#git worktree add ../forge-slices/<slice-id> -b slice/<slice-id> main#git switch -c slice/<slice-id> main#' \
    "$guide" > "$mutated/operator-guide.md"
  sed "s#The audit ledger is the manager's file#The audit ledger is the slice's file#" \
    "$guide" > "$mutated/operator-guide-owner.md"
  if _docs_slice_contract_ok "$mutated/operator-guide.md" "$audit" \
     || _docs_slice_contract_ok "$mutated/operator-guide-owner.md" "$audit"; then
    bad "launch-slice-contract-mutation-is-caught" \
        "a guide without isolated creation or manager ledger ownership still satisfied F40"
  else
    ok "launch-slice-contract-mutation-is-caught"
  fi

  local cleanup
  cleanup="$(sed -n '/^\*\*Reclaim merged chunk worktrees/,/^\*\*Reading a live board/p' "$guide")"
  if printf '%s' "$cleanup" | grep -Fq 'only reaches worktrees under `<project>/.worktrees/`' \
     && printf '%s' "$cleanup" | grep -Fq '**Explicit review outside the bound.**' \
     && printf '%s' "$cleanup" | grep -Fq 'Never widen the unattended sweep'; then
    ok "launch-cleanup-stays-bounded"
  else
    bad "launch-cleanup-stays-bounded" \
        "operator cleanup must retain the .worktrees boundary and require explicit review outside it"
  fi

  local f81 f103
  f81="$(awk '
    /^### F81([^0-9]|$)/ { printing=1 }
    printing && /^### F82([^0-9]|$)/ { exit }
    printing { print }
  ' "$audit")"
  f103="$(awk '
    /^### F103([^0-9]|$)/ { printing=1 }
    printing && /^## Ledger addition from the merge-gate slice/ { exit }
    printing { print }
  ' "$audit")"
  if printf '%s' "$f81" | grep -Fq 'It is **not edited here**' \
     && printf '%s' "$f81" | grep -Fq '**Superseding decision (CHUNK-10).' \
     && printf '%s' "$f103" | grep -Fq 'Recorded because a future reader' \
     && printf '%s' "$f103" | grep -Fq '**Superseding record (CHUNK-10).' \
     && printf '%s' "$f103" | grep -Fq 'ADR-0012 D12.4'; then
    ok "launch-prior-dispositions-are-superseded"
  else
    bad "launch-prior-dispositions-are-superseded" \
        "F81/F103 must retain their original text and append linked CHUNK-10 superseding records"
  fi

  if _docs_f102_contract_ok "$audit" "$state"; then
    ok "launch-f102-cites-real-product-roadmap"
  else
    bad "launch-f102-cites-real-product-roadmap" \
        "F102 must name the measured product, advisory result, report digest, and still-pending blocking decision"
  fi

  sed 's#wielas/forgeboard-report#wielas/fixture#g' \
    "$audit" > "$mutated/audit.md"
  if _docs_f102_contract_ok "$mutated/audit.md" "$state"; then
    bad "launch-f102-evidence-mutation-is-caught" \
        "changing the real product identity still satisfied F102"
  else
    ok "launch-f102-evidence-mutation-is-caught"
  fi

  local shared='make roadmap-check PROJECT="$PROJECT"' file missing=0
  for file in "$audit" "$roadmap" "$state" "$guide"; do
    grep -Fq "$shared" "$file" || missing=$((missing+1))
  done
  if [ "$missing" = 0 ]; then
    ok "launch-docs-share-next-command"
  else
    bad "launch-docs-share-next-command" \
        "$missing of the four launch documents do not name '$shared' as the next command"
  fi

  # Q4 (epic-hands-free). A fresh session with no context reads CLAUDE.md and
  # state.md, in that order, and neither knew the epic existed -- so the one
  # document that says what is done and what is next was reachable only by
  # someone who already knew its filename. A link is prose until something
  # executes it; this is that (ADR-0003).
  local epic=docs/epic-hands-free.md router=CLAUDE.md epic_missing=""
  [ -f "$epic" ] || epic_missing="the epic itself is gone"
  grep -Fq 'epic-hands-free.md' "$router" || epic_missing="$epic_missing CLAUDE.md"
  grep -Fq 'epic-hands-free.md' "$state" || epic_missing="$epic_missing docs/state.md"
  # …and reachable is not enough: both routers must send the reader to the
  # section that governs how a session is run, not merely name the file.
  grep -Fq 'How we run this epic' "$router" || epic_missing="$epic_missing CLAUDE.md(§)"
  grep -Fq 'How we run this epic' "$state" || epic_missing="$epic_missing state.md(§)"
  # The epic's own claim about itself: its session table is the only progress
  # record. If that heading is renamed, both links above become dead ends.
  grep -Fq '## Session plan' "$epic" || epic_missing="$epic_missing epic(session-table)"
  grep -Fq '## How we run this epic' "$epic" || epic_missing="$epic_missing epic(§)"
  if [ -z "$epic_missing" ]; then
    ok "the-open-epic-is-discoverable"
  else
    bad "the-open-epic-is-discoverable" \
        "a session starting with no context cannot reach the epic:$epic_missing"
  fi
}
wants docs      && run_docs_group

# ---------------------------------------------------------------------------
# quota/ — the usage-limit park (ADR-0016).
#
# Codex quota is a rolling window whose shape the provider chooses and can
# change. Nothing here may assume a window length: every case drives the real
# decision function over checked-in streams in scripts/fixtures/quota/, and the
# end-to-end cases drive the real runner against a stubbed `codex` on PATH —
# the technique gate/ already uses for `gh`. This group spends nothing.
#
# Each case asserts both halves where there are two: the program behaves, and
# the skill still calls it. A behavioural test of a program nothing invokes is
# green and worthless.
# ---------------------------------------------------------------------------
run_quota_group() {
  group quota
  local qw=scripts/quota-window.py
  local runner=scripts/codex-run.sh
  local fx=scripts/fixtures/quota
  local lane=skills/forge-lane/SKILL.md

  if [ ! -x "$qw" ] || [ ! -x "$runner" ]; then
    bad "runner-and-parser-exist" "$qw and $runner must both exist and be executable"
    return
  fi

  # THE CLOCK IS PINNED. Fixtures carry literal epochs, and the parser now
  # (correctly) treats a reset that has already passed as stale evidence rather
  # than a live block. Judged against the wall clock, every fixture here would
  # therefore start returning `clear` the moment real time overtook the numbers
  # in it -- the whole group going quietly, permanently green on a date nobody
  # chose. A checked-in epoch is only meaningful beside a checked-in now.
  local QNOW=1786900000          # before every reset any fixture states
  local QLATER=1788000000        # after every reset any fixture states
  _q() { "$qw" --threshold "${2:-95}" --now "${3:-$QNOW}" "$fx/$1.jsonl" 2>/dev/null; }

  # THE case. A short window clearing in minutes and a weekly one clearing in
  # days are both spent; the run is blocked until BOTH clear. Waking at the
  # nearer reset wakes straight back into a block, and a lane looping on that
  # burns a night making no progress.
  if [ "$(_q both-windows-exhausted)" = "blocked wake_at=1787200231 windows=primary,secondary" ]; then
    ok "latest-reset-wins"
  else
    bad "latest-reset-wins" \
        "two exhausted windows must wait for max(resets_at); got '$(_q both-windows-exhausted)'"
  fi

  # The mutation that proves the case above is load-bearing rather than merely
  # agreeing with today's fixture: swap max for min and this group must redden.
  local qwmut="$TMPROOT/quota-window-min.py"
  sed 's/int(max(resets))/int(min(resets))/' "$qw" > "$qwmut" && chmod +x "$qwmut"
  if [ "$(sed -n 's/.*int(\(m..\)(resets)).*/\1/p' "$qw" | head -1)" = max ] \
     && [ "$("$qwmut" --threshold 95 --now $QNOW "$fx/both-windows-exhausted.jsonl" 2>/dev/null)" \
          = "blocked wake_at=1787000000 windows=primary,secondary" ]; then
    ok "nearest-reset-mutation-is-caught"
  else
    bad "nearest-reset-mutation-is-caught" \
        "the max-over-resets_at rule must be the thing latest-reset-wins tests"
  fi

  # The same rule from the other side, and the half that `latest-reset-wins`
  # structurally cannot see: max runs over the BLOCKED windows, not over every
  # window reported. A spent short window beside a healthy weekly one is the
  # ordinary shape under the rolling regime, and taking the weekly reset there
  # sleeps five days because five hours filled.
  local qwall="$TMPROOT/quota-window-allwindows.py"
  sed 's/for _, w in blocked)/for _, w in windows)/' "$qw" > "$qwall" \
    && chmod +x "$qwall"
  if [ "$(_q short-window-exhausted)" = "blocked wake_at=1787000000 windows=primary" ] \
     && [ "$("$qwall" --threshold 95 --now $QNOW "$fx/short-window-exhausted.jsonl" 2>/dev/null)" \
          = "blocked wake_at=1787200231 windows=primary" ]; then
    ok "the-wait-is-bounded-by-the-blocked-windows"
  else
    bad "the-wait-is-bounded-by-the-blocked-windows" \
        "max must run over blocked windows only; got '$(_q short-window-exhausted)'"
  fi

  # When the provider NAMES the window it refused on, that name is the most
  # precise fact in the payload. Widening it to every window is the same
  # five-days-for-five-hours failure, reached through the hard-limit path
  # instead of the percentage one -- and it is invisible to
  # `hard-limit-outranks-percentage`, whose fixture has a null secondary.
  local qwwide="$TMPROOT/quota-window-widenamed.py"
  sed 's/blocked = named if named else windows/blocked = windows/' "$qw" \
    > "$qwwide" && chmod +x "$qwwide"
  if [ "$(_q named-window-reached)" = "blocked wake_at=1787000000 windows=primary" ] \
     && [ "$("$qwwide" --threshold 95 --now $QNOW "$fx/named-window-reached.jsonl" 2>/dev/null)" \
          = "blocked wake_at=1787500000 windows=primary,secondary" ]; then
    ok "a-named-refusal-blocks-only-the-window-it-names"
  else
    bad "a-named-refusal-blocks-only-the-window-it-names" \
        "rate_limit_reached_type must not widen to healthy windows; got '$(_q named-window-reached)'"
  fi

  # A reset that has already passed describes a window which has SINCE reset.
  # Believing it is how a pre-flight read of an old rollout, or a reactive read
  # of a log holding an earlier attempt, parks on a limit that expired hours
  # ago -- with nothing bounding the wait by default.
  if [ "$(_q both-windows-exhausted 95 $QLATER)" = clear ] \
     && [ "$(_q named-window-reached 95 $QLATER)" = clear ]; then
    ok "a-reset-in-the-past-is-stale-not-blocking"
  else
    bad "a-reset-in-the-past-is-stale-not-blocking" \
        "an elapsed resets_at must not block; got '$(_q both-windows-exhausted 95 $QLATER)'"
  fi

  # An epoch reported in MILLISECONDS is the shape most likely to arrive
  # unannounced, and it reads as the year 58000. Sleeping on it is
  # indistinguishable from hanging, so it must degrade to a bounded re-probe.
  if [ "$("$qw" --threshold 95 --now $QNOW \
            --rate-limits '{"primary":{"used_percent":100.0,"resets_at":1787000000000}}' \
            2>/dev/null)" = "blocked wake_at=unknown windows=primary" ]; then
    ok "an-incredible-reset-is-not-slept-on"
  else
    bad "an-incredible-reset-is-not-slept-on" \
        "a resets_at beyond the horizon must read as wake_at=unknown, not as a wait"
  fi

  # A stream carrying no rate-limit data at all -- including a torn final line,
  # which is what a killed process leaves -- is unknown, and unknown lets the
  # run start. Refusing there would deadlock a machine that has never run Codex.
  "$qw" --threshold 95 --now $QNOW "$fx/no-rate-limits.jsonl" >/dev/null 2>&1
  if [ "$?" = 3 ] && [ "$(_q no-rate-limits)" = "unknown no-rate-limit-data" ]; then
    ok "a-stream-without-windows-is-unknown-not-clear"
  else
    bad "a-stream-without-windows-is-unknown-not-clear" \
        "no rate-limit data must be exit 3 unknown; got '$(_q no-rate-limits)'"
  fi

  # Q1 (epic-hands-free). …but a refusal with a stated time in PROSE is not "no
  # data". The fixture is redglass's own event, byte-for-byte out of rollout
  # 01a07acc: no `rate_limits` anywhere, `codex_error_info:
  # usage_limit_exceeded`, and the reset only as "try again at 11:55 AM". It
  # used to read as `unknown no-rate-limit-data`, which codex-run.sh routes to
  # "not a usage limit" (exit 4).
  # TZ is pinned because the sentence carries no zone: under TZ=UTC the event at
  # 07:36:41Z resolves to 11:55:00Z = 1788782100, 2 h 19 m later -- against the
  # ~3 h the lane improvised.
  local QTEXT=1788766602        # one second after the refusal was written
  _qtz() { TZ=UTC "$qw" --threshold 95 --now "${2:-$QTEXT}" "$fx/$1.jsonl" 2>/dev/null; }
  if [ "$(_qtz plaintext-usage-limit)" = "blocked wake_at=1788782100 windows=stated" ]; then
    ok "a-plaintext-refusal-parks-with-its-stated-reset (11:55 AM -> 1788782100)"
  else
    bad "a-plaintext-refusal-parks-with-its-stated-reset" \
        "a prose refusal naming its reset must block with that epoch; got '$(_qtz plaintext-usage-limit)'"
  fi

  # The clock form is resolved against the moment the refusal was WRITTEN, not
  # against now. Anchored to now, an hours-old rollout read at pre-flight parks
  # until this afternoon's 11:55 -- the exact mistake _is_stale exists to stop.
  # Anchored to the event, the same stale refusal lands in the past and clears.
  local QTEXTLATER=1788790000   # ~2 h after the stated 11:55 has passed
  local qwnow="$TMPROOT/quota-window-anchored-now.py"
  sed 's/parse_stated_reset(message, event_time(obj, clock_now))/parse_stated_reset(message, clock_now)/' \
    "$qw" > "$qwnow" && chmod +x "$qwnow"
  if [ "$(_qtz plaintext-usage-limit $QTEXTLATER)" = clear ] \
     && [ "$(TZ=UTC "$qwnow" --threshold 95 --now $QTEXTLATER \
               "$fx/plaintext-usage-limit.jsonl" 2>/dev/null)" != clear ]; then
    ok "a-plaintext-reset-is-anchored-to-the-event-not-to-now"
  else
    bad "a-plaintext-reset-is-anchored-to-the-event-not-to-now" \
        "a refusal older than its own stated reset must be stale; got '$(_qtz plaintext-usage-limit $QTEXTLATER)'"
  fi

  # And it is read off the ERROR CHANNEL only. A chunk that builds a rate
  # limiter prints this sentence in agent text; parsing any string in the
  # stream would park the lane on the model's own prose. The marker and the
  # message must sit in the same object.
  local qprose="$TMPROOT/quota-prose.jsonl"
  printf '%s\n' \
    '{"timestamp":"2026-09-07T07:36:41.002Z","type":"event_msg","payload":{"type":"agent_message","message":"You'"'"'ve hit your usage limit. ... or try again at 11:55 AM."}}' \
    > "$qprose"
  TZ=UTC "$qw" --threshold 95 --now $QTEXT "$qprose" >/dev/null 2>&1
  if [ "$?" = 3 ] \
     && [ "$(TZ=UTC "$qw" --threshold 95 --now $QTEXT "$qprose" 2>/dev/null)" \
          = "unknown no-rate-limit-data" ]; then
    ok "a-plaintext-reset-is-read-only-on-the-error-channel"
  else
    bad "a-plaintext-reset-is-read-only-on-the-error-channel" \
        "the same sentence in agent text must stay unknown, not park the lane"
  fi

  # The second spelling seen in a real rollout, carrying its own date. Recorded
  # because a parser that handles only the bare clock silently falls back to
  # exit 3 on it -- the identical defect, one message format over.
  local qdated="$TMPROOT/quota-dated.jsonl"
  printf '%s\n' \
    '{"timestamp":"2026-08-05T06:00:00.000Z","type":"event_msg","payload":{"type":"task_complete","error":{"message":"You'"'"'ve hit your usage limit... try again at Aug 5th, 2026 9:53 AM.","codex_error_info":"usage_limit_exceeded"}}}' \
    > "$qdated"
  if [ "$(TZ=UTC "$qw" --threshold 95 --now 1785900000 "$qdated" 2>/dev/null)" \
       = "blocked wake_at=1785923580 windows=stated" ]; then
    ok "a-dated-plaintext-reset-is-parsed (Aug 5th, 2026 9:53 AM -> 1785923580)"
  else
    bad "a-dated-plaintext-reset-is-parsed" \
        "the dated refusal form must parse too; got '$(TZ=UTC "$qw" --threshold 95 --now 1785900000 "$qdated" 2>/dev/null)'"
  fi

  # THE case for Q1, and the one the fixture above cannot make. The two streams
  # this script is pointed at have different envelopes, and only one of them is
  # the path that actually exited 4.
  #
  #   pre-flight  -> the newest session ROLLOUT: payload-nested, top-level ISO
  #                  timestamp, and it carries `codex_error_info`.
  #   reactive    -> `$CURRENT`, the live `codex exec --json` stream.
  #
  # The reactive stream is what `codex-run.sh` asks after a nonzero exit, so it
  # is what routed redglass CHUNK-6/8 to "not a usage limit". This fixture is
  # that stream, recovered verbatim from the forge-codex-lane board, session
  # 01a07acc -- the SAME session as the rollout fixture above. It carries no
  # `rate_limits`, no marker of any kind, and no timestamp: the error channel is
  # identifiable only by `"type":"error"` and by the message sitting under
  # `turn.failed`'s `error` key. A rule keyed on the marker alone parses the
  # rollout and is inert here, which is the whole reason this case exists.
  if [ "$(_qtz plaintext-usage-limit-exec-json)" = "blocked wake_at=1788782100 windows=stated" ]; then
    ok "the-reactive-exec-json-refusal-parks (no marker, no timestamp, no rate_limits)"
  else
    bad "the-reactive-exec-json-refusal-parks" \
        "the real `codex exec --json` refusal must park like its rollout does; got '$(_qtz plaintext-usage-limit-exec-json)'"
  fi

  # …and that it parks for the RIGHT reason. Collapse the channel test back to
  # the marker alone — the shipped-and-inert state this case was written to
  # catch — and the stream must go unjudgeable while the rollout, which has the
  # marker, still parses. Both halves are asserted: a mutant that broke BOTH
  # would prove nothing about which arm is load-bearing.
  local qwmark="$TMPROOT/quota-window-marker-only.py"
  # Three -e, not one script with embedded newlines: a backslash-newline inside
  # single quotes stays a literal newline, and BSD sed refuses it as a delimiter.
  sed -e 's/^        on_channel = (marked$/        on_channel = (False/' \
      -e 's/^                      or (isinstance(kind, str) and kind in ERROR_EVENT_TYPES)$/                      or False/' \
      -e 's/^                      or parent_key == "error")$/                      or marked)/' \
    "$qw" > "$qwmark" && chmod +x "$qwmark"
  if [ "$(TZ=UTC "$qwmark" --threshold 95 --now $QTEXT \
            "$fx/plaintext-usage-limit-exec-json.jsonl" 2>/dev/null)" \
       = "unknown no-rate-limit-data" ] \
     && [ "$(TZ=UTC "$qwmark" --threshold 95 --now $QTEXT \
               "$fx/plaintext-usage-limit.jsonl" 2>/dev/null)" \
          = "blocked wake_at=1788782100 windows=stated" ]; then
    ok "the-reactive-channel-rule-is-not-the-marker-rule"
  else
    bad "the-reactive-channel-rule-is-not-the-marker-rule" \
        "collapsing the channel test to the marker alone must make the stream unjudgeable while the rollout still parses — otherwise this case proves nothing"
  fi

  # A marker is evidence about the moment it was written. Carried forward over
  # a FRESHER snapshot, one refused attempt condemns every later reading of the
  # same log however healthy the provider now says the windows are -- which is
  # exactly how a run parks forever on a stale log.
  local qsticky="$TMPROOT/sticky.jsonl"
  {
    printf '{"type":"event_msg","payload":{"type":"token_count","rate_limits":{"primary":{"used_percent":100.0,"resets_at":1787000000}}}}\n'
    printf '{"type":"event_msg","payload":{"type":"error","error_type":"usage_limit_reached"}}\n'
    printf '{"type":"event_msg","payload":{"type":"token_count","rate_limits":{"primary":{"used_percent":5.0,"resets_at":1787000000}}}}\n'
  } > "$qsticky"
  if [ "$("$qw" --threshold 95 --now $QNOW "$qsticky" 2>/dev/null)" = clear ]; then
    ok "a-fresh-snapshot-supersedes-an-earlier-refusal"
  else
    bad "a-fresh-snapshot-supersedes-an-earlier-refusal" \
        "a reached marker must not outlive the snapshot it described"
  fi

  # Rollouts on the machine this shipped from still report ONE window of 10080
  # minutes with a null secondary; the regime this feature exists for reports a
  # short window beside it. Both must read without a branch on window_minutes.
  if [ "$(_q weekly-only-clear)" = clear ] \
     && [ "$(_q five-hour-and-weekly-clear)" = clear ] \
     && [ "$(_q weekly-only-clear 30)" = "blocked wake_at=1787200231 windows=primary" ] \
     && ! grep -qE 'window_minutes[[:space:]]*(==|!=|<|>)' "$qw"; then
    ok "window-shape-is-not-hardcoded"
  else
    bad "window-shape-is-not-hardcoded" \
        "both the weekly-only and short-window shapes must read, with no window length in the parser"
  fi

  # The provider already refused. used_percent reads 98 in this fixture, under
  # the threshold — a percentage must not overrule a stated refusal.
  if [ "$(_q limit-reached-error)" = "blocked wake_at=1787000000 windows=primary" ]; then
    ok "hard-limit-outranks-percentage"
  else
    bad "hard-limit-outranks-percentage" \
        "a usage_limit_reached marker must block below the threshold; got '$(_q limit-reached-error)'"
  fi

  # A null used_percent is unknown, not clear. Counting it clear is how a
  # parser that quietly stopped parsing keeps licensing runs until one dies.
  "$qw" --threshold 95 "$fx/null-used-percent.jsonl" >/dev/null 2>&1
  if [ "$?" = 3 ] && [ "$(_q null-used-percent)" != clear ]; then
    ok "missing-fields-are-unknown-not-clear"
  else
    bad "missing-fields-are-unknown-not-clear" \
        "a null used_percent must be exit 3 'unknown', never 'clear'"
  fi

  if [ "$(_q blocked-without-resets)" = "blocked wake_at=unknown windows=primary" ]; then
    ok "blocked-without-reset-is-not-clear"
  else
    bad "blocked-without-reset-is-not-clear" \
        "exhausted with no resets_at is still blocked; got '$(_q blocked-without-resets)'"
  fi

  # The horizon is one fact held in two languages: quota-window.py refuses to
  # REPORT a reset beyond it, codex-run.sh refuses to SLEEP past it. If they
  # drift apart, one of the two defences silently stops being reachable and
  # everything stays green -- so make them one number by assertion, since the
  # code cannot share it.
  local qw_h cr_h
  qw_h="$(python3 -c 'import re; m = re.search(r"^WAKE_HORIZON = (.+)$", open("scripts/quota-window.py").read(), re.M); print(eval(m.group(1)))' 2>/dev/null)"
  cr_h="$(sed -n 's/^WAKE_HORIZON=\([0-9][0-9]*\).*/\1/p' scripts/codex-run.sh | head -1)"
  if [ -n "$qw_h" ] && [ "$qw_h" = "$cr_h" ]; then
    ok "the-horizon-is-one-number (${qw_h}s)"
  else
    bad "the-horizon-is-one-number" \
        "quota-window.py says '$qw_h' and codex-run.sh says '$cr_h'"
  fi

  # ---- end to end, against a stubbed codex --------------------------------
  #
  # Every end-to-end case below runs under a watchdog. There is no `timeout(1)`
  # to reach for -- macOS ships none -- and the regressions these cases exist to
  # catch are precisely the ones that make the runner never return. A hang has
  # no colour: it is worse than the skip/warn degradation CLAUDE.md warns about,
  # because CI reports nothing at all rather than something misleading.
  _qrun() { # <seconds> <command...>  -> merged output on stdout, real rc
    local limit="$1"; shift
    local out="$TMPROOT/qrun-out.$$" pid wpid rc
    "$@" > "$out" 2>&1 &
    pid=$!
    # stdout to /dev/null, or this subshell holds the caller's command
    # substitution open for the full sleep even after the runner exits.
    ( sleep "$limit"; kill -9 "$pid" ) >/dev/null 2>&1 &
    wpid=$!
    wait "$pid"; rc=$?
    kill -9 "$wpid" >/dev/null 2>&1
    wait "$wpid" >/dev/null 2>&1
    cat "$out"; rm -f "$out"
    return "$rc"
  }

  local qroot="$TMPROOT/quota-run" qbin qws qrt qpark
  qbin="$qroot/bin"; qws="$qroot/ws"; qrt="$qroot/runtime"; qpark="$qroot/parks"
  mkdir -p "$qbin" "$qws" "$qrt" "$qpark" "$qroot/codexhome/sessions"
  printf 'contract\n' > "$qrt/contract.md"
  ( cd "$qws" && git init -q . \
      && git -c user.email=q@q -c user.name=q commit -q --allow-empty -m init ) >/dev/null 2>&1

  # Limited on the first call, clean on the resume. Windows reset seconds out,
  # so the case exercises the real sleep rather than mocking it away.
  cat > "$qbin/codex" <<'QSTUB'
#!/usr/bin/env bash
case "${1:-}" in --version) echo "codex-cli stub"; exit 0;; esac
for a in "$@"; do [ "$a" = resume ] && { echo "$*" > "$STUBDIR/resume-argv"
  printf '{"type":"event_msg","payload":{"type":"token_count","rate_limits":{"primary":{"used_percent":2.0,"resets_at":9999999999}}}}\n'
  printf '{"type":"event_msg","payload":{"type":"agent_message","message":"done"}}\n'
  exit 0; }; done
echo first >> "$STUBDIR/calls"
printf '{"type":"session_meta","payload":{"session_id":"verify-session-42"}}\n'
printf '{"type":"event_msg","payload":{"type":"token_count","rate_limits":{"primary":{"used_percent":100.0,"resets_at":%d},"secondary":{"used_percent":100.0,"resets_at":%d}}}}\n' "$(( $(date +%s) + 9 ))" "$(( $(date +%s) + 10 ))"
printf '{"type":"event_msg","payload":{"type":"error","error_type":"usage_limit_reached"}}\n'
exit 1
QSTUB
  chmod +x "$qbin/codex"

  local qrc qout
  qout="$(_qrun 120 env PATH="$qbin:$PATH" STUBDIR="$qroot" CODEX_HOME="$qroot/codexhome" \
            FORGE_LANE_RUNTIME="$qrt" FORGE_LANE_PARK_ROOT="$qpark" \
            FORGE_QUOTA_PAD=1 FORGE_QUOTA_POLL=1 FORGE_QUOTA_TICK=1 \
            "$runner" "$qws" qrun-1 qtask-1 2>&1)"
  qrc=$?
  if [ "$qrc" = 0 ] \
     && printf '%s' "$qout" | grep -q 'PARKED' \
     && printf '%s' "$qout" | grep -q 'resuming session verify-session-42' \
     && [ "$(grep -c first "$qroot/calls" 2>/dev/null)" = 1 ]; then
    ok "parks-then-resumes-the-same-session"
  else
    bad "parks-then-resumes-the-same-session" \
        "a limited run must park, wake and resume its own session exactly once (rc=$qrc)"
  fi

  # `codex exec resume` accepts neither -s, -C nor --add-dir, so a resumed run
  # that trusted inheritance would silently lose write access to the shared
  # .git — the failure that cost a rung the first time it was met.
  if grep -q 'writable_roots' "$qroot/resume-argv" 2>/dev/null \
     && grep -q 'sandbox_mode' "$qroot/resume-argv" 2>/dev/null; then
    ok "resume-carries-the-sandbox-grant"
  else
    bad "resume-carries-the-sandbox-grant" \
        "the resume path must restate the sandbox grant as -c overrides"
  fi

  # A park record left by a killed supervisor is the successor's way back into
  # the same session: a new run id means a new, empty scratch directory.
  local qrt2="$qroot/runtime2"
  mkdir -p "$qrt2" && printf 'contract\n' > "$qrt2/contract.md"
  cat > "$qpark/qtask-2.json" <<PARKED
{"schema":"forge.park.v1","task_id":"qtask-2","workspace":"$qws",
 "codex_session_id":"verify-session-99","wake_at":0,"parked_at":$(date +%s)}
PARKED
  qout="$(_qrun 120 env PATH="$qbin:$PATH" STUBDIR="$qroot" CODEX_HOME="$qroot/codexhome" \
            FORGE_LANE_RUNTIME="$qrt2" FORGE_LANE_PARK_ROOT="$qpark" \
            FORGE_QUOTA_PAD=1 FORGE_QUOTA_POLL=1 FORGE_QUOTA_TICK=1 \
            "$runner" "$qws" qrun-2 qtask-2 2>&1)"
  if printf '%s' "$qout" | grep -q 'adopting session verify-session-99'; then
    ok "park-record-is-adopted-by-a-successor"
  else
    bad "park-record-is-adopted-by-a-successor" \
        "a durable park record must let a NEW run id resume the parked session"
  fi

  # Adoption is for a supervisor killed DURING a park. A record naming another
  # workspace is a moved card, and one too old to date is debris -- resuming
  # either sends "a usage limit interrupted you, continue where you stopped"
  # into a session that was never interrupted, against a contract that has had
  # a week to change. Both refusals are checked; only the first was before.
  local qrt5="$qroot/runtime5"
  mkdir -p "$qrt5" && printf 'contract\n' > "$qrt5/contract.md"
  cat > "$qpark/qtask-5.json" <<PARKED5
{"schema":"forge.park.v1","task_id":"qtask-5","workspace":"/somewhere/else",
 "codex_session_id":"verify-session-elsewhere","parked_at":$(date +%s)}
PARKED5
  qout="$(_qrun 120 env PATH="$qbin:$PATH" STUBDIR="$qroot" CODEX_HOME="$qroot/codexhome" \
            FORGE_LANE_RUNTIME="$qrt5" FORGE_LANE_PARK_ROOT="$qpark" \
            FORGE_QUOTA_PAD=1 FORGE_QUOTA_POLL=1 FORGE_QUOTA_TICK=1 \
            "$runner" "$qws" qrun-5 qtask-5 2>&1)"
  local qforeign="$qout"
  cat > "$qpark/qtask-6.json" <<PARKED6
{"schema":"forge.park.v1","task_id":"qtask-6","workspace":"$qws",
 "codex_session_id":"verify-session-ancient","parked_at":1}
PARKED6
  local qrt6="$qroot/runtime6"
  mkdir -p "$qrt6" && printf 'contract\n' > "$qrt6/contract.md"
  qout="$(_qrun 120 env PATH="$qbin:$PATH" STUBDIR="$qroot" CODEX_HOME="$qroot/codexhome" \
            FORGE_LANE_RUNTIME="$qrt6" FORGE_LANE_PARK_ROOT="$qpark" \
            FORGE_QUOTA_PAD=1 FORGE_QUOTA_POLL=1 FORGE_QUOTA_TICK=1 \
            "$runner" "$qws" qrun-6 qtask-6 2>&1)"
  if printf '%s' "$qforeign" | grep -q 'ignoring park record: it names workspace' \
     && printf '%s' "$qout" | grep -q 'ignoring park record: parked' \
     && ! printf '%s' "$qout" | grep -q 'adopting session verify-session-ancient'; then
    ok "a-record-that-is-foreign-or-undatable-is-not-adopted"
  else
    bad "a-record-that-is-foreign-or-undatable-is-not-adopted" \
        "adoption must refuse another workspace's record and one past the TTL"
  fi

  # THE regression case, and the one no fixture can reach: the reactive check
  # must read the CURRENT attempt, not the append-only log.
  #
  # Attempt 1 is genuinely limited, and the provider does not say when the
  # window lifts. Attempt 2 resumes and dies of something else entirely -- a
  # dropped connection, an expired token -- before saying anything about quota
  # at all.
  #
  # Both halves of that stub are load-bearing, and each defeats a DIFFERENT
  # defence, which is the only way to isolate this one. Attempt 2's silence
  # means the newest snapshot in the append-only log is still attempt 1's, so
  # superseding a stale marker cannot save it. Attempt 1's missing resets_at
  # means that evidence never ages out, so dropping elapsed windows cannot save
  # it either. What is left is the question this case exists to ask: which file
  # did the reactive check read?
  #
  # Reading the attempt's own stream finds no rate-limit data, which is
  # `unknown`, which routes to the env: block this actually is. Reading the run
  # log finds attempt 1's exhausted window, parks, wakes, re-invokes, and finds
  # the same dead evidence again -- every POLL seconds, forever, spending quota
  # on each pass, while the card heartbeats and looks perfectly alive. MAX_WAIT
  # is 0 by default, so nothing bounds it. The watchdog is what turns that into
  # a red case rather than a suite that never returns.
  cat > "$qbin/codex" <<'QSTUB5'
#!/usr/bin/env bash
case "${1:-}" in --version) echo "codex-cli stub"; exit 0;; esac
for a in "$@"; do [ "$a" = resume ] && {
  printf '{"type":"event_msg","payload":{"type":"error","message":"connection reset by peer"}}\n'
  exit 7; }; done
printf '{"type":"session_meta","payload":{"session_id":"verify-session-11"}}\n'
printf '{"type":"event_msg","payload":{"type":"token_count","rate_limits":{"primary":{"used_percent":100.0}}}}\n'
exit 1
QSTUB5
  chmod +x "$qbin/codex"
  local qrt7="$qroot/runtime7"
  mkdir -p "$qrt7" && printf 'contract\n' > "$qrt7/contract.md"
  qout="$(_qrun 30 env PATH="$qbin:$PATH" STUBDIR="$qroot" CODEX_HOME="$qroot/codexhome" \
            FORGE_LANE_RUNTIME="$qrt7" FORGE_LANE_PARK_ROOT="$qpark" \
            FORGE_QUOTA_PAD=1 FORGE_QUOTA_POLL=1 FORGE_QUOTA_TICK=1 \
            "$runner" "$qws" qrun-7 qtask-7 2>&1)"
  qrc=$?
  # And the mechanism the case turns on, asserted directly: the run log
  # accumulates across attempts while the current-attempt log is truncated for
  # each one. If those two ever became the same file, every defence above is
  # reasoning about a distinction that no longer exists.
  if [ "$qrc" = 4 ] \
     && [ "$(printf '%s' "$qout" | grep -c PARKED)" = 1 ] \
     && printf '%s' "$qout" | grep -q 'no usage limit' \
     && grep -q used_percent "$qrt7/codex-events.jsonl" \
     && ! grep -q used_percent "$qrt7/codex-events.current.jsonl"; then
    ok "the-reactive-check-reads-the-current-attempt"
  else
    bad "the-reactive-check-reads-the-current-attempt" \
        "a later failure must be judged on the attempt's own stream, not the run's log (rc=$qrc)"
  fi

  # A knob that reads as garbage must not degrade quietly. MAX_WAIT=4h makes
  # every `-gt` test fail with `integer expression expected`, which && reads as
  # false -- silently removing the only bound on the wait. PARK_PCT=high reaches
  # argparse, which exits 2, leaving an empty verdict that turns every quota
  # block into a hard env: failure. Both must be usage errors, by name.
  local qrt8="$qroot/runtime8" qbadrc=0 qbadout
  mkdir -p "$qrt8" && printf 'contract\n' > "$qrt8/contract.md"
  qbadout="$(_qrun 60 env PATH="$qbin:$PATH" CODEX_HOME="$qroot/codexhome" \
               FORGE_LANE_RUNTIME="$qrt8" FORGE_LANE_PARK_ROOT="$qpark" \
               FORGE_QUOTA_MAX_WAIT=4h "$runner" "$qws" qrun-8 qtask-8 2>&1)"
  qbadrc=$?
  qout="$(_qrun 60 env PATH="$qbin:$PATH" CODEX_HOME="$qroot/codexhome" \
            FORGE_LANE_RUNTIME="$qrt8" FORGE_LANE_PARK_ROOT="$qpark" \
            FORGE_QUOTA_PARK_PCT=high "$runner" "$qws" qrun-8 qtask-8 2>&1)"
  qrc=$?
  if [ "$qbadrc" = 2 ] && [ "$qrc" = 2 ] \
     && printf '%s' "$qbadout" | grep -q 'FORGE_QUOTA_MAX_WAIT' \
     && printf '%s' "$qout" | grep -q 'FORGE_QUOTA_PARK_PCT'; then
    ok "a-knob-that-reads-as-garbage-is-a-usage-error"
  else
    bad "a-knob-that-reads-as-garbage-is-a-usage-error" \
        "an unparseable knob must exit 2 naming itself, not silently disable its own bound"
  fi

  # The record declares a schema and a successor parses it. A codex --version
  # carrying a quote must not be able to make the only route back into a
  # half-finished session unreadable.
  cat > "$qbin/codex" <<'QSTUB6'
#!/usr/bin/env bash
case "${1:-}" in --version) printf 'codex "quoted" \\ version\n'; exit 0;; esac
printf '{"type":"session_meta","payload":{"session_id":"verify-session-12"}}\n'
printf '{"type":"event_msg","payload":{"type":"token_count","rate_limits":{"primary":{"used_percent":100.0,"resets_at":9999999999}}}}\n'
exit 1
QSTUB6
  chmod +x "$qbin/codex"
  local qrt9="$qroot/runtime9"
