    # branch must be reachable without one, or the whole fix is theater.
    qm_sid=verify-model-1; qm_rollout=yes
    qm_diag="$(_qmodel_check "$runner" npr gpt-fixture-7 xhigh rollout '' "$qm_pin_model")" \
      || { qm_np_ok=0; qm_np_detail="$qm_np_detail requested-half($qm_diag)"; }
    # No override AND no readable rollout: CODEX_MODEL and CODEX_EFFORT must
    # both fall back to the resolved pin, never to empty — the two symptoms
    # this PR fixes. And the model half agrees with the pin here, so
    # REQUESTED must stay absent (the existing property, now proven on the
    # path that matters).
    qm_sid=verify-model-absent; qm_rollout=no
    qm_diag="$(_qmodel_check "$runner" npf "$qm_pin_model" "$qm_pin_effort" requested '' ABSENT)" \
      || { qm_np_ok=0; qm_np_detail="$qm_np_detail ran-half($qm_diag)"; }
  else
    qm_np_ok=0
    qm_np_detail=" could not read $PIN_FILE, or its model now equals the fixture rollout's — the check would prove nothing (F65)"
  fi
  [ "$qm_np_ok" = 1 ] \
    && ok "codex-model-requested-baseline-is-the-pin (no override, rollout disagrees: \$MODEL recorded as requested; no override, no rollout: \$MODEL and \$EFFORT fill FORGE_CODEX_MODEL_RAN and FORGE_CODEX_REASONING_EFFORT, never blank)" \
    || bad "codex-model-requested-baseline-is-the-pin" \
        "with no per-card override the requested baseline must be \$MODEL/\$EFFORT (the resolved pin, ADR-0018), not \${FORGE_CODEX_MODEL:-}/\"\" —$qm_np_detail"

  # Three mutants, each reverting exactly one line of this fix, each checked
  # against the ONE fixture it actually breaks. Reverting the model baseline
  # or the effort baseline against the rollout-disagrees fixture would not
  # show up there — the rollout overwrites both CODEX_MODEL and CODEX_EFFORT
  # regardless of what they were initialised to, so a baseline-only revert is
  # invisible there and only shows up with no rollout to read. Symmetrically
  # the guard-only revert never touches either RAN field; it only breaks
  # FORGE_CODEX_MODEL_REQUESTED.
  local qm_bp_ok=1 qm_bp_detail=""
  if [ "$qm_pin_ok" = 1 ]; then
    qmut="$(_qmodel_mutant baseline-reverts-to-the-override \
      's/CODEX_MODEL="\$MODEL"/CODEX_MODEL="${FORGE_CODEX_MODEL:-}"/')"
    if [ -z "$qmut" ]; then
      qm_bp_ok=0; qm_bp_detail="$qm_bp_detail baseline-mutation-changed-nothing(missed its line, F65)"
    else
      qm_sid=verify-model-absent; qm_rollout=no
      qm_diag="$(_qmodel_check "$qmut" x-baseline-reverts "$qm_pin_model" "$qm_pin_effort" requested '')"; qm_rc=$?
      if [ "$qm_rc" = 0 ]; then
        qm_bp_ok=0; qm_bp_detail="$qm_bp_detail baseline-mutant-was-accepted"
      elif ! printf '%s' "$qm_diag" | grep -Fq "the run was $qm_pin_model"; then
        qm_bp_ok=0
        qm_bp_detail="$qm_bp_detail baseline-diagnostic-did-not-name-the-pin($qm_diag)"
      fi
    fi

    qmut="$(_qmodel_mutant guard-reverts-to-the-override \
      's/-n "\$MODEL"/-n "${FORGE_CODEX_MODEL:-}"/')"
    if [ -z "$qmut" ]; then
      qm_bp_ok=0; qm_bp_detail="$qm_bp_detail guard-mutation-changed-nothing(missed its line, F65)"
    else
      qm_sid=verify-model-1; qm_rollout=yes
      qm_diag="$(_qmodel_check "$qmut" x-guard-reverts gpt-fixture-7 xhigh rollout '' "$qm_pin_model")"; qm_rc=$?
      if [ "$qm_rc" = 0 ]; then
        qm_bp_ok=0; qm_bp_detail="$qm_bp_detail guard-mutant-was-accepted"
      elif ! printf '%s' "$qm_diag" | grep -Fq 'FORGE_CODEX_MODEL_REQUESTED reads ""'; then
        qm_bp_ok=0
        qm_bp_detail="$qm_bp_detail guard-diagnostic-did-not-name-the-missing-key($qm_diag)"
      fi
    fi

    # The effort twin: reverting CODEX_EFFORT back to the historical hardcoded
    # "" (never a per-card override fallback — record_codex_model() ignored
    # $EFFORT/FORGE_CODEX_EFFORT entirely before this PR) is invisible on the
    # rollout-disagrees fixture for the same reason the model baseline mutant
    # is, so it is checked only on the no-rollout fixture.
    qmut="$(_qmodel_mutant effort-baseline-reverts-to-empty \
      's/CODEX_EFFORT="\$EFFORT"/CODEX_EFFORT=""/')"
    if [ -z "$qmut" ]; then
      qm_bp_ok=0; qm_bp_detail="$qm_bp_detail effort-mutation-changed-nothing(missed its line, F65)"
    else
      qm_sid=verify-model-absent; qm_rollout=no
      qm_diag="$(_qmodel_check "$qmut" x-effort-reverts "$qm_pin_model" "$qm_pin_effort" requested '')"; qm_rc=$?
      if [ "$qm_rc" = 0 ]; then
        qm_bp_ok=0; qm_bp_detail="$qm_bp_detail effort-mutant-was-accepted"
      elif ! printf '%s' "$qm_diag" | grep -Fq "the run was $qm_pin_model/$qm_pin_effort/requested"; then
        qm_bp_ok=0
        qm_bp_detail="$qm_bp_detail effort-diagnostic-did-not-name-the-pin($qm_diag)"
      fi
    fi
  else
    qm_bp_ok=0
    qm_bp_detail=" could not read $PIN_FILE, or its model now equals the fixture rollout's (F65)"
  fi
  [ "$qm_bp_ok" = 1 ] \
    && ok "codex-model-requested-baseline-is-the-pin-mutation-is-caught (model baseline reverts to the override, guard reverts to the override, effort baseline reverts to empty)" \
    || bad "codex-model-requested-baseline-is-the-pin-mutation-is-caught" \
        "a runner that reverts either baseline, or the guard, must redden codex-model-requested-baseline-is-the-pin —$qm_bp_detail"

  # ---- THE PIN IS PASSED, NOT INHERITED -----------------------------------
  #
  # The Codex desktop app rewrote ~/.codex/config.toml on 2026-09-08 at
  # 10:08:47 — no human edit — and the chunk authored under it three hours
  # later was approved with nothing naming the model. The repair is that the
  # runner STATES the pin out of scripts/model-pins.sh, so that file stops
  # governing unattended runs and the desktop app may rewrite it freely.
  #
  # This REPLACES config/codex-pin-live, which asserted the opposite: that the
  # live ~/.codex/config.toml agreed with the checked-in pair. That file is no
  # longer authoritative, so agreement with it is no longer a property worth
  # holding. The assertion also moves out of config/, which returns early
  # without hermes and is absent from CI, into a group that is offline and runs
  # on every pull request — the same argument cli/model-pin-documented makes
  # for the driver pin.
  #
  # It RUNS the runner rather than grepping its source, because the property is
  # about argv on TWO branches. Of the model-affecting flags, `codex exec
  # resume` accepts only -m and -c (measured, codex-cli 0.153.4), so a refactor
  # that kept the pin on one branch alone would silently inherit
  # ~/.codex/config.toml on the other — and resume is not an edge case, it is
  # what every ADR-0016 park comes back through. A grep for the flag "somewhere
  # in the file" cannot see that; two recorded argvs can.
  cat > "$qbin/pin-echo" <<'QPIN'
#!/usr/bin/env bash
case "${1:-}" in --version) echo "pin-echo stub"; exit 0;; esac
for a in "$@"; do
  if [ "$a" = resume ]; then
    printf '%s\n' "$*" > "$STUBDIR/pin-argv-resume"
    printf '{"type":"event_msg","payload":{"type":"agent_message","message":"done"}}\n'
    exit 0
  fi
done
printf '%s\n' "$*" > "$STUBDIR/pin-argv-first"
printf '{"type":"session_meta","payload":{"session_id":"verify-pin-1"}}\n'
printf '{"type":"event_msg","payload":{"type":"token_count","rate_limits":{"primary":{"used_percent":100.0,"resets_at":%d}}}}\n' "$(( $(date +%s) + 2 ))"
printf '{"type":"event_msg","payload":{"type":"error","error_type":"usage_limit_reached"}}\n'
exit 1
QPIN
  chmod +x "$qbin/pin-echo"

  local qpin_model="" qpin_effort="" qpin_case
  load_model_pins && { qpin_model="$PIN_CODEX_MODEL"; qpin_effort="$PIN_CODEX_EFFORT"; }

  # BOTH argv files are read, and EITHER one missing a flag fails. Asserting on
  # the two concatenated would pass a runner that pins only the resume call,
  # which is precisely the refactor this case exists to refuse.
  _qpin_check() { # <runner> <suffix> -> diagnostic on stdout, 1 when a branch lost the pin
    # `rt` on its own `local`: bash expands every word of a `local` before it
    # assigns any of them, so `rt="$qroot/runtime-$suffix"` on the line that
    # sets `suffix` reads an unbound variable and dies at 127 under `set -u`.
    # _qmodel_check above splits it for the same reason.
    local prunner="$1" suffix="$2" out rc branch f
    local rt="$qroot/runtime-$suffix"
    rm -rf "$rt"; mkdir -p "$rt"; printf 'contract\n' > "$rt/contract.md"
    rm -f "$qroot/pin-argv-first" "$qroot/pin-argv-resume"
    out="$(_qrun 60 env PATH="$qbin:$PATH" STUBDIR="$qroot" CODEX_HOME="$qroot/codexhome" \
             FORGE_LANE_RUNTIME="$rt" FORGE_LANE_PARK_ROOT="$qpark" \
             FORGE_QUOTA_PAD=1 FORGE_QUOTA_POLL=1 FORGE_QUOTA_TICK=1 \
             FORGE_CODEX_BIN="$qbin/pin-echo" \
             "$prunner" "$qws" "run-$suffix" "task-$suffix" 2>&1)"
    rc=$?
    printf '%s\n' "$out" > "$qroot/pin-run-$suffix.log"
    [ "$rc" = 0 ] \
      || { printf 'the runner exited %s instead of parking and resuming cleanly\n' "$rc"; return 1; }
    for branch in first resume; do
      f="$qroot/pin-argv-$branch"
      [ -s "$f" ] \
        || { printf 'the %s attempt recorded no argv at all\n' "$branch"; return 1; }
      grep -Fq -- "-m $qpin_model" "$f" \
        || { printf 'the %s attempt argv carries no -m %s: %s\n' \
                    "$branch" "$qpin_model" "$(cat "$f")"; return 1; }
      grep -Fq -- "model_reasoning_effort=\"$qpin_effort\"" "$f" \
        || { printf 'the %s attempt argv carries no -c model_reasoning_effort=%s: %s\n' \
                    "$branch" "$qpin_effort" "$(cat "$f")"; return 1; }
    done
    return 0
  }

  if [ -z "$qpin_model" ] || [ -z "$qpin_effort" ]; then
    # An empty expectation makes every `grep -Fq` above match anything, so this
    # guard IS the check rather than a defensive extra — cli/codex-pin-documented
    # learned that the hard way. And a pin file this case cannot read is its own
    # source of truth going missing, which is bad, never skip.
    for qpin_case in codex-pin-is-passed-not-inherited \
                     codex-pin-on-the-fresh-branch-mutation-is-caught \
                     codex-pin-on-the-resume-branch-mutation-is-caught; do
      bad "$qpin_case" \
          "could not source $PIN_FILE for the Codex pin — the check went blind, which is not a pass (F65)"
    done
  else
    local qpin_diag qpin_rc
    qpin_diag="$(_qpin_check "$runner" pin)"; qpin_rc=$?
    if [ "$qpin_rc" = 0 ]; then
      ok "codex-pin-is-passed-not-inherited ($qpin_model/$qpin_effort on both argv branches)"
    else
      bad "codex-pin-is-passed-not-inherited" \
          "codex exec AND codex exec resume must each carry -m and -c model_reasoning_effort out of $PIN_FILE — $qpin_diag"
    fi

    # One mutant per branch. The pin sits on build_argv's common path, so the
    # mutation that models "stripped from the other branch" is to make that one
    # line conditional on the branch it must NOT be confined to. Copies under
    # $TMPROOT beside the helper symlinks, never the tracked file: a mutation
    # harness that edits in place leaves a live defect behind when it is killed,
    # and neither the pushed head nor CI can see that.
    _qpin_mutant_case() { # <case> <mutant> <sed program> <expected diagnostic>
      local cname="$1" mname="$2" mprog="$3" want="$4" mpath mdiag mrc
      mpath="$(_qmodel_mutant "$mname" "$mprog")"
      if [ -z "$mpath" ]; then
        bad "$cname" \
            "the mutation changed nothing, so this case proves nothing — it missed the line it was aimed at (F65)"
        return
      fi
      mdiag="$(_qpin_check "$mpath" "x-$mname")"; mrc=$?
      if [ "$mrc" = 0 ]; then
        bad "$cname" "a runner that drops the pin from that argv branch was accepted"
      elif ! printf '%s' "$mdiag" | grep -Fq "$want"; then
        bad "$cname" \
            "the mutant reddened for the wrong reason; expected a diagnostic naming '$want', got: ${mdiag:-none}"
      else
        ok "$cname"
      fi
    }
    _qpin_mutant_case codex-pin-on-the-fresh-branch-mutation-is-caught \
      pin-not-on-fresh \
      's/^  ARGV=\(.*model_reasoning_effort.*\)$/  [ -n "${SESSION_ID:-}" ] \&\& ARGV=\1/' \
      'the first attempt argv carries no -m'
    _qpin_mutant_case codex-pin-on-the-resume-branch-mutation-is-caught \
      pin-not-on-resume \
      's/^  ARGV=\(.*model_reasoning_effort.*\)$/  [ -z "${SESSION_ID:-}" ] \&\& ARGV=\1/' \
      'the resume attempt argv carries no -m'
  fi

  # ---- THE SANDBOX GRANT NAMES BOTH GIT ROOTS ------------------------------
  #
  # codex-cli 0.164.0 (installed 2026-10-25; 0.157.1 before it) stopped letting
  # a `workspace-write` sandbox write a linked worktree's OWN gitdir
  # (`<common>/worktrees/<name>/`) on the strength of a grant for the common dir
  # alone: `git add` died on `index.lock: Operation not permitted`. Rehearsals
  # 1-6 committed anyway, only because ~/.codex/config.toml carried
  # approvals_reviewer = "auto_review", which approved an escalated retry. This
  # case is the free witness that the runner now states both roots itself, on
  # BOTH argv branches -- `codex exec` takes --add-dir, `codex exec resume`
  # takes only the equivalent -c override, and a refactor that fixed one would
  # leave every ADR-0016 park coming back through the broken grant.
  #
  # The argv is recorded by a stub codex from the REAL runner, one word per
  # line, and the expectation is derived here from git itself rather than from
  # a copy of the runner's string. The main-checkout case is the other half of
  # the contract: there the gitdir IS the common dir, and it is granted once.
  cat > "$qbin/roots-echo" <<'QROOTS'
#!/usr/bin/env bash
case "${1:-}" in --version) echo "roots-echo stub"; exit 0;; esac
for a in "$@"; do
  if [ "$a" = resume ]; then
    printf '%s\n' "$@" > "$STUBDIR/roots-argv-resume"
    printf '{"type":"event_msg","payload":{"type":"agent_message","message":"done"}}\n'
    exit 0
  fi
done
printf '%s\n' "$@" > "$STUBDIR/roots-argv-first"
printf '{"type":"session_meta","payload":{"session_id":"verify-roots-1"}}\n'
printf '{"type":"event_msg","payload":{"type":"token_count","rate_limits":{"primary":{"used_percent":100.0,"resets_at":%d}}}}\n' "$(( $(date +%s) + 2 ))"
printf '{"type":"event_msg","payload":{"type":"error","error_type":"usage_limit_reached"}}\n'
exit 1
QROOTS
  chmod +x "$qbin/roots-echo"

  local qroots_linked="$qroot/ws-linked"
  ( cd "$qws" && git worktree add -q "$qroots_linked" -b qroots-linked ) >/dev/null 2>&1

  _qroots_check() { # <runner> <suffix> <workspace> -> diagnostic on stdout, 1 when a branch lost a root
    local rrunner="$1" suffix="$2" rws="$3" out rc f exp_common exp_gitdir
    local rt="$qroot/runtime-$suffix"
    rm -rf "$rt"; mkdir -p "$rt"; printf 'contract\n' > "$rt/contract.md"
    rm -f "$qroot/roots-argv-first" "$qroot/roots-argv-resume" "$qpark/task-$suffix.json"
    # What git itself says, resolved the way the runner resolves it (pwd -P, so
    # /var and /private/var cannot disagree).
    exp_common="$(cd "$rws" && cd "$(git rev-parse --git-common-dir)" && pwd -P)"
    exp_gitdir="$(cd "$rws" && cd "$(git rev-parse --absolute-git-dir)" && pwd -P)"
    out="$(_qrun 60 env PATH="$qbin:$PATH" STUBDIR="$qroot" CODEX_HOME="$qroot/codexhome" \
             FORGE_LANE_RUNTIME="$rt" FORGE_LANE_PARK_ROOT="$qpark" \
             FORGE_QUOTA_PAD=1 FORGE_QUOTA_POLL=1 FORGE_QUOTA_TICK=1 \
             FORGE_CODEX_BIN="$qbin/roots-echo" \
             "$rrunner" "$rws" "run-$suffix" "task-$suffix" 2>&1)"
    rc=$?
    printf '%s\n' "$out" > "$qroot/roots-run-$suffix.log"
    [ "$rc" = 0 ] \
      || { printf 'the runner exited %s instead of parking and resuming cleanly\n' "$rc"; return 1; }
    local want_dirs want_toml
    if [ "$exp_gitdir" = "$exp_common" ]; then
      want_dirs="$exp_common"
      want_toml="sandbox_workspace_write.writable_roots=[\"$exp_common\"]"
    else
      want_dirs="$exp_common
$exp_gitdir"
      want_toml="sandbox_workspace_write.writable_roots=[\"$exp_common\",\"$exp_gitdir\"]"
    fi
    f="$qroot/roots-argv-first"
    [ -s "$f" ] || { printf 'the first attempt recorded no argv at all\n'; return 1; }
    local got_dirs; got_dirs="$(awk 'p { print; p = 0 } $0 == "--add-dir" { p = 1 }' "$f")"
    [ "$got_dirs" = "$want_dirs" ] \
      || { printf 'the first attempt grants --add-dir {%s}, expected {%s}\n' \
                  "$(printf '%s' "$got_dirs" | tr '\n' ' ')" "$(printf '%s' "$want_dirs" | tr '\n' ' ')"; return 1; }
    f="$qroot/roots-argv-resume"
    [ -s "$f" ] || { printf 'the resume attempt recorded no argv at all\n'; return 1; }
    local got_toml; got_toml="$(grep '^sandbox_workspace_write\.writable_roots=' "$f")"
    [ "$got_toml" = "$want_toml" ] \
      || { printf 'the resume attempt grants {%s}, expected {%s}\n' "$got_toml" "$want_toml"; return 1; }
    return 0
  }

  local qroots_diag qroots_rc qroots_dist
  qroots_dist="$(cd "$qroots_linked" 2>/dev/null && [ "$(cd "$(git rev-parse --absolute-git-dir)" && pwd -P)" != "$(cd "$(git rev-parse --git-common-dir)" && pwd -P)" ] && echo linked)"
  if [ "$qroots_dist" != linked ]; then
    bad "codex-run-grants-both-git-roots" \
        "the linked-worktree fixture is not linked (gitdir == common dir), so the case would prove nothing"
  else
    qroots_diag="$(_qroots_check "$runner" roots-linked "$qroots_linked")"; qroots_rc=$?
    if [ "$qroots_rc" = 0 ]; then
      ok "codex-run-grants-both-git-roots (common dir + worktree gitdir on the fresh --add-dir and the resume writable_roots)"
    else
      bad "codex-run-grants-both-git-roots" \
          "a linked worktree needs its own gitdir granted beside the common dir on BOTH branches (codex-cli 0.164) — $qroots_diag"
    fi
  fi
  qroots_diag="$(_qroots_check "$runner" roots-main "$qws")"; qroots_rc=$?
  if [ "$qroots_rc" = 0 ]; then
    ok "codex-run-grants-a-main-checkout-root-once (gitdir == common dir: one root, no duplicate)"
  else
    bad "codex-run-grants-a-main-checkout-root-once" \
        "in a main checkout the gitdir is the common dir and must be granted exactly once on both branches — $qroots_diag"
  fi

  # The print mode is what preflight and the paid verify probe read, so it is
  # held to the same expectation as the argv: the same roots, one per line, and
  # on a failure NOTHING on stdout (an `env:` line there would be read as a root).
  local qpr_bad="" qpr_out qpr_exp
  qpr_out="$(bash "$runner" --print-sandbox-roots "$qroots_linked" 2>/dev/null)"
  qpr_exp="$(cd "$qroots_linked" && cd "$(git rev-parse --git-common-dir)" && pwd -P)
$(cd "$qroots_linked" && cd "$(git rev-parse --absolute-git-dir)" && pwd -P)"
  [ "$qpr_out" = "$qpr_exp" ] || qpr_bad="$qpr_bad linked"
  qpr_out="$(bash "$runner" --print-sandbox-roots "$qws" 2>/dev/null)"
  qpr_exp="$(cd "$qws" && cd "$(git rev-parse --git-common-dir)" && pwd -P)"
  [ "$qpr_out" = "$qpr_exp" ] || qpr_bad="$qpr_bad main"
  qpr_out="$(bash "$runner" --print-sandbox-roots "$qroot/no-such-workspace" 2>/dev/null)"
  [ -z "$qpr_out" ] || qpr_bad="$qpr_bad stdout-on-error"
  bash "$runner" --print-sandbox-roots "$qroot/no-such-workspace" >/dev/null 2>&1
  [ "$?" = 3 ] || qpr_bad="$qpr_bad exit-code"
  if [ -z "$qpr_bad" ]; then
    ok "codex-run-prints-the-roots-it-grants (linked: common dir + gitdir; main checkout: one; a missing workspace: exit 3 and an empty stdout)"
  else
    bad "codex-run-prints-the-roots-it-grants" "--print-sandbox-roots misreported:$qpr_bad"
  fi

  _qroots_mutant_case() { # <case> <mutant> <sed program> <expected diagnostic> [workspace]
    local cname="$1" mname="$2" mprog="$3" want="$4" mws="${5:-$qroots_linked}" mpath mdiag mrc
    mpath="$(_qmodel_mutant "$mname" "$mprog")"
    if [ -z "$mpath" ]; then
      bad "$cname" \
          "the mutation changed nothing, so this case proves nothing — a moved call site must FAIL, not skip (F65)"
      return
    fi
    mdiag="$(_qroots_check "$mpath" "x-$mname" "$mws")"; mrc=$?
    if [ "$mrc" = 0 ]; then
      bad "$cname" "a runner that drops the worktree gitdir from that argv branch was accepted"
    elif ! printf '%s' "$mdiag" | grep -Fq "$want"; then
      bad "$cname" \
          "the mutant reddened for the wrong reason; expected a diagnostic naming '$want', got: ${mdiag:-none}"
    else
      ok "$cname"
    fi
  }
  _qroots_mutant_case codex-run-gitdir-dropped-on-the-fresh-branch-mutation-is-caught \
    roots-not-on-fresh \
    's/^    for froot in "${SANDBOX_ROOTS\[@\]}"; do$/    for froot in "$GIT_COMMON"; do/' \
    'the first attempt grants'
  _qroots_mutant_case codex-run-gitdir-dropped-on-the-resume-branch-mutation-is-caught \
    roots-not-on-resume \
    's/^    for rroot in "${SANDBOX_ROOTS\[@\]}"; do$/    for rroot in "$GIT_COMMON"; do/' \
    'the resume attempt grants'
  _qroots_mutant_case codex-run-gitdir-never-resolved-mutation-is-caught \
    roots-never-resolved \
    's/^    SANDBOX_ROOTS=("${SANDBOX_ROOTS\[@\]}" "$GIT_DIR_ABS")$/    :/' \
    'the first attempt grants'
  # The other direction: a runner that stops comparing the two directories
  # grants a main checkout's single root twice, and must be refused there.
  _qroots_mutant_case codex-run-duplicate-root-in-a-main-checkout-mutation-is-caught \
    roots-duplicated \
    's/^  if \[ "$GIT_DIR_ABS" != "$GIT_COMMON" \]; then$/  if true; then/' \
    'the first attempt grants' "$qws"

  # ---- THE APPROVAL POLICY IS PINNED, NOT INHERITED ------------------------
  #
  # The same failure as the model pin, one key over. Rehearsals 1-6 ran under
  # the Codex default plus `approvals_reviewer = "auto_review"` out of
  # ~/.codex/config.toml (a file the desktop app rewrites), and every
  # sandbox-refused `git add` / `git commit` was escalated and approved. The
  # runner now states `-c approval_policy="never"` itself, so a refusal is a
  # plain failure and run A no longer depends on user config. `codex exec` has
  # no -a flag (0.164.0); -c is the form, and it is the one `exec resume`
  # accepts too -- so, as with the model pin, the property is about argv on TWO
  # branches and is read off two recorded argvs, not off the source.
  #
  # Reuses the roots-echo stub (it records one argv word per line on each
  # branch). The key must follow a `-c` word: a line that merely mentions it,
  # or a `-c` for some other key, is not the pin.
  _qappr_check() { # <runner> <suffix> -> diagnostic on stdout, 1 when a branch lost the pin
    local arunner="$1" suffix="$2" out rc branch f
    local rt="$qroot/runtime-$suffix"
    rm -rf "$rt"; mkdir -p "$rt"; printf 'contract\n' > "$rt/contract.md"
    rm -f "$qroot/roots-argv-first" "$qroot/roots-argv-resume" "$qpark/task-$suffix.json"
    out="$(_qrun 60 env PATH="$qbin:$PATH" STUBDIR="$qroot" CODEX_HOME="$qroot/codexhome" \
             FORGE_LANE_RUNTIME="$rt" FORGE_LANE_PARK_ROOT="$qpark" \
             FORGE_QUOTA_PAD=1 FORGE_QUOTA_POLL=1 FORGE_QUOTA_TICK=1 \
             FORGE_CODEX_BIN="$qbin/roots-echo" \
             "$arunner" "$qws" "run-$suffix" "task-$suffix" 2>&1)"
    rc=$?
    printf '%s\n' "$out" > "$qroot/appr-run-$suffix.log"
    [ "$rc" = 0 ] \
      || { printf 'the runner exited %s instead of parking and resuming cleanly\n' "$rc"; return 1; }
    for branch in first resume; do
      f="$qroot/roots-argv-$branch"
      [ -s "$f" ] \
        || { printf 'the %s attempt recorded no argv at all\n' "$branch"; return 1; }
      awk 'p && $0 == "approval_policy=\"never\"" { f = 1 } { p = ($0 == "-c") } END { exit !f }' "$f" \
        || { printf 'the %s attempt argv carries no -c approval_policy="never": %s\n' \
                    "$branch" "$(tr '\n' ' ' < "$f")"; return 1; }
    done
    return 0
  }
  local qappr_diag qappr_rc
  qappr_diag="$(_qappr_check "$runner" appr)"; qappr_rc=$?
  if [ "$qappr_rc" = 0 ]; then
    ok "codex-run-pins-approval-never-on-both-branches (-c approval_policy=\"never\" on the fresh exec and on exec resume)"
  else
    bad "codex-run-pins-approval-never-on-both-branches" \
        "codex exec AND codex exec resume must each carry -c approval_policy=\"never\", or a sandbox refusal can be auto-approved as an escalation — $qappr_diag"
  fi
  _qappr_mutant_case() { # <case> <mutant> <sed program> <expected diagnostic>
    local cname="$1" mname="$2" mprog="$3" want="$4" mpath mdiag mrc
    mpath="$(_qmodel_mutant "$mname" "$mprog")"
    if [ -z "$mpath" ]; then
      bad "$cname" \
          "the mutation changed nothing, so this case proves nothing — a moved call site must FAIL, not skip (F65)"
      return
    fi
    mdiag="$(_qappr_check "$mpath" "x-$mname")"; mrc=$?
    if [ "$mrc" = 0 ]; then
      bad "$cname" "a runner that drops the approval pin from that argv branch was accepted"
    elif ! printf '%s' "$mdiag" | grep -Fq "$want"; then
      bad "$cname" \
          "the mutant reddened for the wrong reason; expected a diagnostic naming '$want', got: ${mdiag:-none}"
    else
      ok "$cname"
    fi
  }
  _qappr_mutant_case codex-run-approval-pin-on-the-fresh-branch-mutation-is-caught \
    approval-not-on-fresh \
    's/^  ARGV=\(.*approval_policy.*\)$/  [ -n "${SESSION_ID:-}" ] \&\& ARGV=\1/' \
    'the first attempt argv carries no -c approval_policy'
  _qappr_mutant_case codex-run-approval-pin-on-the-resume-branch-mutation-is-caught \
    approval-not-on-resume \
    's/^  ARGV=\(.*approval_policy.*\)$/  [ -z "${SESSION_ID:-}" ] \&\& ARGV=\1/' \
    'the resume attempt argv carries no -c approval_policy'
  _qappr_mutant_case codex-run-approval-pin-wrong-value-mutation-is-caught \
    approval-wrong-value \
    's/approval_policy="never"/approval_policy="on-request"/' \
    'the first attempt argv carries no -c approval_policy'

  # ---- THE ROLLOUT CHECK READS WHAT CODEX DID, AND FAILS ON NOTHING ----------
  #
  # scripts/codex-rollout-check.py is rehearsal 7's extra pass check
  # (docs/run-a.md, amendment 6): the lane's Codex rollouts for one worktree must
  # show no `index.lock': Operation not permitted` and no escalated retry. It is
  # the only reader of that fact, so these cases hold its four failure modes
  # apart: a denial, an escalation (a tool CALL, not the schema prose every
  # rollout carries), an auto-review sub-thread, and -- the one a lazy check
  # gets wrong -- finding no rollout at all, which verified nothing and is
  # never a pass. The clock is pinned: every fixture carries its own timestamp
  # and the window is passed explicitly, so no case depends on today's date.
  local qrc_check="$REPO_ROOT/scripts/codex-rollout-check.py"
  local qrc_root="$qroot/rollouts" qrc_cwd="$qroot/hello-wt" qrc_since=1793311253
  rm -rf "$qrc_root"; mkdir -p "$qrc_root/2026/10/29" "$qrc_cwd"
  _qrc_rollout() { # <name> <thread_source> <body lines...>  -> writes one rollout for $qrc_cwd
    local name="$1" tsrc="$2"; shift 2
    local f="$qrc_root/2026/10/29/rollout-2026-10-29T23-01-06-$name.jsonl"
    printf '{"type":"session_meta","payload":{"id":"%s","timestamp":"2026-10-29T22:01:06.159Z","cwd":"%s","originator":"codex_exec","cli_version":"0.164.0","thread_source":"%s","base_instructions":"schema: sandbox_permissions require_escalated is prose here"}}\n' \
      "$name" "$qrc_cwd" "$tsrc" > "$f"
    local l; for l in "$@"; do printf '%s\n' "$l" >> "$f"; done
  }
  local qrc_msg='{"type":"response_item","payload":{"type":"message","role":"developer","content":"tool schema: sandbox_permissions=require_escalated is how a command asks to leave the sandbox"}}'
  local qrc_ok='{"type":"response_item","payload":{"type":"custom_tool_call","name":"exec","input":"const r = await tools.exec_command({cmd:\"git commit -m x\",\"workdir\":\"/w\"});"}}'
  local qrc_deny='{"type":"response_item","payload":{"type":"custom_tool_call_output","output":"fatal: Unable to create '"'"'/c/.git/worktrees/t/index.lock'"'"': Operation not permitted"}}'
  local qrc_esc='{"type":"response_item","payload":{"type":"custom_tool_call","name":"exec","input":"const r = await tools.exec_command({cmd:\"git add x\",\"sandbox_permissions\":\"require_escalated\",\"justification\":\"stage\"});"}}'
  _qrc_run() { # <check> [extra args...] -> "rc" on stdout
    local chk="$1"; shift
    python3 -I "$chk" --cwd "$qrc_cwd" --since "$qrc_since" --sessions "$qrc_root" "$@" >"$qroot/rollout-check.out" 2>&1
    printf '%s' "$?"
  }
  local qrc_got

  _qrc_rollout clean exec "$qrc_msg" "$qrc_ok"
  qrc_got="$(_qrc_run "$qrc_check")"
  if [ "$qrc_got" = 0 ] && grep -q '^clean' "$qroot/rollout-check.out"; then
    ok "codex-rollout-check-passes-a-clean-run (schema prose naming require_escalated is not an escalation)"
  else
    bad "codex-rollout-check-passes-a-clean-run" \
        "a rollout with no denial and no escalated call must exit 0, got $qrc_got: $(tr '\n' ' ' < "$qroot/rollout-check.out")"
  fi

  qrc_got=""; local qrc_bad="" qrc_case
  for qrc_case in denial escalation guardian; do
    rm -f "$qrc_root"/2026/10/29/*.jsonl
    case "$qrc_case" in
      denial)     _qrc_rollout "$qrc_case" exec "$qrc_msg" "$qrc_deny" ;;
      escalation) _qrc_rollout "$qrc_case" exec "$qrc_msg" "$qrc_esc" ;;
      guardian)   _qrc_rollout "$qrc_case" guardian_review "$qrc_msg" ;;
    esac
    [ "$(_qrc_run "$qrc_check")" = 1 ] || qrc_bad="$qrc_bad $qrc_case"
  done
  if [ -z "$qrc_bad" ]; then
    ok "codex-rollout-check-fails-on-a-denial-an-escalation-or-an-auto-review-thread"
  else
    bad "codex-rollout-check-fails-on-a-denial-an-escalation-or-an-auto-review-thread" \
        "exit 1 expected for each; not produced for:$qrc_bad"
  fi

  # The grant the lane's Codex RECORDED, against the roots the runner meant to
  # give it. Nothing free proves that `codex exec` maps two --add-dir flags to
  # two writable roots; the rollout's turn_context is the first place that is
  # observable. Rehearsal 6's recorded
  # roots held the common dir alone.
  local qrc_tc_both qrc_tc_common
  qrc_tc_both='{"type":"turn_context","payload":{"sandbox_policy":{"type":"workspace-write","writable_roots":["'"$qroot"'/c","'"$qroot"'/c/worktrees/t"]}}}'
  qrc_tc_common='{"type":"turn_context","payload":{"sandbox_policy":{"type":"workspace-write","writable_roots":["'"$qroot"'/c"]}}}'
  qrc_bad=""
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout roots exec "$qrc_msg" "$qrc_tc_both" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check" --expect-root "$qroot/c" --expect-root "$qroot/c/worktrees/t")" = 0 ] || qrc_bad="$qrc_bad both-granted"
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout roots exec "$qrc_msg" "$qrc_tc_common" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check" --expect-root "$qroot/c" --expect-root "$qroot/c/worktrees/t")" = 1 ] || qrc_bad="$qrc_bad gitdir-missing"
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout roots exec "$qrc_msg" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check" --expect-root "$qroot/c")" = 2 ] || qrc_bad="$qrc_bad no-policy-recorded"
  if [ -z "$qrc_bad" ]; then
    ok "codex-rollout-check-reads-the-granted-roots (both roots recorded: 0; the gitdir absent: 1; no policy recorded: 2)"
  else
    bad "codex-rollout-check-reads-the-granted-roots" "--expect-root misjudged:$qrc_bad"
  fi

  # The approval policy the lane's Codex RECORDED, against the one the runner
  # pinned (quota/codex-run-pins-approval-never-on-both-branches proves the
  # argv; this is the only place `codex exec` honouring it is observable).
  # Rehearsal 6's turn_context read on-request -- that real rollout is the
  # negative control the PR for this check was measured against.
  local qrc_ap_never qrc_ap_req qrc_ap_none
  qrc_ap_never='{"type":"turn_context","payload":{"approval_policy":"never","approvals_reviewer":"user","sandbox_policy":{"type":"workspace-write","writable_roots":["'"$qroot"'/c"]}}}'
  qrc_ap_req='{"type":"turn_context","payload":{"approval_policy":"on-request","approvals_reviewer":"auto_review","sandbox_policy":{"type":"workspace-write","writable_roots":["'"$qroot"'/c"]}}}'
  qrc_ap_none='{"type":"turn_context","payload":{"sandbox_policy":{"type":"workspace-write","writable_roots":["'"$qroot"'/c"]}}}'
  qrc_bad=""
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout appr exec "$qrc_msg" "$qrc_ap_never" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check" --expect-approval never)" = 0 ] || qrc_bad="$qrc_bad never-recorded"
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout appr exec "$qrc_msg" "$qrc_ap_req" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check" --expect-approval never)" = 1 ] \
    && grep -q '^FINDING approval_policy on-request was recorded, expected never' "$qroot/rollout-check.out" \
    || qrc_bad="$qrc_bad on-request-recorded"
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout appr exec "$qrc_msg" "$qrc_ap_never" "$qrc_ap_req" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check" --expect-approval never)" = 1 ] || qrc_bad="$qrc_bad one-turn-on-request"
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout appr exec "$qrc_msg" "$qrc_ap_none" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check" --expect-approval never)" = 2 ] || qrc_bad="$qrc_bad no-policy-recorded"
  # Not asked for, not read: the flag is opt-in, as --expect-root is.
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout appr exec "$qrc_msg" "$qrc_ap_req" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check")" = 0 ] || qrc_bad="$qrc_bad not-asked"
  if [ -z "$qrc_bad" ]; then
    ok "codex-rollout-check-reads-the-approval-policy (never recorded: 0; on-request: 1; one turn on-request: 1; none recorded: 2; flag absent: unread)"
  else
    bad "codex-rollout-check-reads-the-approval-policy" "--expect-approval misjudged:$qrc_bad"
  fi

  # Exit 1 outranks exit 2. Exit 2 reads as "no rollout found"; if a denial, an
  # escalation or a wrong policy WAS found, an unobserved policy or root must not
  # turn that into 2. And a lane turn that recorded no approval_policy while
  # others did is a finding, not something to skip.
  local qrc_ap_nosb
  qrc_ap_nosb='{"type":"turn_context","payload":{"approval_policy":"on-request"}}'
  qrc_bad=""
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout o exec "$qrc_msg" "$qrc_deny" "$qrc_ap_none"
  [ "$(_qrc_run "$qrc_check" --expect-approval never)" = 1 ] || qrc_bad="$qrc_bad denial-and-no-policy"
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout o exec "$qrc_msg" "$qrc_deny" "$qrc_ap_nosb"
  [ "$(_qrc_run "$qrc_check" --expect-root "$qroot/c")" = 1 ] || qrc_bad="$qrc_bad denial-and-no-sandbox-policy"
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout o exec "$qrc_msg" "$qrc_ap_nosb" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check" --expect-root "$qroot/c" --expect-approval never)" = 1 ] || qrc_bad="$qrc_bad wrong-policy-and-no-sandbox-policy"
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout o exec "$qrc_msg" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check" --expect-root "$qroot/c" --expect-approval never)" = 2 ] || qrc_bad="$qrc_bad nothing-recorded-stays-2"
  if [ -z "$qrc_bad" ]; then
    ok "codex-rollout-check-a-finding-outranks-not-observed (a denial or a wrong policy with an unrecorded policy or root is exit 1; nothing recorded and nothing found stays exit 2)"
  else
    bad "codex-rollout-check-a-finding-outranks-not-observed" "exit 1 must win over exit 2:$qrc_bad"
  fi
  qrc_bad=""
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  _qrc_rollout u exec "$qrc_msg" "$qrc_ap_never" "$qrc_ap_none" "$qrc_ok"
  [ "$(_qrc_run "$qrc_check" --expect-approval never)" = 1 ] \
    && grep -q '^FINDING 1 turn_context(s) of the lane.s Codex recorded no approval_policy' "$qroot/rollout-check.out" \
    || qrc_bad="$qrc_bad one-turn-unpinned"
  if [ -z "$qrc_bad" ]; then
    ok "codex-rollout-check-a-turn-with-no-approval-policy-is-a-finding (never on one turn, none on another: exit 1 naming it)"
  else
    bad "codex-rollout-check-a-turn-with-no-approval-policy-is-a-finding" "a lane turn with no approval_policy was skipped:$qrc_bad"
  fi

  # Nothing to read is exit 2, and three different ways of having nothing are
  # held apart: an empty tree, a rollout for another worktree, and one outside
  # the time window.
  rm -f "$qrc_root"/2026/10/29/*.jsonl
  qrc_bad=""
  [ "$(_qrc_run "$qrc_check")" = 2 ] || qrc_bad="$qrc_bad empty-tree"
  _qrc_rollout clean exec "$qrc_msg" "$qrc_ok"
  [ "$(python3 -I "$qrc_check" --cwd "$qroot/some-other-wt" --since "$qrc_since" --sessions "$qrc_root" >/dev/null 2>&1; printf '%s' "$?")" = 2 ] \
    || qrc_bad="$qrc_bad other-cwd"
  [ "$(python3 -I "$qrc_check" --cwd "$qrc_cwd" --since 1793400000 --sessions "$qrc_root" >/dev/null 2>&1; printf '%s' "$?")" = 2 ] \
    || qrc_bad="$qrc_bad outside-window"
  [ "$(python3 -I "$qrc_check" --cwd "$qrc_cwd" --since "$qrc_since" --sessions "$qroot/no-such-root" >/dev/null 2>&1; printf '%s' "$?")" = 2 ] \
    || qrc_bad="$qrc_bad no-sessions-dir"
  if [ -z "$qrc_bad" ]; then
    ok "codex-rollout-check-finding-no-rollout-is-exit-2-never-a-pass"
  else
    bad "codex-rollout-check-finding-no-rollout-is-exit-2-never-a-pass" \
        "exit 2 expected when there is nothing to read; not produced for:$qrc_bad"
  fi

  # Mutants, on copies under $TMPROOT: one that lets the escalation regex match
  # nothing, one that reads zero rollouts as success, one that stops reading the
  # denial. Each must redden the case aimed at it.
  local qrc_mut_ok=1 qrc_mut_detail="" qrc_m
  for qrc_m in \
    "no-escalation:s/^ESCALATION = re.compile(.*/ESCALATION = re.compile(r\"(?!x)x\")/:escalation" \
    "zero-is-a-pass:s/^        return 2\$/        return 0/:empty" \
    "no-denial:s/^DENIAL = .*/DENIAL = \"\\\\x00never\"/:denial" \
    "roots-ignored:s/^        missing = \\[r for r in .*/        missing = []/:roots" \
    "approval-ignored:s/^        wrong = sorted(.*/        wrong = []/:approval" \
    "approval-unobserved-is-a-pass:/the pin was not observed/{n;s/unobserved = True/unobserved = False/;}:approvalnone" \
    "approval-unread:s/^                        policies.add(.*/                        pass/:approval" \
    "exit2-wins:s/^\\( *\\)unobserved = True\$/\\1return 2/:outrank" \
    "unpinned-skipped:s/^\\( *\\)unpinned += 1\$/\\1pass/:unpinned"; do
    local qrc_name="${qrc_m%%:*}" qrc_rest="${qrc_m#*:}"
    local qrc_prog="${qrc_rest%:*}" qrc_aim="${qrc_rest##*:}"
    local qrc_mp="$qroot/codex-rollout-check-$qrc_name.py"
    sed "$qrc_prog" "$qrc_check" > "$qrc_mp" 2>/dev/null
    if cmp -s "$qrc_mp" "$qrc_check"; then
      qrc_mut_ok=0; qrc_mut_detail="$qrc_mut_detail $qrc_name-changed-nothing"; continue
    fi
    rm -f "$qrc_root"/2026/10/29/*.jsonl
    case "$qrc_aim" in
      escalation) _qrc_rollout m exec "$qrc_msg" "$qrc_esc"; qrc_got="$(_qrc_run "$qrc_mp")"; [ "$qrc_got" = 1 ] && { qrc_mut_ok=0; qrc_mut_detail="$qrc_mut_detail $qrc_name-accepted"; } ;;
      denial)     _qrc_rollout m exec "$qrc_msg" "$qrc_deny"; qrc_got="$(_qrc_run "$qrc_mp")"; [ "$qrc_got" = 1 ] && { qrc_mut_ok=0; qrc_mut_detail="$qrc_mut_detail $qrc_name-accepted"; } ;;
      empty)      qrc_got="$(_qrc_run "$qrc_mp")"; [ "$qrc_got" = 2 ] && { qrc_mut_ok=0; qrc_mut_detail="$qrc_mut_detail $qrc_name-accepted"; } ;;
      approval)   _qrc_rollout m exec "$qrc_msg" "$qrc_ap_req" "$qrc_ok"; qrc_got="$(_qrc_run "$qrc_mp" --expect-approval never)"; [ "$qrc_got" = 1 ] && { qrc_mut_ok=0; qrc_mut_detail="$qrc_mut_detail $qrc_name-accepted"; } ;;
      approvalnone) _qrc_rollout m exec "$qrc_msg" "$qrc_ap_none" "$qrc_ok"; qrc_got="$(_qrc_run "$qrc_mp" --expect-approval never)"; [ "$qrc_got" = 2 ] && { qrc_mut_ok=0; qrc_mut_detail="$qrc_mut_detail $qrc_name-accepted"; } ;;
      outrank)    _qrc_rollout m exec "$qrc_msg" "$qrc_deny" "$qrc_ap_none"; qrc_got="$(_qrc_run "$qrc_mp" --expect-approval never)"; [ "$qrc_got" = 1 ] && { qrc_mut_ok=0; qrc_mut_detail="$qrc_mut_detail $qrc_name-accepted"; } ;;
      unpinned)   _qrc_rollout m exec "$qrc_msg" "$qrc_ap_never" "$qrc_ap_none" "$qrc_ok"; qrc_got="$(_qrc_run "$qrc_mp" --expect-approval never)"; [ "$qrc_got" = 1 ] && { qrc_mut_ok=0; qrc_mut_detail="$qrc_mut_detail $qrc_name-accepted"; } ;;
      roots)      _qrc_rollout m exec "$qrc_msg" "$qrc_tc_common" "$qrc_ok"; qrc_got="$(_qrc_run "$qrc_mp" --expect-root "$qroot/c" --expect-root "$qroot/c/worktrees/t")"; [ "$qrc_got" = 1 ] && { qrc_mut_ok=0; qrc_mut_detail="$qrc_mut_detail $qrc_name-accepted"; } ;;
    esac
  done
  if [ "$qrc_mut_ok" = 1 ]; then
    ok "codex-rollout-check-mutation-is-caught (an escalation regex that matches nothing, zero rollouts read as success, a denial that is never read, expected roots that are ignored, an approval policy that is ignored, never read, or whose absence reads as success, exit 2 outranking a finding, and a turn with no policy skipped each turn a case red)"
  else
    bad "codex-rollout-check-mutation-is-caught" "a mutant of the rollout check was accepted:$qrc_mut_detail"
  fi

  # ---- a pin with no source is SUBSTRATE, and it is exit 3, not 127 -------
  #
  # codex-run.sh is `set -uo pipefail`. A bare "$FORGE_PIN_CODEX_MODEL" against
  # a pin file that lost the key exits **127** — a code absent from that
  # script's own documented table, and worse than the exit 1 ADR-0010
  # deliberately leaves unused so a caller under `set -e` cannot misread a park
  # as a crash. Without the startup validation this design would have replaced
  # one silent-inheritance path with a new one, so the exit code is asserted to
  # be 3 EXACTLY: "non-zero" is also true of 127, which is the defect itself.
  #
  # A copy in its own directory, because codex-run.sh resolves the pin file
  # relative to itself — $qmutdir has one symlinked in, which is what keeps the
  # mutants above from failing for this reason instead of their own.
  local qnp="$qroot/no-pins" qnprt="$qroot/runtime-nopin"
  local qnp_absent qnp_absent_rc qnp_short qnp_short_rc qnp_real
  mkdir -p "$qnp"
  # codex-run.sh names the pin file as "$SCRIPT_DIR/model-pins.sh", and
  # SCRIPT_DIR is `pwd -P` — on macOS that turns /var into /private/var, so the
  # expected path has to be resolved the same way or this grep never matches.
  qnp_real="$(cd "$qnp" && pwd -P)"
  cp "$runner" "$qnp/codex-run.sh" && chmod +x "$qnp/codex-run.sh"
  ln -sf "$REPO_ROOT/scripts/quota-window.py" "$qnp/quota-window.py"
  ln -sf "$REPO_ROOT/scripts/codex-progress.py" "$qnp/codex-progress.py"
  rm -f "$qnp/model-pins.sh"
  rm -rf "$qnprt"; mkdir -p "$qnprt"; printf 'contract\n' > "$qnprt/contract.md"
  qnp_absent="$(_qrun 30 env PATH="$qbin:$PATH" CODEX_HOME="$qroot/codexhome" \
                  FORGE_LANE_RUNTIME="$qnprt" FORGE_LANE_PARK_ROOT="$qpark" \
                  FORGE_CODEX_BIN="$qbin/pin-echo" \
                  "$qnp/codex-run.sh" "$qws" qrun-nopin qtask-nopin 2>&1)"
  qnp_absent_rc=$?
  # The 127 case exactly: a pin file that sources cleanly and lost one key.
  printf 'FORGE_PIN_CODEX_MODEL="fixture-model"\n' > "$qnp/model-pins.sh"
  qnp_short="$(_qrun 30 env PATH="$qbin:$PATH" CODEX_HOME="$qroot/codexhome" \
                 FORGE_LANE_RUNTIME="$qnprt" FORGE_LANE_PARK_ROOT="$qpark" \
                 FORGE_CODEX_BIN="$qbin/pin-echo" \
                 "$qnp/codex-run.sh" "$qws" qrun-nopin2 qtask-nopin2 2>&1)"
  qnp_short_rc=$?
  rm -f "$qnp/model-pins.sh"
  if [ "$qnp_absent_rc" = 3 ] \
     && printf '%s' "$qnp_absent" | grep -Fq "$qnp_real/model-pins.sh" \
     && [ "$qnp_short_rc" = 3 ] \
     && printf '%s' "$qnp_short" | grep -Fq 'FORGE_PIN_CODEX_EFFORT'; then
    ok "a-pin-with-no-source-is-substrate-not-a-crash"
  else
    bad "a-pin-with-no-source-is-substrate-not-a-crash" \
        "an absent pin file and one missing a key must EACH exit 3 naming what is absent, never 127 (got $qnp_absent_rc / $qnp_short_rc: ${qnp_absent:-none} / ${qnp_short:-none})"
  fi

  # The other half: a runner the lane does not call is dead code. §4 must reach
  # it through ~/.forge/repo, the only path that resolves from a worktree.
  # Since FL2 the caller is scripts/lane.sh, beside the runner; its park count (the runner's
  # PARK-COMMENT lines, reported in the hand-off summary since P24 — a fenced terminal cannot
  # post them to the card) is executed by lane/lane-sh-runs-the-protocol.
  if grep -Fq '"$HERE/codex-run.sh" "$WS" "$RUN_ID" "$TASK"' scripts/lane.sh \
     && grep -Fq 'PARK-COMMENT' scripts/lane.sh \
     && ! grep -Eq 'codex exec' scripts/lane.sh \
     && ! grep -Eq '^UV_CACHE_DIR=.*codex exec' "$lane"; then
    ok "lane-invokes-the-runner"
  else
    bad "lane-invokes-the-runner" \
        "lane.sh must call codex-run.sh beside itself, count its PARK-COMMENT lines, and never invoke codex exec inline"
  fi
}
wants quota     && run_quota_group

# ===========================================================================
# digest/ — the daily digest and the one decision-first format (epic GW1, GW2).
#
# Under `hermes cron … --no-agent` the digest's stdout IS the operator's
# message and nothing rephrases it, so this group diffs the whole message
# against a checked-in expectation. It runs offline: boards are checked-in SQL
# under an isolated HERMES_HOME, TZ is pinned to UTC so "the day" is the same
# instant on every host, and the spend line comes from the real metrics.sh.
# ===========================================================================

# Every class the contract's blocked_reason_pattern registers must have a
# decision entry, and every entry must be a registered class. $1=formatter file.
# Blind is not a pass: a pattern that yields no classes, or a formatter that
# yields no entries, fails.
decision_classes_diagnostic() {
  local fmt="$1" registered answered missing extra
  registered="$(jq -r '.blocked_reason_pattern' rubrics/run-metadata-contract.json 2>/dev/null \
    | sed -n 's/^\^(\([a-z|-]*\)):.*/\1/p' | tr '|' '\n' | sort)"
  [ -n "$registered" ] || { echo "no classes could be read out of blocked_reason_pattern — the check went blind (F65)"; return 1; }
  answered="$(bash -c '. "$1" && decision_classes' _ "$fmt" 2>/dev/null | sort)"
  [ -n "$answered" ] || { echo "$fmt answers no class at all — the check went blind (F65)"; return 1; }
  missing="$(comm -23 <(printf '%s\n' "$registered") <(printf '%s\n' "$answered") | tr '\n' ' ')"
  extra="$(comm -13 <(printf '%s\n' "$registered") <(printf '%s\n' "$answered") | tr '\n' ' ')"
  [ -z "$missing$extra" ] || {
    echo "registered with no decision: ${missing:-none}; decisions for no registered class: ${extra:-none}"; return 1; }
  # And each entry really answers four lines through the function the digest calls.
  local c n
  for c in $answered; do
    n="$(bash -c '. "$1" && class_decision "$2"' _ "$fmt" "$c" 2>/dev/null | grep -c .)"
    [ "$n" = 4 ] || { echo "class_decision $c yields $n non-empty lines, want 4 (means, decision, risk, reply)"; return 1; }
  done
  return 0
}

run_digest_group() {
  group digest
  for tool in sqlite3 jq; do
    command -v "$tool" >/dev/null 2>&1 || { skip "fixture-message-exact" "$tool not on PATH"; return; }
  done
  local ds=scripts/digest.sh root="$TMPROOT/digest" out rc detail
  local kb="$root/hermes/kanban/boards"
  mkdir -p "$kb/digest-fixture" "$kb/metrics-fl3" "$kb/quiet" "$kb/_archived/old-1"
  sqlite3 "$kb/digest-fixture/kanban.db" < scripts/fixtures/digest-board.sql >/dev/null 2>&1
  sqlite3 "$kb/metrics-fl3/kanban.db" < scripts/fixtures/metrics-board-fl3.sql >/dev/null 2>&1
  # An archived board full of waiting cards: Hermes moved it out of the way,
  # so it must not speak.
  sqlite3 "$kb/_archived/old-1/kanban.db" < scripts/fixtures/digest-board.sql >/dev/null 2>&1
  # A board whose only card finished long ago: nothing to say, so nothing said.
  sqlite3 "$kb/quiet/kanban.db" < scripts/fixtures/digest-board.sql >/dev/null 2>&1
  sqlite3 "$kb/quiet/kanban.db" "DELETE FROM tasks WHERE id <> 't_d7';" >/dev/null 2>&1
  _dg() { TZ=UTC HERMES_HOME="$root/hermes" "$REPO_ROOT/$ds" "$@"; }

  local before after
  before="$(for b in digest-fixture metrics-fl3 quiet; do db_source_fingerprint "$kb/$b/kanban.db"; done)"
  out="$(_dg --day 2026-07-28 2>"$root/err")"; rc=$?
  after="$(for b in digest-fixture metrics-fl3 quiet; do db_source_fingerprint "$kb/$b/kanban.db"; done)"
  printf '%s\n' "$out" > "$root/out.txt"
  if [ "$rc" = 0 ] && diff -u scripts/fixtures/digest-expected.txt "$root/out.txt" > "$root/diff" 2>&1; then
    ok "fixture-message-exact ($(grep -c '^Decision needed: ' "$root/out.txt") decisions waiting, every line)"
  else
    bad "fixture-message-exact" "rc=$rc $(head -14 "$root/diff" | tr '\n' ' ') $(head -3 "$root/err" | tr '\n' ' ')"
  fi
  # The decision and risk labels stay on their own visually separated lines;
  # the fixture has five decisions, so a blind test cannot pass.
  if awk '
    /^Decision needed: / { decisions++; if (previous != "") bad=1 }
    /^Risk: / { risks++; if (previous != "") bad=1 }
    { previous=$0 }
    END { exit (bad || decisions != 5 || risks != 5) }
  ' "$root/out.txt"; then
    ok "decision-risk-spacing"
  else
    bad "decision-risk-spacing" "five decision and risk lines must follow blank lines"
  fi

  # A busy board can have no landed or waiting work; zero remains visible.
  mkdir -p "$kb/empty-sections"
  sqlite3 "$kb/empty-sections/kanban.db" < scripts/fixtures/digest-board.sql >/dev/null 2>&1
  sqlite3 "$kb/empty-sections/kanban.db" "DELETE FROM tasks WHERE id <> 't_d4';" >/dev/null 2>&1
  local empty_output
  empty_output="$(_dg --board empty-sections --day 2026-07-28 2>/dev/null)"; rc=$?
  { [ "$rc" = 0 ] && printf '%s\n' "$empty_output" | grep -qxF 'Landed (0): nothing' \
    && printf '%s\n' "$empty_output" | grep -qxF 'Waiting on you (0): nothing' \
    && printf '%s\n' "$empty_output" | grep -qxF 'In flight: 1 running' \
    && [ "$(printf '%s\n' "$empty_output" | grep -cFx '────────────')" = 4 ]; } \
    && ok "empty-sections-readable" \
    || bad "empty-sections-readable" "zero-count headings must remain explicit and underlined — landed, waiting, what it means, what to do (rc=$rc)"
  rm -rf "$kb/empty-sections"

  # Heading-shaped lines in card text are data, not digest section headings.
  mkdir -p "$kb/verbatim"
  sqlite3 "$kb/verbatim/kanban.db" < scripts/fixtures/digest-board.sql >/dev/null 2>&1
  local verbatim_reason verbatim_title payload_sql verbatim_out
  verbatim_reason="$(cat <<'REASON'
merge-pending: a heading-shaped hold
What it means: keep unusual content
SENTINEL_START
Landed (1)
Waiting on you (0): nothing
In flight: nothing
Spend: no metered driver runs on the day
Decision needed: inspect the card
Risk: preserve this line
SENTINEL_END
Decision needed: the real decision
Risk: the real risk
Reply: inspect it
REASON
)"
  verbatim_title="$(printf 'A title\nLanded (1)\nRisk: title line')"
  payload_sql="$(jq -cn --arg r "$verbatim_reason" '{reason:$r,kind:"needs_input"}' | sed "s/'/''/g")"
  sqlite3 "$kb/verbatim/kanban.db" "DELETE FROM tasks WHERE id <> 't_d1'; DELETE FROM task_events;
    UPDATE tasks SET title = 'A title
Landed (1)
Risk: title line' WHERE id = 't_d1';
    INSERT INTO task_events (task_id,kind,payload,created_at) VALUES ('t_d1','blocked','$payload_sql',1785206000);" >/dev/null 2>&1
  verbatim_out="$(_dg --board verbatim --day 2026-07-28 2>/dev/null)"; rc=$?
  { [ "$rc" = 0 ] && [[ "$verbatim_out" = *"$verbatim_reason"* ]] \
    && [[ "$verbatim_out" = *"$verbatim_title"* ]]; } \
    && ok "hold-and-title-verbatim" \
    || bad "hold-and-title-verbatim" "heading-like card content must not be restyled (rc=$rc)"
  rm -rf "$kb/verbatim"

  [ -n "$before" ] && [ "$before" = "$after" ] \
    && ok "is-read-only" \
    || bad "is-read-only" "a board or one of its sidecars changed while the digest read it"

  out="$(_dg --board quiet --day 2026-07-28 2>/dev/null)"; rc=$?
  { [ "$rc" = 0 ] && [ -z "$out" ]; } \
    && ok "silent-when-nothing-happened" \
    || bad "silent-when-nothing-happened" "a quiet board must print nothing and exit 0 (rc=$rc): $(printf '%s' "$out" | head -2 | tr '\n' ' ')"

  mkdir -p "$kb/broken"; printf 'not sqlite\n' > "$kb/broken/kanban.db"
  out="$(_dg --board broken --board quiet --day 2026-07-28 2>/dev/null)"; rc=$?
  { [ "$rc" = 3 ] && printf '%s' "$out" | grep -q '^== broken ==' \
    && printf '%s' "$out" | grep -q 'UNREADABLE'; } \
    && ok "an-unreadable-board-is-named" \
    || bad "an-unreadable-board-is-named" "an unreadable board must be named on stdout with exit 3, never read as quiet (rc=$rc): $(printf '%s' "$out" | head -3 | tr '\n' ' ')"
  rm -rf "$kb/broken"

  # Epic MS1: a held milestone gate is silent while any chunk it closes is
  # open, and speaks — decision-first, as bootstrapped — once they are all done.
  mkdir -p "$kb/gates"
  sqlite3 "$kb/gates/kanban.db" < scripts/fixtures/digest-board.sql >/dev/null 2>&1
  local gate_reason
  gate_reason="$(bash -c '. scripts/decision-message.sh && decision_message milestone-gate "GATE-M1 holds milestone M1" "means" "decide" "risk" "reply"')"
  sqlite3 "$kb/gates/kanban.db" "DELETE FROM tasks; DELETE FROM task_events;
    INSERT INTO tasks (id, title, assignee, status, created_at) VALUES
      ('t_g1', 'CHUNK-1: last chunk of M1', 'forge-verifier', 'review', 1785200000),
      ('t_g2', 'GATE-M1: Milestone 1', NULL, 'blocked', 1785200000);
    INSERT INTO task_links (parent_id, child_id) VALUES ('t_g1', 't_g2');
    INSERT INTO task_events (task_id, kind, payload, created_at)
      VALUES ('t_g2', 'blocked', json_object('reason', '$(printf '%s' "$gate_reason" | sed "s/'/''/g")'), 1785200000);" >/dev/null 2>&1
  local g_open g_done
  g_open="$(_dg --board gates --day 2026-07-28 2>/dev/null)"
  sqlite3 "$kb/gates/kanban.db" "UPDATE tasks SET status='done', completed_at=1785200000 WHERE id='t_g1';" >/dev/null 2>&1
  g_done="$(_dg --board gates --day 2026-07-28 2>/dev/null)"
  if ! printf '%s' "$g_open" | grep -q 't_g2' \
     && printf '%s' "$g_done" | grep -q '^— t_g2 · GATE-M1' \
     && printf '%s' "$g_done" | grep -q '^Decision needed: decide'; then
    ok "a-gate-speaks-only-when-its-milestone-is-done"
  else
    bad "a-gate-speaks-only-when-its-milestone-is-done" \
        "a held gate must be absent while its chunk is open and shown decision-first once it is done; open: $(printf '%s' "$g_open" | grep -c t_g2) mention(s), done: $(printf '%s' "$g_done" | head -8 | tr '\n' ' ')"
  fi
  rm -rf "$kb/gates"

  # Epic P13: an interactive chunk is held from the bootstrap on, like a gate,
  # and has nothing to ask while a parent is open. CHUNK-5's shape — two
  # parents, one done — so "all parents done" is told apart from "any". The
  # controls stay listed throughout. Three share the open parent: a held chunk
  # blocked again for another reason, because the LAST reason counts and the
  # rule is not "every blocked card with an open parent"; a card blocked with
  # no recorded reason, which a NULL comparison must not drop; and a held chunk
  # that went to triage, which no script can complete (P8), so it always
  # speaks. The fourth is a held root, which has nothing to wait for.
  mkdir -p "$kb/humans"
  sqlite3 "$kb/humans/kanban.db" < scripts/fixtures/digest-board.sql >/dev/null 2>&1
  local hold
  hold="$(bash -c '. scripts/decision-message.sh && printf %s "$INTERACTIVE_HOLD_REASON"' 2>/dev/null | sed "s/'/''/g")"
  sqlite3 "$kb/humans/kanban.db" "DELETE FROM tasks; DELETE FROM task_events; DELETE FROM task_runs;
    INSERT INTO tasks (id, title, assignee, status, created_at) VALUES
      ('t_h1', 'CHUNK-2: first parent',             'forge-verifier', 'done',    1785200000),
      ('t_h2', 'CHUNK-3: second parent',            'forge-verifier', 'review',  1785200000),
      ('t_h3', 'CHUNK-5: a human chunk',            NULL,             'blocked', 1785200000),
      ('t_h4', 'CHUNK-6: held, then blocked again', NULL,             'blocked', 1785200000),
      ('t_h5', 'CHUNK-7: blocked with no reason',   NULL,             'blocked', 1785200000),
      ('t_h6', 'CHUNK-1: a held root',              NULL,             'blocked', 1785200000),
      ('t_h7', 'CHUNK-8: held, now in triage',      NULL,             'triage',  1785200000);
    INSERT INTO task_links (parent_id, child_id) VALUES
      ('t_h1', 't_h3'), ('t_h2', 't_h3'), ('t_h2', 't_h4'), ('t_h2', 't_h5'), ('t_h2', 't_h7');
    INSERT INTO task_events (task_id, kind, payload, created_at) VALUES
      ('t_h3', 'blocked', json_object('reason', '$hold', 'kind', 'needs_input'), 1785200000),
      ('t_h4', 'blocked', json_object('reason', '$hold', 'kind', 'needs_input'), 1785200000),
      ('t_h4', 'blocked', json_object('reason', 'env: the workspace is gone', 'kind', 'needs_input'), 1785200100),
      ('t_h6', 'blocked', json_object('reason', '$hold', 'kind', 'needs_input'), 1785200000),
      ('t_h7', 'blocked', json_object('reason', '$hold', 'kind', 'needs_input'), 1785200000);" >/dev/null 2>&1
  local h_open h_done c controls_listed=1
  h_open="$(_dg --board humans --day 2026-07-28 2>/dev/null)"
  sqlite3 "$kb/humans/kanban.db" "UPDATE tasks SET status='archived' WHERE id='t_h2';" >/dev/null 2>&1
  h_done="$(_dg --board humans --day 2026-07-28 2>/dev/null)"
  for c in t_h4 t_h5 t_h6 t_h7; do
    printf '%s' "$h_open" | grep -q "^— $c · " && printf '%s' "$h_done" | grep -q "^— $c · " \
      || controls_listed=0
  done
  if [ -n "$hold" ] && [ "$controls_listed" = 1 ] \
     && printf '%s' "$h_open" | grep -q '^Waiting on you (4)$' \
     && ! printf '%s' "$h_open" | grep -q 't_h3' \
     && printf '%s' "$h_done" | grep -q '^Waiting on you (5)$' \
     && printf '%s' "$h_done" | grep -q '^— t_h3 · CHUNK-5'; then
    ok "an-interactive-chunk-speaks-only-when-its-parents-are-done"
  else
    bad "an-interactive-chunk-speaks-only-when-its-parents-are-done" \
        "a held interactive chunk must be absent while either parent is open and listed once both are done or archived, with all four controls listed throughout; hold '$hold', open: $(printf '%s' "$h_open" | grep -E '^(Waiting|— )' | tr '\n' ' '), done: $(printf '%s' "$h_done" | grep -E '^(Waiting|— )' | tr '\n' ' ')"
  fi
  # Epic P16: once it speaks, the hold must say what it is and what to do. It
  # rendered as `other: … Risk: unknown` until S6c — the one held card in run A
  # that is the operator's own work, described as a mystery.
  local h_msg
  h_msg="$(printf '%s\n' "$h_done" | awk '/^— t_h3 /{f=1; next} f && /^— /{exit} f')"
  if printf '%s' "$h_msg" | grep -q '^interactive: ' \
     && printf '%s' "$h_msg" | grep -q '^Decision needed: ' \
     && printf '%s' "$h_msg" | grep -q '^Reply: .*/start-chunk' \
     && ! printf '%s' "$h_msg" | grep -q '^other: ' \
     && ! printf '%s' "$h_msg" | grep -qi 'risk: unknown'; then
    ok "an-interactive-hold-is-decision-first"
  else
    bad "an-interactive-hold-is-decision-first" \
        "a listed interactive chunk must render as what it is, the decision and the reply — never as other; got: $(printf '%s' "$h_msg" | tr '\n' '|' | head -c 400)"
  fi
  rm -rf "$kb/humans"

  # Epic P21: a human chunk the verifier (or the operator, through bounce.sh)
  # sent back lands `ready` on the non-spawnable sentinel. Nothing will pick it
  # up but the operator, so it is waiting on them — and it is not "in flight",
  # which is what a ready card means everywhere else. The control is a ready
  # lane card, which stays in flight and is not waiting on anyone.
  mkdir -p "$kb/returned"
  sqlite3 "$kb/returned/kanban.db" < scripts/fixtures/digest-board.sql >/dev/null 2>&1
  sqlite3 "$kb/returned/kanban.db" "DELETE FROM tasks; DELETE FROM task_events; DELETE FROM task_runs;
    INSERT INTO tasks (id, title, assignee, status, created_at) VALUES
      ('t_r1', 'CHUNK-5: sent back',   'forge-operator-handoff', 'ready', 1785200000),
      ('t_r2', 'CHUNK-4: a lane chunk', 'forge-codex-lane',       'ready', 1785200000);
    INSERT INTO task_events (task_id, kind, payload, created_at) VALUES
      ('t_r1', 'changes_requested', json_object('reason', 'https://example.invalid/p/pull/9' || char(10) || char(10) || 'merged tree: 5 tests fail on the union', 'implementer', 'forge-operator-handoff', 'reviewer', 'forge-verifier', 'status', 'ready'), 1785200000);" >/dev/null 2>&1
  local r_out r_msg
  r_out="$(_dg --board returned --day 2026-07-28 2>/dev/null)"
  r_msg="$(printf '%s\n' "$r_out" | awk '/^— t_r1 /{f=1; next} f && /^— /{exit} f')"
  if printf '%s' "$r_out" | grep -q '^In flight: 1 ready$' \
     && printf '%s' "$r_out" | grep -q '^Waiting on you (1)$' \
     && printf '%s' "$r_out" | grep -q '^— t_r1 · CHUNK-5' \
     && ! printf '%s' "$r_out" | grep -q '^— t_r2 ' \
     && printf '%s' "$r_msg" | grep -q '^returned: ' \
     && printf '%s' "$r_msg" | grep -q '^Decision needed: fix it' \
     && printf '%s' "$r_msg" | grep -q '^Reply: .*show t_r1'; then
    ok "a-returned-human-chunk-waits-on-you"
  else
    bad "a-returned-human-chunk-waits-on-you" \
        "a human chunk sent back (ready, on forge-operator-handoff) must be waiting on the operator, decision-first and out of flight, while a ready lane card stays in flight; got: $(printf '%s' "$r_out" | grep -vE '^(Landed|Spend|$)' | tr '\n' '|' | head -c 500)"
  fi
  rm -rf "$kb/returned"

  # Owner feedback, 5 Nov 2026: "What it means" should be longer and clearer, and
  # the digest should say what to do. Both sections close each board, computed
  # from its rows. Fixtures pin their rows' epochs and the --day they are read on
  # (TZ=UTC), so no check depends on today's date.
  _section() { awk -v h="$1" '$0 == h {getline; f=1; next} f && /^$/ {f=0; next} f'; }
  _boardfix() {  # $1=board; the digest fixture's schema, then the caller's rows
    mkdir -p "$kb/$1"; sqlite3 "$kb/$1/kanban.db" < scripts/fixtures/digest-board.sql >/dev/null 2>&1
    sqlite3 "$kb/$1/kanban.db" "DELETE FROM tasks; DELETE FROM task_events; DELETE FROM task_runs; DELETE FROM task_links;" >/dev/null 2>&1
  }
  local wd_means wd_do wd_rest

  # The fixture message (two boards) is where "What it means" is read in full.
  wd_means="$(_section 'Where this board stands' < "$root/out.txt")"
  if [ "$(printf '%s\n' "$wd_means" | grep -c .)" = 13 ] \
     && [ "$(printf '%s\n' "$wd_means" | grep -cxF 'Overall: work continues on what is in flight; no waiting card is behind the cards that need you.')" = 2 ] \
     && printf '%s\n' "$wd_means" | grep -qxF 'Progress: 1 card landed on 2026-07-28; now 1 running.' \
     && printf '%s\n' "$wd_means" | grep -qxF 'Waiting on parents: 1 card; none needs you yet, each starts on its own once its parents finish.' \
     && printf '%s\n' "$wd_means" | grep -qxF 'Waiting on you: 3 cards' \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 1 verified chunk, waiting for your merge; its children stay held until it is merged.' \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 1 blocked by env: codex usage limit — waited past FORGE_QUOTA_MAX_WAIT (park record: .forge/park-1.json); it holds, with its children, until you fix the cause and unblock.' \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 1 stopped for an unrecognised reason; read it with `hermes kanban --board digest-fixture show t_d3`.' \
     && printf '%s\n' "$wd_means" | grep -qxF 'Waiting on you: 2 cards' \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 1 in triage; no script can complete a triage card, so it stays until you decide.' \
     && printf '%s\n' "$wd_means" | grep -qxF 'Progress: 5 cards landed on 2026-07-28; now 1 in review.' \
     && ! printf '%s\n' "$wd_means" | grep -qE 'speaks in this digest|outside the known classes'; then
    ok "board-stands-explains-state-and-consequence (overall, progress, parents and one line per waiting kind with its consequence, on both fixture boards)"
  else
    bad "board-stands-explains-state-and-consequence" "got: $(printf '%s' "$wd_means" | tr '\n' '|' | head -c 900)"
  fi

  # A held gate whose every chunk is done: the exact decision step.
  _boardfix todogate
  local tg_reason
  tg_reason="$(bash -c '. scripts/decision-message.sh && decision_message milestone-gate "GATE-M1 holds milestone M1'"'"'s successors until you complete it" "every chunk that depends on this gate waits" "once every chunk of M1 is merged, run its probe (tests/probes/gate_m1.json) with \`~/.forge/repo/scripts/probe-run.sh '"'"'/p/product'"'"' GATE-M1\` and decide whether M1 is done — exit 0 passes, 1 is a finding, 2 is no verdict; until then there is nothing to decide" "completing it early starts the next milestone on work nobody has probed" "\`hermes kanban --board todogate complete <id> --result \"<the runner'"'"'s last line>\"\`"')"
  sqlite3 "$kb/todogate/kanban.db" "
    INSERT INTO tasks (id, title, assignee, status, created_at, completed_at) VALUES
      ('t_g1', 'CHUNK-9: the last chunk of M1', 'forge-verifier', 'done',    1785200000, 1785100000),
      ('t_g2', 'GATE-M1: Milestone 1',          NULL,             'blocked', 1785200000, NULL),
      ('t_g3', 'CHUNK-10: after the gate',      'forge-codex-lane', 'todo',  1785200000, NULL),
      ('t_g4', 'CHUNK-11: after a live chunk',  'forge-codex-lane', 'todo',  1785200000, NULL),
      ('t_g5', 'CHUNK-12: a live chunk',         'forge-codex-lane', 'running', 1785200000, NULL);
    INSERT INTO task_links (parent_id, child_id) VALUES ('t_g1', 't_g2'), ('t_g2', 't_g3'), ('t_g5', 't_g4');
    INSERT INTO task_events (task_id, kind, payload, created_at)
      VALUES ('t_g2', 'blocked', json_object('reason', '$(printf '%s' "$tg_reason" | sed "s/'/''/g")'), 1785200000);" >/dev/null 2>&1
  out="$(_dg --board todogate --day 2026-07-28 2>/dev/null)"; rc=$?
  wd_do="$(printf '%s\n' "$out" | _section 'What to do')"
  wd_rest="$(printf '%s\n' "$out" | awk '/^Where this board stands$/{exit} {print}')"
  if [ "$rc" = 0 ] \
     && printf '%s\n' "$wd_do" | grep -qxF "   \`~/.forge/repo/scripts/probe-run.sh '/p/product' GATE-M1\`" \
     && printf '%s\n' "$wd_do" | grep -qxF '   Exit 0: `hermes kanban --board todogate complete t_g2 --result "<the runner'"'"'s last line>"`' \
     && printf '%s\n' "$wd_do" | grep -qxF '   Completing it releases the next milestone; do it only when your run plan says to.' \
     && printf '%s\n' "$wd_do" | grep -qxF '   Exit 1 (a finding) or 2 (no verdict): do not complete it.' \
     && printf '%s\n' "$wd_do" | head -1 | grep -qxF '1. GATE-M1 (t_g2): no chunk it closes is still open, so probe the milestone:' \
     && printf '%s\n' "$out" | _section 'Where this board stands' | grep -qxF '  · 1 milestone gate ready for your sign-off; the chunks behind it stay held until you complete it.' \
     && printf '%s\n' "$out" | _section 'Where this board stands' | grep -qxF 'Overall: work continues on what is in flight, but 1 waiting card cannot start until you act.' \
     && printf '%s\n' "$out" | _section 'Where this board stands' | grep -qxF 'Waiting on parents: 2 cards (1 behind the cards waiting on you, so they start only after you act; the rest start on their own once their parents finish).' \
     && ! printf '%s\n' "$wd_do" | grep -qxFf <(printf '%s\n' "$wd_rest" | grep .); then
    ok "what-to-do-names-the-gate-step (probe, complete with --board, the exit rule; no line repeated from the card above)"
  else
    bad "what-to-do-names-the-gate-step" "rc=$rc; what to do was: $(printf '%s' "$wd_do" | tr '\n' '|' | head -c 700)"
  fi
  local all_do="$wd_do"

  # Nothing waits. (a) only landed work; (b) a run moving on its own with a gate
  # held on its open chunk; (c) nothing running while cards wait on parents.
  _boardfix nothing
  sqlite3 "$kb/nothing/kanban.db" "INSERT INTO tasks (id, title, assignee, status, created_at, completed_at)
    VALUES ('t_n1', 'CHUNK-1: done on the day', 'forge-verifier', 'done', 1785200000, 1785210000);" >/dev/null 2>&1
  out="$(_dg --board nothing --day 2026-07-28 2>/dev/null)"; rc=$?
  local n_a_do n_a_means
  n_a_do="$(printf '%s\n' "$out" | _section 'What to do')"; n_a_means="$(printf '%s\n' "$out" | _section 'Where this board stands')"
  all_do="$all_do
$n_a_do"
  local n_a_ok=0
  { [ "$rc" = 0 ] && [ "$n_a_do" = 'Nothing needs you today.' ] \
    && printf '%s\n' "$n_a_means" | grep -qxF 'Progress: 1 card landed on 2026-07-28; nothing is running now.' \
    && printf '%s\n' "$n_a_means" | grep -qxF 'Waiting on you: nothing.'; } && n_a_ok=1

  _boardfix moving
  sqlite3 "$kb/moving/kanban.db" "
    INSERT INTO tasks (id, title, assignee, status, created_at) VALUES
      ('t_m1', 'CHUNK-1: running',      'forge-codex-lane', 'running', 1785200000),
      ('t_m2', 'CHUNK-2: next',         'forge-codex-lane', 'todo',    1785200000),
      ('t_m3', 'GATE-M1: Milestone 1',  NULL,               'blocked', 1785200000);
    INSERT INTO task_links (parent_id, child_id) VALUES ('t_m1', 't_m2'), ('t_m1', 't_m3');
    INSERT INTO task_events (task_id, kind, payload, created_at)
      VALUES ('t_m3', 'blocked', json_object('reason', 'milestone-gate: held'), 1785200000);" >/dev/null 2>&1
  out="$(_dg --board moving --day 2026-07-28 2>/dev/null)"; rc=$?
  local n_b_do n_b_means
  n_b_do="$(printf '%s\n' "$out" | _section 'What to do')"; n_b_means="$(printf '%s\n' "$out" | _section 'Where this board stands')"
  all_do="$all_do
$n_b_do"
  local n_b_ok=0
  { [ "$rc" = 0 ] \
    && [ "$n_b_do" = 'Nothing needs you today. The run is moving on its own; the next digest says if that changes.' ] \
    && printf '%s\n' "$n_b_means" | grep -qxF 'Progress: nothing landed on 2026-07-28; now 1 running.' \
    && printf '%s\n' "$n_b_means" | grep -qxF 'Waiting on parents: 2 cards; none needs you yet, each starts on its own once its parents finish. Held gates and human chunks appear under Waiting on you once their parents finish.' \
    && printf '%s\n' "$n_b_means" | grep -qxF 'Waiting on you: nothing.'; } && n_b_ok=1

  _boardfix stalled
  sqlite3 "$kb/stalled/kanban.db" "
    INSERT INTO tasks (id, title, assignee, status, created_at) VALUES
      ('t_s1', 'CHUNK-2: waits', 'forge-codex-lane', 'todo', 1785200000);" >/dev/null 2>&1
  out="$(_dg --board stalled --day 2026-07-28 2>/dev/null)"; rc=$?
  local n_c_do; n_c_do="$(printf '%s\n' "$out" | _section 'What to do')"
  all_do="$all_do
$n_c_do"
  local n_c_ok=0
  { [ "$rc" = 0 ] && [ "$n_c_do" = 'Nothing needs you today. Nothing is running either, though, and 1 card waits on parents: if tomorrow'"'"'s digest says the same, look at the board with `hermes kanban --board stalled list`.' ]; } && n_c_ok=1
  if [ "$n_a_ok$n_b_ok$n_c_ok" = 111 ]; then
    ok "what-to-do-when-nothing-waits (landed only; moving on its own with a held gate counted as waiting on parents; stalled behind a parent)"
  else
    bad "what-to-do-when-nothing-waits" "landed-only=$n_a_ok moving=$n_b_ok stalled=$n_c_ok; got: [$n_a_do] [$n_b_do] [$n_c_do]"
  fi

  # A blocked card and a triage card.
  _boardfix blocked
  sqlite3 "$kb/blocked/kanban.db" "
    INSERT INTO tasks (id, title, assignee, status, created_at) VALUES
      ('t_b1', 'CHUNK-8: Exporter', 'forge-codex-lane', 'blocked', 1785200000),
      ('t_b2', 'follow-up: a nit',  NULL,               'triage',  1785200000),
      ('t_b3', 'CHUNK-9: needs the exporter', 'forge-codex-lane', 'todo', 1785200000),
      ('t_b4', 'CHUNK-10: needs CHUNK-9',     'forge-codex-lane', 'todo', 1785200000);
    INSERT INTO task_links (parent_id, child_id) VALUES ('t_b1', 't_b3'), ('t_b3', 't_b4');
    INSERT INTO task_events (task_id, kind, payload, created_at) VALUES
      ('t_b1', 'blocked', json_object('reason', 'env: the workspace is gone'), 1785200000);" >/dev/null 2>&1
  out="$(_dg --board blocked --day 2026-07-28 2>/dev/null)"; rc=$?
  wd_do="$(printf '%s\n' "$out" | _section 'What to do')"; wd_means="$(printf '%s\n' "$out" | _section 'Where this board stands')"
  all_do="$all_do
$wd_do"
  if [ "$rc" = 0 ] \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 1 blocked by env: the workspace is gone; it holds, with its children, until you fix the cause and unblock.' \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 1 in triage; no script can complete a triage card, so it stays until you decide.' \
     && printf '%s\n' "$wd_means" | grep -qxF 'Overall: nothing is running, so the run is stopped until you act.' \
     && printf '%s\n' "$wd_means" | grep -qxF 'Waiting on parents: 2 cards (all behind the cards waiting on you, so they start only after you act).' \
     && printf '%s\n' "$wd_do" | grep -qxF '1. CHUNK-8 (t_b1): blocked by env. Inspect with `hermes kanban --board blocked show t_b1`; once the cause is fixed, `hermes kanban --board blocked unblock t_b1`.' \
     && printf '%s\n' "$wd_do" | grep -qxF '2. follow-up: a nit (t_b2): read it with `hermes kanban --board blocked show t_b2` and decide whether to keep it; no script can complete it.'; then
    ok "what-to-do-names-what-to-inspect (a blocked card: show then unblock; a triage card: show and decide)"
  else
    bad "what-to-do-names-what-to-inspect" "rc=$rc; means: $(printf '%s' "$wd_means" | tr '\n' '|'); to do: $(printf '%s' "$wd_do" | tr '\n' '|' | head -c 600)"
  fi

  # Phone size: nine cards in triage.
  _boardfix many
  local mi
  for mi in 1 2 3 4 5 6 7 8 9; do
    sqlite3 "$kb/many/kanban.db" "INSERT INTO tasks (id, title, assignee, status, created_at)
      VALUES ('t_x$mi', 'follow-up: nit number $mi', NULL, 'triage', 1785200000);" >/dev/null 2>&1
  done
  out="$(_dg --board many --day 2026-07-28 2>/dev/null)"; rc=$?
  wd_do="$(printf '%s\n' "$out" | _section 'What to do')"; wd_means="$(printf '%s\n' "$out" | _section 'Where this board stands')"
  all_do="$all_do
$wd_do"
  local both_len
  both_len="$(printf '%s\n%s\n' "$wd_means" "$wd_do" | wc -m | tr -d ' ')"
  if [ "$rc" = 0 ] && [ "$(printf '%s\n' "$wd_do" | grep -c '^[0-9]\. ')" = 6 ] \
     && printf '%s\n' "$wd_do" | tail -1 | grep -qxF '…and 3 more waiting cards; the cards above have their own Reply lines.' \
     && [ "$both_len" -lt 1800 ] \
     && ! printf '%s\n' "$out" | grep -qi 'to stop or manage this job'; then  # a regression guard, not a live check: the footer is Hermes's cron.wrap_response, which this script can never emit
    ok "what-to-do-stays-phone-sized (nine cards: six steps and a count, $both_len characters for both sections, no job-management footer)"
  else
    bad "what-to-do-stays-phone-sized" "rc=$rc steps=$(printf '%s\n' "$wd_do" | grep -c '^[0-9]\. ') chars=$both_len last: $(printf '%s' "$wd_do" | tail -1)"
  fi

  # The steps the boards above do not reach: an interactive chunk (h_done), a
  # returned human chunk (r_out), and two holds that need their own wording. And
  # on every board checked, nothing in "What to do" repeats a line printed above.
  _dupfree() {
    local t sec rest; t="$(cat)"
    sec="$(printf '%s\n' "$t" | _section 'What to do')"
    rest="$(printf '%s\n' "$t" | awk '$0 == "What to do" {getline; f=1; next} f && /^$/ {f=0; next} !f' | grep .)"
    [ -n "$sec" ] && [ -n "$rest" ] && ! printf '%s\n' "$sec" | grep -qxFf <(printf '%s\n' "$rest")
  }
  _boardfix bounced
  sqlite3 "$kb/bounced/kanban.db" "
    INSERT INTO tasks (id, title, assignee, status, created_at) VALUES
      ('t_k1', 'CHUNK-3: not converging', 'forge-verifier', 'blocked', 1785200000),
      ('t_k2', 'CHUNK-4: bounced blind',  'forge-verifier', 'blocked', 1785200000);
    INSERT INTO task_events (task_id, kind, payload, created_at) VALUES
      ('t_k1', 'blocked', json_object('reason', 'bounce-budget: two bounces did not converge'), 1785200000),
      ('t_k2', 'blocked', json_object('reason', 'judge-bounce: came back with no reason'), 1785200000);" >/dev/null 2>&1
  local k_out k_do h_do r_do dup_ok=1 dup_bad=""
  k_out="$(_dg --board bounced --day 2026-07-28 2>/dev/null)"
  k_do="$(printf '%s\n' "$k_out" | _section 'What to do')"
  h_do="$(printf '%s\n' "$h_done" | _section 'What to do')"
  r_do="$(printf '%s\n' "$r_out" | _section 'What to do')"
  all_do="$all_do
$k_do
$h_do
$r_do"
  for c in "$h_done:humans" "$r_out:returned" "$k_out:bounced" "$(cat "$root/out.txt"):fixture"; do
    printf '%s\n' "${c%:*}" | _dupfree || { dup_ok=0; dup_bad="$dup_bad ${c##*:}"; }
  done
  if printf '%s\n' "$h_do" | grep -qF '(t_h3): implement it with /start-chunk in the product checkout; its children wait for the merge.' \
     && printf '%s\n' "$h_do" | grep -qF '(t_h7): read it with `hermes kanban --board humans show t_h7` and decide' \
     && printf '%s\n' "$h_do" | grep -qF '(t_h5): read the reason with `hermes kanban --board humans show t_h5` and decide.' \
     && printf '%s\n' "$r_do" | grep -qxF '1. CHUNK-5 (t_r1): read the reasons with `hermes kanban --board returned show t_r1`, fix its branch, then /end-chunk.' \
     && printf '%s\n' "$k_do" | grep -qxF '1. CHUNK-3 (t_k1): repair the PR branch yourself or amend the contract, or send it back; see its Reply above.' \
     && printf '%s\n' "$k_do" | grep -qxF '2. CHUNK-4 (t_k2): inspect with `hermes kanban --board bounced show t_k2`, then follow its Reply above.' \
     && [ "$dup_ok" = 1 ]; then
    ok "what-to-do-covers-every-step-and-repeats-nothing (interactive, returned, bounce-budget, judge-bounce; no repeated line on 4 outputs)"
  else
    bad "what-to-do-covers-every-step-and-repeats-nothing" "repeats on:${dup_bad:- none}; humans: $(printf '%s' "$h_do" | tr '\n' '|' | head -c 500); returned: $(printf '%s' "$r_do" | tr '\n' '|'); bounced: $(printf '%s' "$k_do" | tr '\n' '|')"
  fi
  rm -rf "$kb/bounced"

  # Mutants that survived the first review, now pinned.
  # (a) A parent-link cycle among cards behind a waiting card must terminate: the
  # walk down the links subtracts what it has seen. Run under a watchdog that
  # kills the whole process group, so a looping jq cannot outlive the case.
  _with_timeout() {  # $1=seconds, then the command
    perl -e 'use POSIX; setpgid(0,0); my $s = shift; my $pid = fork;
             if (!$pid) { exec @ARGV or exit 127 }
             $SIG{ALRM} = sub { kill "KILL", -$$; exit 142 }; alarm $s;
             waitpid $pid, 0; exit($? >> 8)' "$@"
  }
  _boardfix cycle
  sqlite3 "$kb/cycle/kanban.db" "
    INSERT INTO tasks (id, title, assignee, status, created_at) VALUES
      ('t_c0', 'CHUNK-1: blocked',  'forge-codex-lane', 'blocked', 1785200000),
      ('t_c1', 'CHUNK-2: in a loop', 'forge-codex-lane', 'todo',    1785200000),
      ('t_c2', 'CHUNK-3: in a loop', 'forge-codex-lane', 'todo',    1785200000);
    INSERT INTO task_links (parent_id, child_id) VALUES ('t_c0', 't_c1'), ('t_c1', 't_c2'), ('t_c2', 't_c1');
    INSERT INTO task_events (task_id, kind, payload, created_at)
      VALUES ('t_c0', 'blocked', json_object('reason', 'env: a tool is missing'), 1785200000);" >/dev/null 2>&1
  out="$(_with_timeout 20 env TZ=UTC HERMES_HOME="$root/hermes" "$REPO_ROOT/$ds" --board cycle --day 2026-07-28 2>/dev/null)"; rc=$?
  if [ "$rc" = 0 ] \
     && printf '%s\n' "$out" | grep -qxF 'Waiting on parents: 2 cards (all behind the cards waiting on you, so they start only after you act).'; then
    ok "what-to-do-survives-a-parent-cycle (two cards linked in a loop behind a blocked one: the digest ends, rc 0, and counts both once)"
  else
    bad "what-to-do-survives-a-parent-cycle" "rc=$rc (142 = killed by the 20s watchdog: the walk down the links did not end); got: $(printf '%s' "$out" | grep '^Waiting on parents' | head -2)"
  fi
  rm -rf "$kb/cycle"

  # (b) The order of the steps, and (c) the wording for several cards of one kind.
  # Nine waiting cards of eight kinds, six shown: a gate first, then the merge,
  # the bounce-budget hold, the human chunk, the returned chunk, the blocked
  # cards; the unrecognised one and the triage card are the two left over.
  _boardfix mixed
  local mx_gate mx_hold
  mx_gate="$(bash -c '. scripts/decision-message.sh && decision_message milestone-gate "GATE-M1 holds milestone M1" "means" "run its probe with \`probe-cmd GATE-M1\` and decide" "risk" "reply"' | sed "s/'/''/g")"
  mx_hold="$(bash -c '. scripts/decision-message.sh && printf %s "$INTERACTIVE_HOLD_REASON"' | sed "s/'/''/g")"
  sqlite3 "$kb/mixed/kanban.db" "
    INSERT INTO tasks (id, title, assignee, status, created_at) VALUES
      ('t_o1', 'CHUNK-1: verified',      'forge-verifier',         'blocked', 1785200000),
      ('t_o2', 'GATE-M1: Milestone 1',   NULL,                     'blocked', 1785200000),
      ('t_o3', 'CHUNK-3: not converging', 'forge-verifier',        'blocked', 1785200000),
      ('t_o4', 'CHUNK-5: a human chunk', NULL,                     'blocked', 1785200000),
      ('t_o5', 'CHUNK-6: sent back',     'forge-operator-handoff', 'ready',   1785200000),
      ('t_o6', 'CHUNK-7: first env',     'forge-codex-lane',       'blocked', 1785200000),
      ('t_o7', 'CHUNK-8: second env',    'forge-codex-lane',       'blocked', 1785200000),
      ('t_o8', 'CHUNK-9: odd',           'forge-codex-lane',       'blocked', 1785200000),
      ('t_o9', 'follow-up: a nit',       NULL,                     'triage',  1785200000);
    INSERT INTO task_events (task_id, kind, payload, created_at) VALUES
      ('t_o1', 'blocked', json_object('reason', 'merge-pending: verified'), 1785200000),
      ('t_o2', 'blocked', json_object('reason', '$mx_gate'), 1785200000),
      ('t_o3', 'blocked', json_object('reason', 'bounce-budget: no convergence'), 1785200000),
      ('t_o4', 'blocked', json_object('reason', '$mx_hold'), 1785200000),
      ('t_o6', 'blocked', json_object('reason', 'env: first problem'), 1785200000),
      ('t_o7', 'blocked', json_object('reason', 'env: second problem'), 1785200000),
      ('t_o8', 'blocked', json_object('reason', 'something odd with no class'), 1785200000);" >/dev/null 2>&1
  out="$(_dg --board mixed --day 2026-07-28 2>/dev/null)"; rc=$?
  wd_do="$(printf '%s\n' "$out" | _section 'What to do')"; wd_means="$(printf '%s\n' "$out" | _section 'Where this board stands')"
  all_do="$all_do
$wd_do"
  local mx_order
  mx_order="$(printf '%s\n' "$wd_do" | sed -n 's/^[0-9]\. [^(]*(\(t_o[0-9]\)):.*/\1/p' | tr '\n' ' ')"
  if [ "$rc" = 0 ] && [ "$mx_order" = 't_o2 t_o1 t_o3 t_o4 t_o5 t_o6 ' ] \
     && printf '%s\n' "$wd_do" | tail -1 | grep -qxF '…and 3 more waiting cards; the cards above have their own Reply lines.' \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 2 blocked by env: first problem (and 1 like it); they hold, with their children, until you fix the cause and unblock.' \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 1 stopped for an unrecognised reason; read it with `hermes kanban --board mixed show t_o8`.' \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 1 chunk the verifier bounced without converging; held, with their children, until you decide.' \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 1 chunk for you to implement; nothing is built until you start.' \
     && printf '%s\n' "$wd_means" | grep -qxF '  · 1 human chunk sent back for changes; their children and milestone gate wait.'; then
    ok "what-to-do-orders-its-steps (gate, merge, bounce-budget, interactive, returned, blocked; three left to a count) and the-kinds-are-worded-for-several-cards"
  else
    bad "what-to-do-orders-its-steps" "rc=$rc order='$mx_order' want 't_o2 t_o1 t_o3 t_o4 t_o5 t_o6 '; means: $(printf '%s' "$wd_means" | tr '\n' '|' | head -c 900)"
  fi
  rm -rf "$kb/mixed"

  # The gate's wording must hold for the gates the digest really shows: one whose
  # chunks are archived rather than done, and one that closes no chunk at all.
  _boardfix gatewords
  sqlite3 "$kb/gatewords/kanban.db" "
    INSERT INTO tasks (id, title, assignee, status, created_at) VALUES
      ('t_w1', 'CHUNK-1: archived', 'forge-verifier', 'archived', 1785200000),
      ('t_w2', 'GATE-M1: after an archived chunk', NULL, 'blocked', 1785200000),
      ('t_w3', 'GATE-M2: closes no chunk',        NULL, 'blocked', 1785200000),
      ('t_w4', 'CHUNK-2: still open',  'forge-codex-lane', 'running', 1785200000),
      ('t_w5', 'GATE-M3: held on an open chunk', NULL, 'blocked', 1785200000);
    INSERT INTO task_links (parent_id, child_id) VALUES ('t_w1', 't_w2'), ('t_w4', 't_w5');
    INSERT INTO task_events (task_id, kind, payload, created_at) VALUES
      ('t_w2', 'blocked', json_object('reason', '$mx_gate'), 1785200000),
      ('t_w3', 'blocked', json_object('reason', '$mx_gate'), 1785200000),
      ('t_w5', 'blocked', json_object('reason', '$mx_gate'), 1785200000);" >/dev/null 2>&1
  out="$(_dg --board gatewords --day 2026-07-28 2>/dev/null)"; rc=$?
  wd_do="$(printf '%s\n' "$out" | _section 'What to do')"
  if [ "$rc" = 0 ] \
     && printf '%s\n' "$wd_do" | grep -qxF '1. GATE-M1 (t_w2): no chunk it closes is still open, so probe the milestone:' \
     && printf '%s\n' "$wd_do" | grep -qxF '2. GATE-M2 (t_w3): no chunk it closes is still open, so probe the milestone:' \
     && [ "$(printf '%s\n' "$wd_do" | grep -c '^[0-9]\. ')" = 2 ] \
     && ! printf '%s\n' "$wd_do" | grep -q 'are done'; then
    ok "what-to-do-gate-wording-holds-for-archived-and-parentless-gates (a gate behind an archived chunk and one behind none get the accurate wording; one behind an open chunk gets no step)"
  else
    bad "what-to-do-gate-wording-holds-for-archived-and-parentless-gates" "rc=$rc; got: $(printf '%s' "$wd_do" | tr '\n' '|' | head -c 600)"
  fi
  rm -rf "$kb/gatewords"

  # Six gates waiting at once (more than a run will ever have): the two sections
  # still fit one Telegram chunk (4096 UTF-16 units; they are BMP-only here) and
  # list every probe. The whole message cannot: six verbatim holds are ~7 KB,
  # which Hermes sends as several messages (epic GW2).
  _boardfix gates6
  local gi gr
  for gi in 1 2 3 4 5 6; do
    gr="$(bash -c '. scripts/decision-message.sh && decision_message milestone-gate "GATE-M$1 holds milestone M$1'"'"'s successors until you complete it" "every chunk that depends on this gate waits, by the board'"'"'s own parent rule, until the gate is done" "once every chunk of M$1 is merged, run its probe (tests/probes/gate_m$1.json) with \`~/.forge/repo/scripts/probe-run.sh '"'"'/Users/goonlab/dev/the-product'"'"' GATE-M$1\` and decide whether M$1 is done — exit 0 passes, 1 is a finding, 2 is no verdict; until then there is nothing to decide" "completing it early starts the next milestone on work nobody has probed" "reply"' _ "$gi" | sed "s/'/''/g")"
    sqlite3 "$kb/gates6/kanban.db" "INSERT INTO tasks (id, title, status, created_at) VALUES ('t_y$gi', 'GATE-M$gi: Milestone $gi', 'blocked', 1785200000);
      INSERT INTO task_events (task_id, kind, payload, created_at) VALUES ('t_y$gi', 'blocked', json_object('reason', '$gr'), 1785200000);" >/dev/null 2>&1
  done
  out="$(_dg --board gates6 --day 2026-07-28 2>/dev/null)"; rc=$?
  local g6_len
  g6_len="$(printf '%s\n' "$out" | awk '/^Where this board stands$/{f=1} /^Spend:/{f=0} f' | wc -m | tr -d ' ')"
  if [ "$rc" = 0 ] && [ "$g6_len" -gt 1500 ] && [ "$g6_len" -lt 4096 ] \
     && [ "$(printf '%s\n' "$out" | grep -c 'probe-run.sh .*/Users/goonlab/dev/the-product. GATE-M[1-6]`$')" = 6 ]; then
    ok "what-to-do-stays-phone-sized-for-six-gates ($g6_len characters for both sections, under one 4096-unit Telegram chunk, with all six probes)"
  else
    bad "what-to-do-stays-phone-sized-for-six-gates" "rc=$rc sections=$g6_len characters (want 1500..4095), probes=$(printf '%s\n' "$out" | grep -c 'probe-run.sh')"
  fi
  rm -rf "$kb/gates6"

  # Every command the section names carries its board: one without lands on the
  # wrong board. The fixture message's own sections count too. Zero commands
  # found is blind, not a pass.
  all_do="$all_do
$(_section 'What to do' < "$root/out.txt")"
  local cmds_total cmds_bare
  cmds_total="$(printf '%s\n' "$all_do" | grep -o 'hermes kanban [^ `]*' | grep -c .)"
  cmds_bare="$(printf '%s\n' "$all_do" | grep -o 'hermes kanban [^ `]*' | grep -vc '^hermes kanban --board$')"
  if [ "$cmds_total" -ge 8 ] && [ "$cmds_bare" = 0 ] \
     && ! printf '%s\n' "$all_do" | grep -oE 'hermes kanban --board [^ ]+ ' | grep -qE 'board (<|--)'; then
    ok "what-to-do-is-board-qualified ($cmds_total commands, each with --board <name>)"
  else
    bad "what-to-do-is-board-qualified" "commands=$cmds_total without --board=$cmds_bare"
  fi
  rm -rf "$kb/todogate" "$kb/nothing" "$kb/moving" "$kb/stalled" "$kb/blocked" "$kb/many"

  if detail="$(decision_classes_diagnostic scripts/decision-message.sh)"; then
    ok "every-block-class-has-a-decision ($(bash -c '. scripts/decision-message.sh && decision_classes' | grep -c .) classes)"
  else
    bad "every-block-class-has-a-decision" "$detail"
  fi
  # The mutant: the same formatter with the `ci-red` entry deleted.
  awk '/^    ci-red\) printf/{skip=1} skip && /;;$/{skip=0; next} !skip' scripts/decision-message.sh > "$root/dm-mutant.sh"
  if detail="$(decision_classes_diagnostic "$root/dm-mutant.sh")"; then
    bad "a-missing-decision-is-caught" "a formatter with no ci-red entry passed"
  elif printf '%s' "$detail" | grep -q 'registered with no decision: ci-red'; then
    ok "a-missing-decision-is-caught"
  else
    bad "a-missing-decision-is-caught" "the mutant reddened for the wrong reason: $detail"
  fi

  # ONE FORMATTER. Each producer that speaks to the operator sources it, and no
  # file under scripts/ defines its own copy. Zero producers found is a fail.
  local p found=0 defs
  detail=""
  for p in scripts/prejudge-review.sh scripts/merge-watcher.sh scripts/digest.sh hermes/board-bootstrap.sh; do
    [ -f "$p" ] || { detail="$detail $p-missing"; continue; }
    found=$((found + 1))
    grep -Eq '^[[:space:]]*\. "?\$[^"]*/decision-message\.sh"?' "$p" \
      || detail="$detail $p-does-not-source-the-formatter"
  done
  [ "$found" -gt 0 ] || detail="$detail no-producer-found"
  defs="$(grep -lE '^[[:space:]]*decision_message\(\)' scripts/*.sh 2>/dev/null | grep -v '^scripts/decision-message.sh$' | tr '\n' ' ')"
  [ -z "$defs" ] || detail="$detail second-definition-in:$defs"
  [ -z "$detail" ] \
    && ok "one-formatter ($found producers source scripts/decision-message.sh)" \
    || bad "one-formatter" "every message to the operator goes through one formatter —$detail"

  # CRON RUNS A SYMLINK. `hermes cron --script` takes a path under
  # ~/.hermes/scripts/, and the operator's step for both cron jobs is a symlink
  # there to ~/.forge/repo/scripts/<name>. A script that finds its siblings by
  # `dirname "${BASH_SOURCE[0]}"` then looks in ~/.hermes/scripts/ — and since
  # GW1 both of these source decision-message.sh, so the first deploy would have
  # silently killed the live watcher. Every other case runs them by their real
  # path, which is exactly why none of them could see it.
  local cron="$root/cron-scripts" cstub="$root/cron-stub"
  mkdir -p "$cron" "$cstub"
  ln -sf "$REPO_ROOT/scripts/digest.sh" "$cron/forge-digest.sh"
  ln -sf "$REPO_ROOT/scripts/merge-watcher.sh" "$cron/forge-merge-watcher.sh"
  # hermes lists one board with no held card on it; gh is never reached.
  cat > "$cstub/hermes" <<'CRON_STUB'
#!/usr/bin/env bash
case "$*" in *"boards list"*) echo '[{"slug":"cron-lab"}]';; *) echo '[]';; esac
CRON_STUB
  printf '#!/usr/bin/env bash\nexit 0\n' > "$cstub/gh"
  chmod +x "$cstub/hermes" "$cstub/gh"
  detail=""
  out="$(cd "$root" && TZ=UTC HERMES_HOME="$root/hermes" bash "$cron/forge-digest.sh" --day 2026-07-28 2>"$root/cron.err")"; rc=$?
  { [ "$rc" = 0 ] && [ "$out" = "$(cat scripts/fixtures/digest-expected.txt)" ]; } \
    || detail="$detail digest-through-a-symlink(rc=$rc,$(head -1 "$root/cron.err"))"
  out="$(cd "$root" && PATH="$cstub:$PATH" bash "$cron/forge-merge-watcher.sh" 2>"$root/cron.err")"; rc=$?
  { [ "$rc" = 0 ] && [ -z "$out" ]; } \
    || detail="$detail merge-watcher-through-a-symlink(rc=$rc,$(head -1 "$root/cron.err"))"
  [ -z "$detail" ] \
    && ok "cron-symlinks-reach-their-siblings" \
    || bad "cron-symlinks-reach-their-siblings" "a cron job runs the script through a symlink, so it must find its siblings beside the symlink's TARGET —$detail"

  # DORMANT BOARDS. A board nobody has touched for FORGE_DIGEST_DORMANT_DAYS (14)
  # before the END of the digest day collapses to one line at the end of the
  # message. Every time here is derived from the pinned --day, never the clock, so
  # the boundary is the same on every date. The boards are synthetic and live in
  # their own HERMES_HOME, so the shared fixture boards above cannot interfere.
  local dh="$root/dormant/hermes" dk="$root/dormant/hermes/kanban/boards" dday=2026-07-28
  local d_end d_cut d_old
  d_end="$(TZ=UTC sqlite3 :memory: "SELECT strftime('%s','$dday','+1 day','utc');")"
  d_cut=$((d_end - 14 * 86400))             # exactly 14 days before the end of the day
  d_old=$((d_cut - 40 * 86400 + 43200))     # 2026-06-05 12:00 UTC: long untouched
  _dgd() { TZ=UTC HERMES_HOME="$dh" "$REPO_ROOT/$ds" --day "$dday" "$@"; }
  # $1=slug $2=time of the board's newest (and only) event $3...=one card per status.
  # A blocked card carries a lane-block reason, so it is waiting on the operator.
  _dormant_board() {
    local slug="$1" at="$2" st n=0 sql="DELETE FROM tasks; DELETE FROM task_events; DELETE FROM task_runs; DELETE FROM task_links;"
    shift 2
    mkdir -p "$dk/$slug"
    sqlite3 "$dk/$slug/kanban.db" < scripts/fixtures/digest-board.sql >/dev/null 2>&1
    for st in "$@"; do
      n=$((n + 1))
      sql="$sql INSERT INTO tasks (id, title, assignee, status, created_at) VALUES ('t_${slug}_$n', 'CHUNK-$n: synthetic card', 'forge-codex-lane', '$st', $at);"
      if [ "$st" = blocked ]; then
        sql="$sql INSERT INTO task_events (task_id, kind, payload, created_at) VALUES ('t_${slug}_$n', 'blocked', '{\"reason\":\"ci-red: make check is red after codex\",\"kind\":\"needs_input\"}', $at);"
      else
        sql="$sql INSERT INTO task_events (task_id, kind, payload, created_at) VALUES ('t_${slug}_$n', 'created', NULL, $at);"
      fi
    done
    sqlite3 "$dk/$slug/kanban.db" "$sql" >/dev/null 2>&1
  }
  # The one line a dormant board gets. $1=slug $2=what is open $3=date of its newest event
  _dormant_line() {
    printf -- '- %s: %s, last activity %s — full view: `~/.forge/repo/scripts/digest.sh --board %s`; archive it: `hermes kanban boards rm %s`' \
      "$1" "$2" "$3" "$1" "$1"
  }
  local d_head="Forge digest — $dday" d_sec="Dormant boards (1) — untouched for 14+ days, nothing running"
  local d_active d_expect d_note d_tail d_val rc2

  # 1. A dormant board collapses to its one line, at the end, after an active board
  # that renders exactly as it does under --board (which never collapses).
  rm -rf "$root/dormant"; mkdir -p "$dk"
  _dormant_board active-board $((d_end - 3600)) blocked
  _dormant_board stale-board "$d_old" blocked blocked todo
  d_active="$(_dgd --board active-board 2>/dev/null)"
  d_expect="$d_active"$'\n\n'"$d_sec"$'\n'"$(_dormant_line stale-board '2 waiting on you, 1 not started' 2026-06-05)"
  out="$(_dgd 2>"$root/err")"; rc=$?
  detail=""
  { [ "$rc" = 0 ] && [ "$out" = "$d_expect" ]; } \
    || detail="$detail active-then-one-dormant-line(rc=$rc: $(printf '%s' "$out" | grep -E '^(== |Dormant|- stale)' | cut -c1-60 | tr '\n' '|'))"
  printf '%s' "$d_active" | grep -q '^== active-board ==' && printf '%s' "$d_active" | grep -q '^Decision needed: ' \
    || detail="$detail the-active-board-was-not-rendered-in-full"
  # With no active board the message is the header line and the dormant section.
  rm -rf "$dk/active-board"
  out="$(_dgd 2>/dev/null)"; rc=$?
  { [ "$rc" = 0 ] && [ "$out" = "$d_head"$'\n\n'"$d_sec"$'\n'"$(_dormant_line stale-board '2 waiting on you, 1 not started' 2026-06-05)" ]; } \
    || detail="$detail all-dormant-is-header-plus-section(rc=$rc: $(printf '%s' "$out" | head -4 | cut -c1-60 | tr '\n' '|'))"
  # The archive verb is a real one: named in a message to the operator, so asked of the CLI when there is one.
  d_note="archive verb not checked: no hermes on PATH"
  if command -v hermes >/dev/null 2>&1; then
    hermes kanban boards --help 2>&1 | grep -Eq '[{,]rm[,}]' \
      && d_note="archive verb confirmed by the live hermes --help" \
      || detail="$detail hermes-kanban-boards-rm-is-not-a-command"
  fi
  [ -z "$detail" ] \
    && ok "dormant-board-collapses-to-one-line-at-the-end (active board in full first, header plus section when all are dormant; $d_note)" \
    || bad "dormant-board-collapses-to-one-line-at-the-end" "a board untouched past the window must be one line after every active board —$detail"

  # 2. The boundary and the overrides. Newest event 60s inside the 14 days: in
  # full. 60s outside: one line. A running card, or one in review, keeps a board
  # in full however old its events. --board and FORGE_DIGEST_DORMANT_DAYS=0 give
  # back one full block per board.
  rm -rf "$root/dormant"; mkdir -p "$dk"
  _dormant_board edge-inside $((d_cut + 60)) blocked
  _dormant_board edge-outside $((d_cut - 60)) blocked
  _dormant_board old-review "$d_old" review
  _dormant_board old-running "$d_old" running
  detail=""
  out="$(_dgd 2>/dev/null)"; rc=$?
  d_expect="$(_dgd --board edge-inside --board old-review --board old-running 2>/dev/null)"$'\n\n'"$d_sec"$'\n'"$(_dormant_line edge-outside '1 waiting on you' 2026-07-14)"
  { [ "$rc" = 0 ] && [ "$out" = "$d_expect" ]; } \
    || detail="$detail boundary(rc=$rc: $(printf '%s' "$out" | grep -E '^(== |Dormant|- edge)' | cut -c1-40 | tr '\n' '|'))"
  out="$(_dgd --board edge-outside 2>/dev/null)"
  { printf '%s' "$out" | grep -q '^== edge-outside ==' && ! printf '%s' "$out" | grep -q '^Dormant boards'; } \
    || detail="$detail an-explicit-board-must-render-in-full"
  d_expect="$(_dgd --board edge-inside --board edge-outside --board old-review --board old-running 2>/dev/null)"
  for d_val in 0 soon; do
    out="$(FORGE_DIGEST_DORMANT_DAYS=$d_val _dgd 2>/dev/null)"
    [ "$out" = "$d_expect" ] && ! printf '%s' "$out" | grep -q '^Dormant boards' \
      || detail="$detail DORMANT_DAYS=$d_val-must-give-one-full-block-per-board"
  done
  out="$(FORGE_DIGEST_DORMANT_DAYS=13 _dgd 2>/dev/null)"
  printf '%s' "$out" | grep -qF 'Dormant boards (2) — untouched for 13+ days, nothing running' \
    || detail="$detail DORMANT_DAYS=13-must-move-the-window"
  [ -z "$detail" ] \
    && ok "dormancy-boundary-and-overrides (60s either side of 14 days, a running and a review card, --board, FORGE_DIGEST_DORMANT_DAYS 0/soon/13)" \
    || bad "dormancy-boundary-and-overrides" "the window is 14 days before the end of --day; running, review and named boards are never collapsed; 0 or a non-number restores today's output —$detail"

  # 3. A board that cannot be read is never dormant: it keeps its UNREADABLE
  # block and the exit 3, and is not one of the dormant lines.
  rm -rf "$root/dormant"; mkdir -p "$dk/broken"
  printf 'not sqlite\n' > "$dk/broken/kanban.db"
  _dormant_board stale-board "$d_old" blocked
  detail=""
  out="$(_dgd 2>/dev/null)"; rc=$?
  d_tail="$(printf '%s\n' "$out" | sed -n '/^Dormant boards/,$p')"
  { [ "$rc" = 3 ] && printf '%s\n' "$out" | grep -q '^== broken ==' && printf '%s\n' "$out" | grep -q '^UNREADABLE' \
    && [ "$d_tail" = "$d_sec"$'\n'"$(_dormant_line stale-board '1 waiting on you' 2026-06-05)" ]; } \
    || detail="$detail unreadable-beside-a-dormant-board(rc=$rc: $(printf '%s' "$out" | grep -E '^(== |UNREADABLE|Dormant|- )' | cut -c1-40 | tr '\n' '|'))"
  rm -rf "$dk/stale-board"
  out="$(_dgd 2>/dev/null)"; rc2=$?
  { [ "$rc2" = 3 ] && printf '%s\n' "$out" | grep -q '^UNREADABLE' && ! printf '%s\n' "$out" | grep -q '^Dormant boards'; } \
    || detail="$detail unreadable-alone(rc=$rc2: $(printf '%s' "$out" | head -4 | cut -c1-40 | tr '\n' '|'))"
  [ -z "$detail" ] \
    && ok "an-unreadable-board-is-never-dormant (still named UNREADABLE with exit 3, beside a dormant board and alone)" \
    || bad "an-unreadable-board-is-never-dormant" "a board that could not be read is not a quiet or dormant board —$detail"
  rm -rf "$root/dormant"
}
wants digest    && run_digest_group

# ---------------------------------------------------------------------------
# watchdog/ — the liveness watchdog (scripts/watchdog.sh) as a program, its installer, and the two preflight checks
# that came with it.
#
# Two things went wrong in November 2026 and nothing reported either: the gateway was down for days (and nothing on the
# host can report that, FileVault being on), and the kernel's auto-decomposer woke up and turned parked triage cards
# into dispatched workers (docs/hermes-field-notes.md). Every case here runs the real script against a stubbed
# launchctl and a stubbed curl, in a temp HERMES_HOME and a temp state root, under a PINNED clock: the output files are
# touched to fixed times and FORGE_WATCHDOG_NOW is set from their real mtimes, never from the wall clock. Nothing here
# reaches Telegram, a heartbeat URL, the operator's ~/.hermes or ~/.forge, or a real launchd.
#
# WD_SCRIPTS and WD_PREFLIGHT aim the group at a COPY of the scripts, which is how each case was made to fail once
# against a deliberately broken script without editing a tracked file.
# ---------------------------------------------------------------------------
run_watchdog_group() {
  group watchdog
  command -v jq >/dev/null 2>&1 || { skip "healthy-pings-the-heartbeat-and-stays-quiet" "jq not on PATH"; return; }
  local wds="${WD_SCRIPTS:-$REPO_ROOT/scripts}" wdp="${WD_PREFLIGHT:-$REPO_ROOT/scripts/preflight.sh}" root="$TMPROOT/watchdog"
  local TOK="7000001:TEST-token_ABCdef" HB="https://hc.example.test/ping/00000000-test-heartbeat-secret"
  local W NOW wdout wdrc WD_X="" WD_BASHFLAGS="" WD_BARE=0
  mkdir -p "$root"

  _wd_mtime() { local m; m="$(stat -c %Y "$1" 2>/dev/null)" || m=""; case "$m" in ''|*[!0-9]*) m="$(stat -f %m "$1" 2>/dev/null)";; esac; printf '%s' "$m"; }
  _wd_n() { local n; n="$(grep -c "^$1\$" "$W/stub/curl.log" 2>/dev/null)"; printf '%s' "${n:-0}"; }
  # A host: a Hermes home whose cron has run (the digest at 09:00, the ticker at 13:00 on 2026-11-13), the kernel
  # setting off, a bot token, a heartbeat URL, a gateway that is up and a Telegram that answers. NOW is ten minutes
  # after the ticker's last output.
  _wd_world() { # name
    local h
    W="$root/$1"; h="$W/hermes"; rm -rf "$W"
    mkdir -p "$W/home" "$h/cron/output/mw1" "$h/cron/output/dg1" "$W/state" "$W/bin" "$W/stub"
    printf '{"jobs":[{"id":"zz9","name":"hermes-daily-watch"},{"id":"mw1","name":"forge-merge-watcher"},{"id":"dg1","name":"forge-digest"}]}\n' > "$h/cron/jobs.json"
    : > "$h/cron/output/mw1/2026-11-13_13-00-00.md"; : > "$h/cron/output/dg1/2026-11-13_09-00-00.md"
    touch -t 202611131300 "$h/cron/output/mw1/2026-11-13_13-00-00.md"; touch -t 202611130900 "$h/cron/output/dg1/2026-11-13_09-00-00.md"
    printf 'kanban:\n  dispatch_in_gateway: true\n  auto_decompose: false\n  max_in_progress: 1\n' > "$h/config.yaml"
    printf 'TELEGRAM_BOT_TOKEN=%s\nTELEGRAM_HOME_CHANNEL=-1001234567\n' "$TOK" > "$h/.env"
    printf 'FORGE_HEARTBEAT_URL=%s\n' "$HB" > "$W/state/watchdog.env"
    cat > "$W/bin/launchctl" <<'WD_LAUNCHCTL'
#!/bin/sh
# stub: records every call; answers `print` from the mode file
echo "$*" >> "$WD_STUB_DIR/launchctl.calls"
case "$1" in
  print)
    case "$(cat "$WD_STUB_DIR/launchctl.mode" 2>/dev/null || echo running)" in
      running) printf 'gui/501/ai.hermes.gateway = {\n\tactive count = 1\n\tstate = running\n}\n';;
      stopped) printf 'gui/501/ai.hermes.gateway = {\n\tactive count = 0\n\tstate = not running\n}\n';;
      nostate) printf 'gui/501/ai.hermes.gateway = {\n\tactive count = 0\n}\n';;
      *) echo 'Could not find service "ai.hermes.gateway" in domain for user gui: 501' >&2; exit 113;;
    esac;;
  bootstrap) [ "$(cat "$WD_STUB_DIR/launchctl.bootstrap" 2>/dev/null || echo ok)" = ok ] || { echo "Bootstrap failed: 5: Input/output error" >&2; exit 5; };;
esac
exit 0
WD_LAUNCHCTL
    cat > "$W/bin/curl" <<'WD_CURL'
#!/bin/sh
# stub: records argv, environment and stdin of every call apart; tells a Telegram send from a heartbeat by its stdin
d="$WD_STUB_DIR"
n=$(cat "$d/count" 2>/dev/null || echo 0); n=$((n + 1)); echo "$n" > "$d/count"
printf '%s\n' "$@" > "$d/call.$n.argv"
env > "$d/call.$n.env"
cat > "$d/call.$n.stdin"
if grep -q 'sendMessage' "$d/call.$n.stdin"; then
  echo telegram >> "$d/curl.log"
  case "$(cat "$d/telegram.mode" 2>/dev/null || echo ok)" in
    ok) printf '{"ok":true,"result":{}}\n200';;
    401) printf '{"ok":false,"error_code":401}\n401';;
    *) exit 6;;
  esac
else
  echo heartbeat >> "$d/curl.log"
  [ "$(cat "$d/heartbeat.mode" 2>/dev/null || echo ok)" = ok ] || exit 22
fi
exit 0
WD_CURL
    chmod +x "$W/bin/launchctl" "$W/bin/curl"
    echo running > "$W/stub/launchctl.mode"; echo ok > "$W/stub/telegram.mode"
    NOW=$(( $(_wd_mtime "$h/cron/output/mw1/2026-11-13_13-00-00.md") + 600 ))
    WD_X=""; WD_BASHFLAGS=""; WD_BARE=0
  }
  _wd_run() { # args for watchdog.sh; WD_X holds extra NAME=value words -> wdout, wdrc (stdout and stderr both kept, appended)
    local pathv="$PATH"
    [ "$WD_BARE" = 1 ] && pathv=/usr/bin:/bin
    if [ "$WD_BARE" = 1 ]; then
      wdout="$(env -i PATH="$pathv" HOME="$W/home" HERMES_HOME="$W/hermes" FORGE_STATE_ROOT="$W/state" FORGE_WATCHDOG_NOW="$NOW" \
        FORGE_WATCHDOG_LAUNCHCTL="$W/bin/launchctl" FORGE_WATCHDOG_CURL="$W/bin/curl" WD_STUB_DIR="$W/stub" $WD_X \
        /bin/bash $WD_BASHFLAGS "$wds/watchdog.sh" "$@" 2>>"$W/stderr")"; wdrc=$?
    else
      wdout="$(env -u FORGE_WATCHDOG_TICK_MAX_MIN -u FORGE_WATCHDOG_REMIND_HOURS -u FORGE_WATCHDOG_ROOT -u HERMES_KANBAN_BOARD \
        HOME="$W/home" HERMES_HOME="$W/hermes" FORGE_STATE_ROOT="$W/state" FORGE_WATCHDOG_NOW="$NOW" \
        FORGE_WATCHDOG_LAUNCHCTL="$W/bin/launchctl" FORGE_WATCHDOG_CURL="$W/bin/curl" WD_STUB_DIR="$W/stub" $WD_X \
        /bin/bash $WD_BASHFLAGS "$wds/watchdog.sh" "$@" 2>>"$W/stderr")"; wdrc=$?
    fi
    printf '%s\n' "$wdout" >> "$W/stdout.txt"
  }
  _wd_line() { printf '%s\n' "$wdout" | grep -E "^$1 +$2 " | head -n 1; }
  _wd_state() { jq -r '[.observed, .alerted, (.alerted_at | tostring)] | join(" ")' "$W/state/watchdog/state.json" 2>/dev/null; }
  _wd_leaks() { # needle -> the places it appears that it must not
    local needle="$1" f out=""
    for f in "$W"/stub/call.*.argv "$W"/stub/call.*.env "$W/stub/launchctl.calls" "$W/state/watchdog/state.json" "$W/stdout.txt" "$W/stderr"; do
      [ -f "$f" ] && grep -qF -- "$needle" "$f" && out="$out ${f##*/}"
    done
    printf '%s' "$out"
  }
  local d

  # --- healthy: exit 0, one heartbeat, no alert -----------------------------------------------------------------------
  d=""; _wd_world healthy
  _wd_run
  [ "$wdrc" = 0 ] || d="$d exit=$wdrc"
  [ "$(printf '%s\n' "$wdout" | grep -c '^OK ')" = 4 ] || d="$d not-four-OK-lines"
  ! printf '%s\n' "$wdout" | grep -q '^FAIL' || d="$d a-FAIL-line"
  [ "$(_wd_n heartbeat)" = 1 ] || d="$d heartbeats=$(_wd_n heartbeat)"
  [ "$(_wd_n telegram)" = 0 ] || d="$d alerts=$(_wd_n telegram)"
  [ "$(_wd_state | cut -d' ' -f1,2)" = "healthy healthy" ] || d="$d state=$(_wd_state)"
  # The same pass under the PATH launchd gives a LaunchAgent (jq is found in the Homebrew dirs the script appends).
  if [ -x /usr/bin/jq ] || [ -x /bin/jq ] || [ -x /opt/homebrew/bin/jq ] || [ -x /usr/local/bin/jq ]; then
    WD_BARE=1; _wd_run; WD_BARE=0
    { [ "$wdrc" = 0 ] && [ "$(_wd_n heartbeat)" = 2 ] && [ "$(_wd_n telegram)" = 0 ]; } || d="$d bare-path(exit=$wdrc heartbeats=$(_wd_n heartbeat))"
  fi
  [ -z "$d" ] && ok "healthy-pings-the-heartbeat-and-stays-quiet (four OK lines, exit 0, one heartbeat per healthy pass including under launchd's bare PATH, no alert, state healthy)" \
    || bad "healthy-pings-the-heartbeat-and-stays-quiet" "a healthy host exits 0, pings once and says nothing —$d (output: $(printf '%s' "$wdout" | head -12 | tr '\n' '|' | cut -c1-500))"

  # --- a dead gateway: one alert, no repeat, a reminder after the interval, one recovery, no ping while down ----------
  d=""; _wd_world lifecycle
  local t0="$NOW"
  WD_X="FORGE_WATCHDOG_TICK_MAX_MIN=2000"
  echo down > "$W/stub/launchctl.mode"
  _wd_run
  [ "$wdrc" = 1 ] || d="$d first-exit=$wdrc"
  [ -n "$(_wd_line FAIL gateway)" ] || d="$d no-FAIL-gateway-line"
  [ "$(_wd_n telegram)" = 1 ] || d="$d first-pass-alerts=$(_wd_n telegram)"
  grep -q 'UNHEALTHY' "$W"/stub/call.*.stdin 2>/dev/null && grep -q 'gateway' "$W"/stub/call.*.stdin 2>/dev/null || d="$d alert-does-not-name-the-gateway"
  [ "$(_wd_state | cut -d' ' -f1,2)" = "unhealthy unhealthy" ] || d="$d state-after-first=$(_wd_state)"
  NOW=$((t0 + 60)); _wd_run
  [ "$wdrc" = 1 ] && [ "$(_wd_n telegram)" = 1 ] || d="$d immediate-second-run(exit=$wdrc alerts=$(_wd_n telegram))"
  NOW=$((t0 + 6 * 3600 - 60)); _wd_run
  [ "$(_wd_n telegram)" = 1 ] || d="$d one-minute-before-the-interval(alerts=$(_wd_n telegram))"
  NOW=$((t0 + 6 * 3600)); _wd_run
  [ "$(_wd_n telegram)" = 2 ] || d="$d at-the-interval(alerts=$(_wd_n telegram))"
  grep -q 'still UNHEALTHY' "$W"/stub/call.2.stdin 2>/dev/null || d="$d reminder-is-not-worded-as-one"
  NOW=$((t0 + 6 * 3600 + 60)); _wd_run
  [ "$(_wd_n telegram)" = 2 ] || d="$d after-the-reminder(alerts=$(_wd_n telegram))"
  [ "$(_wd_n heartbeat)" = 0 ] || d="$d heartbeat-while-unhealthy($(_wd_n heartbeat))"
  echo running > "$W/stub/launchctl.mode"
  NOW=$((t0 + 6 * 3600 + 120)); _wd_run
  [ "$wdrc" = 0 ] || d="$d recovery-exit=$wdrc"
  [ "$(_wd_n telegram)" = 3 ] || d="$d recovery-alerts=$(_wd_n telegram)"
  grep -q 'healthy again' "$W"/stub/call.3.stdin 2>/dev/null || d="$d recovery-is-not-worded-as-one"
  [ "$(_wd_n heartbeat)" = 1 ] || d="$d heartbeat-at-recovery($(_wd_n heartbeat))"
  NOW=$((t0 + 6 * 3600 + 180)); _wd_run
  [ "$wdrc" = 0 ] && [ "$(_wd_n telegram)" = 3 ] && [ "$(_wd_n heartbeat)" = 2 ] || d="$d after-recovery(alerts=$(_wd_n telegram) heartbeats=$(_wd_n heartbeat))"
  [ -z "$d" ] && ok "gateway-down-alerts-once-and-recovers (exit 1 and one alert; the next run, and one a minute short of 6h, send nothing; the run at 6h sends one reminder; recovery sends exactly one message; no heartbeat while down, one per healthy pass after)" \
    || bad "gateway-down-alerts-once-and-recovers" "alerts follow state changes, not passes —$d"

  # --- a stopped or stateless gateway is not a running one -------------------------------------------------------------
  d=""; _wd_world gwstate
  echo stopped > "$W/stub/launchctl.mode"; _wd_run --no-alert
  { [ "$wdrc" = 1 ] && _wd_line FAIL gateway | grep -q 'not running'; } || d="$d loaded-not-running-was-not-a-fail(exit=$wdrc)"
  echo nostate > "$W/stub/launchctl.mode"; _wd_run --no-alert
  { [ "$wdrc" = 1 ] && _wd_line FAIL gateway | grep -q 'no state'; } || d="$d loaded-with-no-state-was-not-a-fail(exit=$wdrc)"
  echo down > "$W/stub/launchctl.mode"; _wd_run --no-alert
  { [ "$wdrc" = 1 ] && _wd_line FAIL gateway | grep -q 'not loaded'; } || d="$d not-loaded-was-not-a-fail(exit=$wdrc)"

  # --- a stale ticker and a stale digest each fail on their own line ---------------------------------------------------
  _wd_world stale
  local tick_m; tick_m="$(_wd_mtime "$W/hermes/cron/output/mw1/2026-11-13_13-00-00.md")"
  NOW=$((tick_m + 29 * 60)); _wd_run --no-alert
  { [ "$wdrc" = 0 ] && [ -n "$(_wd_line OK ticker)" ]; } || d="$d ticker-29m-old-failed(exit=$wdrc)"
  NOW=$((tick_m + 31 * 60)); _wd_run --no-alert
  { [ "$wdrc" = 1 ] && [ -n "$(_wd_line FAIL ticker)" ] && [ -n "$(_wd_line OK digest)" ] && [ -n "$(_wd_line OK gateway)" ] \
    && [ "$(printf '%s\n' "$wdout" | grep -c '^FAIL')" = 1 ]; } || d="$d stale-ticker(exit=$wdrc: $(printf '%s' "$wdout" | grep '^FAIL' | tr '\n' '|' | cut -c1-200))"
  WD_X="FORGE_WATCHDOG_TICK_MAX_MIN=60"; NOW=$((tick_m + 31 * 60)); _wd_run --no-alert
  [ -n "$(_wd_line OK ticker)" ] || d="$d the-ticker-limit-is-not-read-from-FORGE_WATCHDOG_TICK_MAX_MIN"
  WD_X=""
  touch -t 202611120700 "$W/hermes/cron/output/dg1/2026-11-13_09-00-00.md"
  NOW=$((tick_m + 600)); _wd_run --no-alert
  { [ "$wdrc" = 1 ] && [ -n "$(_wd_line FAIL digest)" ] && [ -n "$(_wd_line OK ticker)" ] && [ "$(printf '%s\n' "$wdout" | grep -c '^FAIL')" = 1 ]; } \
    || d="$d stale-digest(exit=$wdrc: $(printf '%s' "$wdout" | grep '^FAIL' | tr '\n' '|' | cut -c1-200))"
  touch -t 202611121400 "$W/hermes/cron/output/dg1/2026-11-13_09-00-00.md"
  _wd_run --no-alert
  [ -n "$(_wd_line OK digest)" ] || d="$d a-digest-23h-old-failed"
  # a job the cron does not have, and one that never wrote anything, are failures with their own words
  jq 'del(.jobs[] | select(.name == "forge-digest"))' "$W/hermes/cron/jobs.json" > "$W/jobs.tmp" && mv "$W/jobs.tmp" "$W/hermes/cron/jobs.json"
  _wd_run --no-alert
  _wd_line FAIL digest | grep -q 'no cron job named forge-digest' || d="$d a-missing-job-was-not-named"
  rm -f "$W/hermes/cron/output/mw1/"*
  _wd_run --no-alert
  _wd_line FAIL ticker | grep -q 'never written' || d="$d an-empty-output-directory-was-not-named"
  [ -z "$d" ] && ok "gateway-states-and-stale-cron-output-fail-on-their-own-lines (loaded-not-running, stateless and not-loaded gateways; a ticker 31m old fails and 29m passes, FORGE_WATCHDOG_TICK_MAX_MIN moves the limit; a digest 30h old fails and 23h passes; a missing job and an empty output directory are named)" \
