  # --- the kernel setting, read from the file ---------------------------------------------------------------------------
  d=""; _wd_world cfg
  local row label text want
  while IFS='|' read -r label text want; do
    [ -n "$label" ] || continue
    printf '%b' "$text" > "$W/hermes/config.yaml"
