    pf_row="$(_pf_wl 113)"; case "$pf_row" in "WARN the liveness watchdog LaunchAgent ai.forge.watchdog is not loaded"*"watchdog-install.sh"*) ;; *) d="$d an-unloaded-watchdog-did-not-warn($(printf '%s' "$pf_row" | tr '\n' '|' | cut -c1-200))";; esac
