import plistlib, sys
d = plistlib.load(open(sys.argv[1], "rb")); home = sys.argv[2]
want = {"Label": "ai.forge.watchdog", "StartInterval": 600, "RunAtLoad": True,
        "ProgramArguments": ["/bin/bash", home + "/.forge/repo/scripts/watchdog.sh"]}
