  [ -z "$ipl" ] || d="$d plist-wrong:$ipl"
  _wd_inst
  { [ "$wdrc" = 2 ] && printf '%s\n' "$wdout" | grep -q 'does not exist' && [ -z "$(ls -A "$H")" ] && [ ! -e "$lc" ]; } || d="$d install-without-the-runtime-script(exit=$wdrc)"
